//   đề 31–40 : giữa kì I, cuối kì I, giữa kì II, cuối kì II
//   đề 41–50 : tổng hợp cuối năm, ôn tập, chuyên đề, nâng cao/HSG

const KHTN6_EXAMS = [

/* ═══════════ ĐỀ 1 — GIỚI THIỆU VỀ KHTN. AN TOÀN TRONG PHÒNG THỰC HÀNH ═══════════ */
{
  id: 10651, title: 'Đề 1 · Giới thiệu về KHTN. An toàn trong phòng thực hành', time: 60,
  questions: [
    { sec: 'Khái niệm KHTN', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Khoa học tự nhiên là ngành khoa học nghiên cứu về:', opts: o4('các hiện tượng xã hội và đời sống con người', 'lịch sử hình thành và phát triển của loài người', 'các sự vật, hiện tượng và quy luật của thế giới tự nhiên', 'cách thức tổ chức sản xuất và kinh doanh hàng hóa'), ans: 'C', why: 'Khoa học tự nhiên nghiên cứu các sự vật, hiện tượng, quy luật tự nhiên và ảnh hưởng của chúng tới cuộc sống con người.' },
    { sec: 'Khái niệm KHTN', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Hoạt động nào sau đây KHÔNG được coi là nghiên cứu khoa học tự nhiên?', opts: o4('Nghiên cứu quá trình quang hợp của cây xanh', 'Tìm hiểu về sự nở vì nhiệt của chất rắn', 'Nghiên cứu sự biến đổi của các chất khi đun nóng', 'Nghiên cứu phong tục tập quán của một vùng miền'), ans: 'D', why: 'Phong tục tập quán là đối tượng của khoa học xã hội, không phải khoa học tự nhiên. Ba hoạt động còn lại lần lượt thuộc Sinh học, Vật lí và Hóa học.' },
    { sec: 'Phương pháp tìm hiểu tự nhiên', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Một bạn trồng hai chậu đậu giống hệt nhau, tưới nước như nhau; một chậu để ngoài sáng, một chậu để trong tối. Thí nghiệm này nhằm tìm hiểu ảnh hưởng của yếu tố nào?', opts: o4('Nước', 'Ánh sáng', 'Nhiệt độ', 'Loại đất trồng'), ans: 'B', why: 'Trong thí nghiệm có đối chứng, chỉ được thay đổi MỘT yếu tố, các yếu tố khác giữ như nhau. Ở đây hai chậu chỉ khác nhau về ánh sáng nên yếu tố đang được khảo sát là ánh sáng.' },
    { sec: 'An toàn thực hành', lvl: 'VD', name: 'Câu 4', pts: 1, text: 'Trong phòng thực hành, khi làm vỡ nhiệt kế thủy ngân, em cần làm gì đầu tiên?', opts: o4('Báo ngay cho giáo viên và không tự ý thu dọn', 'Dùng tay nhặt các hạt thủy ngân cho vào thùng rác', 'Dùng chổi quét thật nhanh rồi đổ xuống cống thoát nước', 'Mở quạt thổi thật mạnh cho thủy ngân bay đi hết'), ans: 'A', why: 'Thủy ngân rất độc và dễ bay hơi. Tuyệt đối không tự xử lí, càng không dùng tay không hay chổi quét; phải báo giáo viên để xử lí đúng quy trình.' },
    { sec: 'Kí hiệu cảnh báo', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Kí hiệu cảnh báo hình tam giác viền đen, nền vàng dùng để:', opts: o4('chỉ dẫn cách thực hiện thao tác', 'cấm thực hiện một việc nào đó', 'chỉ lối thoát hiểm khi có sự cố', 'cảnh báo về một nguy hiểm'), ans: 'D', why: 'Quy ước: hình tam giác nền vàng — cảnh báo nguy hiểm; hình tròn viền đỏ gạch chéo — cấm; hình vuông/chữ nhật nền xanh — chỉ dẫn hoặc lối thoát.' },
    { sec: 'An toàn thực hành', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Vì sao trong phòng thực hành KHÔNG được nếm thử hoặc ngửi trực tiếp hóa chất?', opts: o4('Vì nhiều hóa chất độc, có thể gây ngộ độc hoặc bỏng đường hô hấp', 'Vì làm như vậy sẽ khiến hóa chất bị bẩn, không dùng lại được nữa', 'Vì mùi và vị của hóa chất không giúp nhận biết được chất đó', 'Vì hóa chất trong phòng thực hành thường rất đắt tiền và khó mua'), ans: 'A', why: 'Rất nhiều hóa chất có tính độc, ăn mòn hoặc bay hơi mạnh. Nếm hay ngửi trực tiếp có thể gây ngộ độc, bỏng niêm mạc mũi và đường hô hấp. Khi cần ngửi phải dùng tay phẩy nhẹ hơi về phía mũi.' },
    { sec: 'Dụng cụ quan sát', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'Dụng cụ nào sau đây dùng để quan sát các vật có kích thước rất nhỏ như tế bào?', opts: o4('Kính lúp', 'Ống nhòm', 'Kính hiển vi', 'Kính râm'), ans: 'C', why: 'Kính hiển vi có độ phóng đại lớn (hàng trăm đến hàng nghìn lần) nên quan sát được tế bào. Kính lúp chỉ phóng đại vài lần, dùng cho vật nhỏ nhưng mắt vẫn nhìn thấy được.' },
    { sec: 'Dụng cụ quan sát', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Một kính lúp ghi số bội giác 5x. Điều đó có nghĩa là:', opts: o4('kính lúp có đường kính 5 cm', 'ảnh nhìn qua kính lớn gấp 5 lần so với khi nhìn bằng mắt thường', 'kính lúp có khối lượng 5 gam', 'phải đặt vật cách kính đúng 5 cm mới nhìn rõ'), ans: 'B', why: 'Số bội giác cho biết ảnh quan sát qua kính lớn gấp bao nhiêu lần so với khi nhìn trực tiếp bằng mắt. Số bội giác càng lớn thì ảnh càng to.' },
    { sec: 'Lĩnh vực của KHTN', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Lĩnh vực nào sau đây KHÔNG thuộc khoa học tự nhiên?', opts: o4('Lịch sử', 'Vật lí', 'Hóa học', 'Sinh học'), ans: 'A', why: 'Lịch sử thuộc nhóm khoa học xã hội. Khoa học tự nhiên gồm Vật lí, Hóa học, Sinh học, Khoa học Trái Đất và Thiên văn học.' },
    { sec: 'An toàn thực hành', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Khi vào phòng thực hành, việc đầu tiên học sinh cần làm là:', opts: o4('lấy ngay hóa chất ra để bắt đầu làm thí nghiệm', 'bật tất cả các thiết bị điện trong phòng lên', 'đọc kĩ nội quy và hướng dẫn an toàn của phòng', 'tự ý pha trộn các hóa chất có sẵn trên bàn'), ans: 'C', why: 'Nội quy và hướng dẫn an toàn giúp phòng tránh tai nạn. Chỉ được thao tác khi đã hiểu rõ quy định và được giáo viên cho phép.' },
    { sec: 'Phương pháp tìm hiểu tự nhiên', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Một nhóm học sinh muốn kiểm tra giả thuyết "nước muối làm hạt đậu nảy mầm kém hơn nước thường". Cách bố trí thí nghiệm đúng là:', opts: o4('Ngâm 10 hạt đậu trong nước muối, không cần so sánh với gì khác', 'Ngâm 10 hạt đậu trong nước muối và 5 hạt đậu trong nước thường', 'Ngâm 10 hạt trong nước muối để chỗ tối, 10 hạt trong nước thường để chỗ sáng', 'Ngâm 10 hạt đậu trong nước muối và 10 hạt trong nước thường, các điều kiện khác như nhau'), ans: 'D', why: 'Thí nghiệm phải có nhóm đối chứng, số lượng hạt bằng nhau và chỉ khác nhau đúng một yếu tố (loại nước). Phương án B sai vì số hạt khác nhau; phương án C sai vì thay đổi thêm yếu tố ánh sáng nên không kết luận được nguyên nhân.' },
    { sec: 'Vật thể và chất', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Vật thể nào sau đây là vật thể tự nhiên?', opts: o4('Cái bàn', 'Cây tre', 'Chiếc xe đạp', 'Quyển vở'), ans: 'B', why: 'Cây tre có sẵn trong tự nhiên, không do con người tạo ra. Bàn, xe đạp, quyển vở đều là vật thể nhân tạo.' },
    { sec: 'Vai trò của KHTN', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Vai trò của khoa học tự nhiên trong đời sống là:', opts: o4('cung cấp hiểu biết để phát triển công nghệ, bảo vệ sức khỏe và môi trường', 'ghi chép lại các sự kiện quan trọng đã xảy ra trong quá khứ', 'quy định cách ứng xử giữa người với người trong xã hội', 'sáng tác các tác phẩm văn học và nghệ thuật cho cộng đồng'), ans: 'A', why: 'Khoa học tự nhiên là nền tảng để phát triển công nghệ, chăm sóc sức khỏe, bảo vệ môi trường và ứng phó với thiên tai.' },
    { sec: 'An toàn thực hành', lvl: 'VD', name: 'Câu 14', pts: 1, text: 'Khi đun nóng hóa chất trong ống nghiệm, cần hướng miệng ống nghiệm:', opts: o4('về phía mình để quan sát cho rõ', 'về phía bạn ngồi bên cạnh', 'thẳng đứng lên phía trên', 'về phía không có người'), ans: 'D', why: 'Khi đun, chất lỏng có thể sôi bắn ra ngoài. Hướng miệng ống về phía không có người để tránh gây bỏng cho mình và cho người khác.' },
    { sec: 'Phép đo', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Một bạn đo chiều dài chiếc bút ba lần, được 15,2 cm; 15,3 cm; 15,2 cm. Kết quả phép đo nên ghi là:', opts: o4('15,3 cm', '45,7 cm', '15,2 cm', '15,23 cm'), ans: 'C', why: 'Kết quả lấy giá trị trung bình: (15,2 + 15,3 + 15,2) : 3 = 45,7 : 3 ≈ 15,23 cm. Nhưng thước chỉ đo tới 0,1 cm nên phải làm tròn đúng mức đó ⇒ ghi 15,2 cm. Phương án D ghi thừa chữ số, vượt quá độ chính xác của dụng cụ.' },
    { sec: 'Vật thể và chất', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Vật thể nào sau đây là vật thể nhân tạo?', opts: o4('Con mèo', 'Chiếc cốc thủy tinh', 'Hòn đá', 'Dòng sông'), ans: 'B', why: 'Chiếc cốc thủy tinh do con người chế tạo nên là vật thể nhân tạo; ba vật còn lại có sẵn trong tự nhiên.' },
    { sec: 'Phương pháp tìm hiểu tự nhiên', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Thứ tự đúng của các bước trong tiến trình tìm hiểu tự nhiên là:', opts: o4('làm thí nghiệm → quan sát đặt câu hỏi → rút ra kết luận → xây dựng giả thuyết', 'xây dựng giả thuyết → quan sát đặt câu hỏi → rút ra kết luận → làm thí nghiệm', 'rút ra kết luận → xây dựng giả thuyết → làm thí nghiệm → quan sát đặt câu hỏi', 'quan sát đặt câu hỏi → xây dựng giả thuyết → làm thí nghiệm → rút ra kết luận'), ans: 'D', why: 'Tiến trình tìm hiểu tự nhiên bắt đầu từ quan sát và đặt câu hỏi, sau đó dự đoán (giả thuyết), rồi làm thí nghiệm để kiểm tra, cuối cùng mới rút ra kết luận. Kết luận không bao giờ đứng trước thí nghiệm.' },
    { sec: 'Vật thể và chất', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Chất nào sau đây tạo nên vật thể "chiếc lốp xe"?', opts: o4('Cao su', 'Thủy tinh', 'Nước', 'Sắt'), ans: 'A', why: 'Lốp xe được làm chủ yếu từ cao su vì cao su có tính đàn hồi và bám đường tốt.' },
    { sec: 'An toàn thực hành', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Vì sao không được dùng tay ướt để cắm hoặc rút phích cắm điện?', opts: o4('Vì tay ướt làm phích cắm nhanh bị hỏng hơn', 'Vì nước làm giảm độ sáng của bóng đèn trong phòng', 'Vì nước dẫn điện nên rất dễ gây điện giật nguy hiểm', 'Vì tay ướt làm ổ cắm bị bẩn và nhanh han gỉ'), ans: 'C', why: 'Nước (nhất là nước có hòa tan muối khoáng trên da) dẫn điện. Tay ướt làm điện trở của cơ thể giảm mạnh, dòng điện dễ truyền qua người gây điện giật.' },
    { sec: 'Kí hiệu cảnh báo', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Kí hiệu nào sau đây cảnh báo chất dễ cháy?', opts: o4('Hình bàn tay bị ăn mòn', 'Hình ngọn lửa', 'Hình đầu lâu và hai xương chéo', 'Hình cây bị chết và cá chết'), ans: 'B', why: 'Hình ngọn lửa cảnh báo chất dễ cháy. Bàn tay bị ăn mòn — chất ăn mòn; đầu lâu xương chéo — chất độc; cây và cá chết — chất nguy hại cho môi trường.' },
    { sec: 'Dụng cụ đo', lvl: 'NB', name: 'Câu 21', pts: 1, text: 'Dụng cụ dùng để đo khối lượng là:', opts: o4('Cân', 'Thước', 'Nhiệt kế', 'Đồng hồ'), ans: 'A', why: 'Cân đo khối lượng; thước đo chiều dài; nhiệt kế đo nhiệt độ; đồng hồ đo thời gian.' },
    { sec: 'Dụng cụ quan sát', lvl: 'VD', name: 'Câu 22', pts: 1, text: 'Để quan sát gân của một chiếc lá cây, dụng cụ phù hợp nhất là:', opts: o4('Kính hiển vi quang học', 'Ống nhòm', 'Kính râm', 'Kính lúp'), ans: 'D', why: 'Gân lá đủ lớn để mắt thường nhìn thấy nhưng cần phóng to để thấy rõ chi tiết ⇒ dùng kính lúp là phù hợp. Kính hiển vi chỉ dùng cho vật rất nhỏ như tế bào và cần làm tiêu bản.' },
    { sec: 'An toàn thực hành', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Khi làm thí nghiệm, học sinh KHÔNG được:', opts: o4('đeo kính bảo hộ khi cần thiết', 'rửa tay thật sạch sau khi làm thí nghiệm', 'tự ý trộn lẫn các hóa chất với nhau', 'đọc kĩ nhãn hóa chất trước khi sử dụng'), ans: 'C', why: 'Tự ý trộn hóa chất có thể gây phản ứng mạnh, sinh khí độc, cháy nổ. Chỉ được làm theo đúng hướng dẫn của giáo viên.' },
    { sec: 'Lĩnh vực của KHTN', lvl: 'NB', name: 'Câu 24', pts: 1, text: 'Khoa học tự nhiên gồm các lĩnh vực chủ yếu nào?', opts: o4('Vật lí, Hóa học, Lịch sử, Địa lí', 'Vật lí, Hóa học, Sinh học, Khoa học Trái Đất và Thiên văn học', 'Toán học, Vật lí, Hóa học, Tin học', 'Sinh học, Địa lí, Văn học, Nghệ thuật'), ans: 'B', why: 'Bốn lĩnh vực chủ yếu của khoa học tự nhiên là Vật lí, Hóa học, Sinh học và Khoa học Trái Đất — Thiên văn học.' },
    { sec: 'Vật thể và chất', lvl: 'NC', name: 'Câu 25', pts: 1, text: 'Một bạn nói: "Mọi vật thể đều được tạo nên từ chất." Nhận định này:', opts: o4('đúng, vì bất kì vật thể nào cũng do một hoặc nhiều chất tạo thành', 'sai, vì vật thể tự nhiên không được tạo nên từ chất', 'sai, vì chỉ vật thể nhân tạo mới được tạo nên từ chất', 'sai, vì chất và vật thể là hai thứ hoàn toàn tách rời nhau'), ans: 'A', why: 'Chất là thứ tạo nên vật thể. Cây tre (tự nhiên) tạo nên từ cellulose, nước…; chiếc cốc (nhân tạo) tạo nên từ thủy tinh. Một vật thể có thể do nhiều chất tạo thành, ví dụ chiếc xe đạp gồm sắt, cao su, nhựa.' },
    { sec: 'Dụng cụ đo', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Nhiệt kế y tế dùng để đo:', opts: o4('khối lượng cơ thể', 'chiều cao cơ thể', 'nhiệt độ cơ thể', 'huyết áp của cơ thể'), ans: 'C', why: 'Nhiệt kế y tế có thang đo khoảng 35 – 42 °C, đúng khoảng nhiệt độ của cơ thể người.' },
    { sec: 'An toàn thực hành', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Khi sử dụng đèn cồn, muốn tắt đèn ta phải:', opts: o4('thổi thật mạnh vào ngọn lửa', 'đổ nước vào trong đèn cồn', 'để yên cho đèn tự tắt dần', 'đậy nắp đèn lại'), ans: 'D', why: 'Đậy nắp làm ngọn lửa tắt do thiếu oxygen. Thổi có thể làm cồn bắn ra gây cháy lan; đổ nước làm hỏng đèn.' },
    { sec: 'Phương pháp tìm hiểu tự nhiên', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Bạn Nam đặt hai đĩa nước giống hệt nhau, một đĩa ngoài nắng, một đĩa trong bóng râm. Sau 2 giờ, đĩa ngoài nắng cạn nhiều hơn. Kết luận đúng là:', opts: o4('Nước chỉ bay hơi khi có ánh nắng mặt trời chiếu vào', 'Nhiệt độ càng cao thì nước bay hơi càng nhanh', 'Ánh sáng đã làm nước biến đổi thành một chất khác', 'Diện tích mặt thoáng là yếu tố quyết định tốc độ bay hơi'), ans: 'B', why: 'Hai đĩa chỉ khác nhau ở chỗ nắng — râm, tức khác nhau về nhiệt độ. Đĩa nóng hơn cạn nhanh hơn ⇒ nhiệt độ càng cao, bay hơi càng nhanh. A sai vì đĩa trong râm vẫn cạn bớt; D sai vì hai đĩa có mặt thoáng như nhau nên không kết luận được về yếu tố này.' },
    { sec: 'Khái niệm KHTN', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Hoạt động nào sau đây là hoạt động nghiên cứu khoa học?', opts: o4('Tìm hiểu vì sao lá cây có màu xanh', 'Trồng hoa để trang trí lớp học', 'Vẽ tranh về phong cảnh quê hương', 'Tập hát một bài hát mới'), ans: 'A', why: 'Nghiên cứu khoa học là hoạt động tìm hiểu, khám phá để trả lời một câu hỏi về thế giới tự nhiên. Ba hoạt động còn lại là lao động và nghệ thuật.' },
    { sec: 'Dụng cụ đo', lvl: 'TH', name: 'Câu 30', pts: 1, text: 'Trong các dụng cụ sau, dụng cụ nào dùng để đo thời gian?', opts: o4('Cân đồng hồ', 'Thước dây', 'Đồng hồ bấm giây', 'Nhiệt kế rượu'), ans: 'C', why: 'Đồng hồ bấm giây đo khoảng thời gian diễn ra một hiện tượng. Lưu ý "cân đồng hồ" là loại cân, dùng đo khối lượng chứ không đo thời gian.' },
  ],
},

/* ═══════════ ĐỀ 2 — DỤNG CỤ ĐO. ĐO CHIỀU DÀI, KHỐI LƯỢNG, THỜI GIAN ═══════════ */
{
  id: 10652, title: 'Đề 2 · Dụng cụ đo. Đo chiều dài, khối lượng, thời gian', time: 60,
  questions: [
    { sec: 'Đơn vị đo', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Đơn vị đo chiều dài hợp pháp của nước ta là:', opts: o4('mét (m)', 'inch', 'dặm', 'gam'), ans: 'A', why: 'Mét là đơn vị đo chiều dài trong hệ đơn vị đo lường hợp pháp của Việt Nam (hệ SI). Inch và dặm là đơn vị của Anh, Mĩ; gam là đơn vị khối lượng.' },
    { sec: 'Ghi kết quả đo', lvl: 'VD', name: 'Câu 2', pts: 1, text: 'Một thước có giới hạn đo 30 cm và độ chia nhỏ nhất 1 mm. Kết quả đo nào sau đây được ghi ĐÚNG?', opts: o4('12 cm', '12,25 cm', '12,5 cm', '12,50 cm'), ans: 'C', why: 'ĐCNN 1 mm = 0,1 cm nên kết quả phải ghi tới một chữ số thập phân (theo cm): 12,5 cm. Phương án A thiếu chữ số; B và D ghi tới 0,01 cm, vượt quá khả năng của thước.' },
    { sec: 'Dụng cụ đo', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Dụng cụ nào sau đây dùng để đo thời gian?', opts: o4('Cân đồng hồ', 'Thước cuộn', 'Bình chia độ', 'Đồng hồ bấm giây'), ans: 'D', why: 'Đồng hồ bấm giây đo thời gian. Cân đồng hồ đo khối lượng, thước cuộn đo chiều dài, bình chia độ đo thể tích.' },
    { sec: 'Đo thể tích vật rắn', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Bình chia độ chứa 40 mL nước. Thả chìm một viên sỏi vào thì mực nước lên 47 mL. Nếu thả thêm một viên sỏi giống hệt nữa thì mực nước sẽ là:', opts: o4('47 mL', '54 mL', '87 mL', '14 mL'), ans: 'B', why: 'Thể tích mỗi viên sỏi = 47 − 40 = 7 (mL). Thả thêm một viên giống hệt thì mực nước dâng thêm 7 mL nữa: 47 + 7 = 54 (mL).' },
    { sec: 'Giới hạn đo', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Giới hạn đo (GHĐ) của một thước là:', opts: o4('độ dài giữa hai vạch chia liên tiếp trên thước', 'độ dài nhỏ nhất mà thước có thể đo được', 'độ dài lớn nhất ghi trên thước', 'số vạch chia có trên toàn bộ thước'), ans: 'C', why: 'GHĐ là độ dài lớn nhất ghi trên thước — tức giá trị lớn nhất mà thước đo được trong một lần. Phương án A là định nghĩa của ĐCNN.' },
    { sec: 'Đơn vị đo', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'Đơn vị đo khối lượng hợp pháp của nước ta là:', opts: o4('lít', 'kilôgam', 'mét', 'giây'), ans: 'B', why: 'Kilôgam (kg) là đơn vị đo khối lượng trong hệ SI. Lít đo thể tích, mét đo chiều dài, giây đo thời gian.' },
    { sec: 'Cách đo chiều dài', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Khi đọc kết quả đo chiều dài một vật, phải đặt mắt nhìn:', opts: o4('theo hướng vuông góc với cạnh thước tại đầu kia của vật', 'theo hướng xiên từ phía bên trái của vật cần đo', 'theo hướng xiên từ phía bên phải của vật cần đo', 'theo hướng song song với mặt thước đang sử dụng'), ans: 'A', why: 'Nhìn xiên sẽ gây sai số do hiện tượng thị sai: vạch chia và đầu vật không trùng nhau trong tầm nhìn. Phải nhìn vuông góc với mặt thước tại vị trí đầu vật.' },
    { sec: 'Đổi đơn vị', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Đổi 2,5 kg ra gam ta được:', opts: o4('25 g', '250 g', '25000 g', '2500 g'), ans: 'D', why: '1 kg = 1000 g nên 2,5 kg = 2,5 × 1000 = 2500 (g).' },
    { sec: 'Ghi kết quả đo', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Một bạn dùng cân có ĐCNN 0,1 g để cân một vật và ghi kết quả 15,25 g. Kết quả này:', opts: o4('đúng, vì đã ghi tới hai chữ số sau dấu phẩy', 'đúng, vì chiếc cân đó rất chính xác', 'sai, vì phải ghi tới 0,1 g, tức 15,2 g hoặc 15,3 g', 'sai, vì khối lượng bắt buộc phải là một số nguyên'), ans: 'C', why: 'Kết quả đo không được ghi chính xác hơn ĐCNN của dụng cụ. Cân chỉ đọc được tới 0,1 g nên chữ số hàng phần trăm là vô nghĩa.' },
    { sec: 'Dụng cụ đo', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'Để đo thể tích của chất lỏng, ta dùng:', opts: o4('bình chia độ', 'thước kẻ', 'lực kế', 'nhiệt kế'), ans: 'A', why: 'Bình chia độ (hoặc ống đong, cốc chia độ) có vạch chia thể tích nên dùng để đo thể tích chất lỏng.' },
    { sec: 'Chọn dụng cụ đo', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Muốn đo chiều dài một sân bóng khoảng 100 m, nên chọn dụng cụ nào?', opts: o4('Thước kẻ 20 cm, đo nhiều lần rồi cộng lại', 'Thước cuộn có giới hạn đo 50 m', 'Thước dây may mặc dài 1,5 m', 'Thước thẳng học sinh dài 30 cm'), ans: 'B', why: 'Phải chọn dụng cụ có GHĐ phù hợp để số lần đo ít, sai số nhỏ. Thước cuộn 50 m chỉ cần đo 2 lần; dùng thước 20 cm hay 30 cm phải đo hàng trăm lần, sai số cộng dồn rất lớn.' },
    { sec: 'Độ chia nhỏ nhất', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Độ chia nhỏ nhất (ĐCNN) của thước là:', opts: o4('độ dài lớn nhất ghi trên thước', 'chiều dài của toàn bộ chiếc thước', 'số vạch chia có trên thước', 'độ dài giữa hai vạch chia liên tiếp'), ans: 'D', why: 'ĐCNN là khoảng cách giữa hai vạch chia liên tiếp — nó quyết định mức độ chính xác khi ghi kết quả đo.' },
    { sec: 'Đổi đơn vị', lvl: 'VD', name: 'Câu 13', pts: 1, text: 'Một bạn cân một túi gạo được 5 kg 200 g. Khối lượng túi gạo tính theo kilôgam là:', opts: o4('52 kg', '5,02 kg', '5,2 kg', '5200 kg'), ans: 'C', why: '200 g = 0,2 kg nên 5 kg 200 g = 5 + 0,2 = 5,2 (kg).' },
    { sec: 'Đổi đơn vị', lvl: 'NB', name: 'Câu 14', pts: 1, text: '1 giờ bằng bao nhiêu giây?', opts: o4('3600 s', '60 s', '100 s', '600 s'), ans: 'A', why: '1 giờ = 60 phút, mỗi phút = 60 giây nên 1 giờ = 60 × 60 = 3600 (s).' },
    { sec: 'Đo thể tích vật rắn', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Để đo thể tích của một hòn đá to không bỏ lọt bình chia độ, ta cần dùng thêm:', opts: o4('một chiếc cân đồng hồ', 'bình tràn', 'một chiếc thước dây', 'một chiếc nhiệt kế'), ans: 'B', why: 'Thả hòn đá vào bình tràn đã đầy nước, hứng lấy phần nước tràn ra rồi đo bằng bình chia độ. Thể tích nước tràn ra chính bằng thể tích hòn đá.' },
    { sec: 'Đổi đơn vị', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Đổi 1,5 giờ ra phút ta được:', opts: o4('15 phút', '105 phút', '150 phút', '90 phút'), ans: 'D', why: '1,5 giờ = 1 giờ + 0,5 giờ = 60 + 30 = 90 (phút).' },
    { sec: 'Dụng cụ đo', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Dụng cụ nào sau đây dùng để đo nhiệt độ?', opts: o4('Nhiệt kế', 'Cân', 'Thước', 'Bình chia độ'), ans: 'A', why: 'Nhiệt kế là dụng cụ đo nhiệt độ, hoạt động dựa trên sự dãn nở vì nhiệt.' },
    { sec: 'Đo khối lượng', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'Dùng cân Rô-bec-van, đặt vật lên đĩa trái và các quả cân lên đĩa phải. Khi đòn cân thăng bằng, khối lượng của vật bằng:', opts: o4('tổng khối lượng các quả cân cộng với khối lượng của đĩa cân', 'hiệu khối lượng các quả cân và khối lượng của đĩa cân', 'tổng khối lượng của các quả cân đặt trên đĩa bên phải', 'một nửa tổng khối lượng của các quả cân đã sử dụng'), ans: 'C', why: 'Hai đĩa cân giống hệt nhau nên khối lượng của chúng tự triệt tiêu. Khi cân thăng bằng, khối lượng vật đúng bằng tổng khối lượng các quả cân.' },
    { sec: 'Cách đo chiều dài', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Khi đo chiều dài một vật, cần đặt thước:', opts: o4('song song nhưng cách xa vật để nhìn rõ vạch chia', 'dọc theo vật cần đo, một đầu vật ngang bằng vạch số 0', 'vuông góc với vật cần đo để dễ quan sát', 'chéo góc với vật để đo được cả phần cong'), ans: 'B', why: 'Thước phải đặt dọc theo vật và một đầu vật trùng với vạch số 0, khi đó số đọc ở đầu kia chính là chiều dài vật.' },
    { sec: 'Đơn vị đo', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'Đơn vị đo thời gian trong hệ SI là:', opts: o4('giờ', 'phút', 'ngày', 'giây'), ans: 'D', why: 'Giây (s) là đơn vị đo thời gian trong hệ SI. Giờ, phút, ngày là các đơn vị dẫn xuất dùng trong đời sống.' },
    { sec: 'Ghi kết quả đo', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Một bạn đo chiều dài quyển sách 4 lần được: 20,1 cm; 20,2 cm; 20,1 cm; 20,0 cm. Chiều dài trung bình của quyển sách là:', opts: o4('20,0 cm', '20,2 cm', '20,1 cm', '80,4 cm'), ans: 'C', why: 'Chiều dài trung bình = (20,1 + 20,2 + 20,1 + 20,0) : 4 = 80,4 : 4 = 20,1 (cm). Phương án D là tổng bốn lần đo, chưa chia cho 4.' },
    { sec: 'Đo khối lượng', lvl: 'TH', name: 'Câu 22', pts: 1, text: 'Trước khi đo khối lượng bằng cân đồng hồ, ta cần:', opts: o4('điều chỉnh kim cân về đúng vạch số 0', 'đặt vật lên đĩa cân rồi mới chỉnh kim', 'lắc mạnh cân cho kim dao động qua lại', 'đặt cân ở nơi có gió thổi mạnh'), ans: 'A', why: 'Nếu kim không ở vạch 0 khi chưa cân thì mọi kết quả đều bị lệch đi một lượng cố định. Vì vậy phải hiệu chỉnh kim về 0 trước.' },
    { sec: 'Chọn dụng cụ đo', lvl: 'NB', name: 'Câu 23', pts: 1, text: 'Để đo đường kính trong của một chiếc cốc, dụng cụ phù hợp là:', opts: o4('Cân đồng hồ', 'Nhiệt kế', 'Đồng hồ bấm giây', 'Thước kẻ'), ans: 'D', why: 'Đường kính là một độ dài nên phải dùng dụng cụ đo chiều dài, ở đây là thước kẻ.' },
    { sec: 'Đo thể tích vật rắn', lvl: 'VD', name: 'Câu 24', pts: 1, text: 'Một bình chia độ chứa 55 mL nước. Thả chìm hoàn toàn một vật rắn vào bình thì mực nước dâng lên 78 mL. Thể tích của vật rắn là:', opts: o4('78 cm³', '23 cm³', '133 cm³', '55 cm³'), ans: 'B', why: 'Thể tích vật = thể tích nước dâng thêm = 78 − 55 = 23 (mL). Vì 1 mL = 1 cm³ nên thể tích vật là 23 cm³.' },
    { sec: 'Đo thể tích chất lỏng', lvl: 'NC', name: 'Câu 25', pts: 1, text: 'Khi đọc kết quả đo thể tích chất lỏng trong bình chia độ, mắt phải nhìn:', opts: o4('từ trên xuống mặt thoáng của chất lỏng', 'từ dưới lên mặt thoáng của chất lỏng', 'ngang bằng với mặt thoáng của chất lỏng', 'chếch một góc 45° so với mặt thoáng'), ans: 'C', why: 'Nhìn từ trên xuống hay từ dưới lên đều gây sai số thị sai, khiến đọc thừa hoặc thiếu. Phải đặt mắt ngang bằng với mặt thoáng chất lỏng.' },
    { sec: 'Đổi đơn vị', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Đổi 750 g ra kilôgam ta được:', opts: o4('0,75 kg', '7,5 kg', '75 kg', '0,075 kg'), ans: 'A', why: '1000 g = 1 kg nên 750 g = 750 : 1000 = 0,75 (kg).' },
    { sec: 'Sai số phép đo', lvl: 'NC', name: 'Câu 27', pts: 1, text: 'Vì sao khi đo phải thực hiện phép đo nhiều lần rồi lấy giá trị trung bình?', opts: o4('Để kéo dài thời gian làm thí nghiệm cho kĩ lưỡng', 'Để giảm bớt sai số do người đo và dụng cụ gây ra', 'Để dụng cụ đo lâu bị hỏng hơn khi dùng nhiều', 'Để kết quả cuối cùng luôn là một số nguyên đẹp'), ans: 'B', why: 'Mỗi lần đo đều có sai số ngẫu nhiên, khi thì thừa khi thì thiếu. Lấy trung bình của nhiều lần đo, các sai số này bù trừ nhau nên kết quả gần giá trị thật hơn.' },
    { sec: 'Đổi đơn vị', lvl: 'NB', name: 'Câu 28', pts: 1, text: '1 km bằng bao nhiêu mét?', opts: o4('10 m', '100 m', '10000 m', '1000 m'), ans: 'D', why: 'Tiền tố "ki-lô" nghĩa là một nghìn nên 1 km = 1000 m.' },
    { sec: 'Chọn dụng cụ đo', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Một thước có GHĐ 20 cm và ĐCNN 1 mm. Thước này KHÔNG thể dùng để đo:', opts: o4('chiều dài chiếc bút chì', 'chiều rộng quyển vở', 'chiều dài chiếc bảng lớp học', 'bề dày của quyển sách'), ans: 'C', why: 'Bảng lớp dài vài mét, vượt xa GHĐ 20 cm của thước. Ba vật còn lại đều có kích thước nhỏ hơn 20 cm nên đo được trong một lần.' },
    { sec: 'Dụng cụ đo', lvl: 'NB', name: 'Câu 30', pts: 1, text: 'Dụng cụ nào sau đây dùng để đo lực?', opts: o4('Lực kế', 'Cân', 'Thước', 'Nhiệt kế'), ans: 'A', why: 'Lực kế đo độ lớn của lực, hoạt động dựa trên độ dãn của lò xo. Cân đo khối lượng, không phải lực.' },
  ],
},

/* ═══════════ ĐỀ 3 — ĐO NHIỆT ĐỘ. THANG NHIỆT ĐỘ ═══════════ */
{
  id: 10653, title: 'Đề 3 · Đo nhiệt độ. Thang nhiệt độ', time: 60,
  questions: [
    { sec: 'Nhiệt độ trong đời sống', lvl: 'VD', name: 'Câu 1', pts: 1, text: 'Nhiệt độ cơ thể của người bình thường vào khoảng:', opts: o4('27 °C', '37 °C', '47 °C', '100 °C'), ans: 'B', why: 'Thân nhiệt người khỏe mạnh vào khoảng 37 °C. Vượt quá 37,5 °C thường được coi là sốt.' },
    { sec: 'Dụng cụ đo nhiệt độ', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Dụng cụ dùng để đo nhiệt độ là:', opts: o4('nhiệt kế', 'lực kế', 'ampe kế', 'tốc kế'), ans: 'A', why: 'Nhiệt kế đo nhiệt độ. Lực kế đo lực, ampe kế đo cường độ dòng điện, tốc kế đo tốc độ.' },
    { sec: 'Thang nhiệt độ', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Ở điều kiện thường, nước đá nóng chảy ở nhiệt độ:', opts: o4('100 °C', '−10 °C', '0 °C', '37 °C'), ans: 'C', why: 'Nước đá bắt đầu nóng chảy ở 0 °C. Đây cũng là mốc dưới của thang nhiệt độ Celsius.' },
    { sec: 'Giới hạn đo của nhiệt kế', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Vì sao không dùng nhiệt kế y tế để đo nhiệt độ của nước đang sôi?', opts: o4('Vì nhiệt kế y tế quá ngắn, không chạm được tới đáy nồi', 'Vì nước sôi làm nhiệt kế y tế bị bẩn, rất khó lau chùi', 'Vì nhiệt kế y tế chỉ dùng được cho cơ thể của sinh vật sống', 'Vì giới hạn đo của nhiệt kế y tế chỉ khoảng 35 – 42 °C, thấp hơn 100 °C'), ans: 'D', why: 'Nước sôi ở 100 °C, vượt xa GHĐ của nhiệt kế y tế. Dùng sai sẽ làm cột thủy ngân dâng quá vạch cuối và làm vỡ nhiệt kế.' },
    { sec: 'Đơn vị nhiệt độ', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Đơn vị đo nhiệt độ thường dùng ở nước ta là:', opts: o4('độ C (°C)', 'độ F (°F)', 'kelvin (K)', 'niutơn (N)'), ans: 'A', why: 'Việt Nam dùng thang Celsius, đơn vị là độ C. Độ F dùng ở Mĩ, kelvin dùng trong khoa học, niutơn là đơn vị đo lực.' },
    { sec: 'Nguyên tắc hoạt động', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Nhiệt kế hoạt động dựa trên hiện tượng nào?', opts: o4('sự nở vì nhiệt của chất rắn khi bị nén mạnh', 'sự bay hơi của chất lỏng khi gặp lạnh', 'sự dẫn điện của kim loại khi nóng lên', 'sự dãn nở vì nhiệt của chất lỏng hoặc kim loại'), ans: 'D', why: 'Khi nóng lên, chất lỏng (thủy ngân, rượu) hoặc thanh kim loại trong nhiệt kế dãn nở, làm cột chất lỏng dâng lên hoặc kim quay — nhờ đó chỉ ra nhiệt độ.' },
    { sec: 'Thang nhiệt độ', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Ở điều kiện thường, nước sôi ở nhiệt độ:', opts: o4('0 °C', '100 °C', '37 °C', '50 °C'), ans: 'B', why: 'Nước sôi ở 100 °C — đây là mốc trên của thang nhiệt độ Celsius.' },
    { sec: 'Giới hạn đo của nhiệt kế', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Một nhiệt kế có GHĐ từ −20 °C đến 50 °C và ĐCNN 1 °C. Nhiệt kế này dùng được để đo:', opts: o4('nhiệt độ của nước đang sôi trong ấm', 'nhiệt độ bên trong lò nung gạch', 'nhiệt độ không khí ngoài trời', 'nhiệt độ của sắt đang nóng chảy'), ans: 'C', why: 'Nhiệt độ không khí ngoài trời thường nằm trong khoảng −20 °C đến 50 °C nên phù hợp. Nước sôi (100 °C), lò nung và sắt nóng chảy (hàng trăm tới hàng nghìn độ) đều vượt GHĐ.' },
    { sec: 'Cách đo nhiệt độ', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Trước khi đo nhiệt độ cơ thể bằng nhiệt kế y tế thủy ngân, ta cần:', opts: o4('vẩy mạnh cho thủy ngân tụt xuống dưới vạch 35 °C', 'hơ nhiệt kế qua lửa cho nóng lên trước', 'ngâm nhiệt kế vào nước đá cho thật lạnh', 'lắc nhiệt kế cho cột chất lỏng dâng lên cao'), ans: 'A', why: 'Nhiệt kế y tế có chỗ thắt giữ cột thủy ngân không tụt xuống sau khi đo, nên phải vẩy mạnh đưa thủy ngân về dưới 35 °C trước khi đo lần mới.' },
    { sec: 'Bài toán nhiệt độ', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Buổi sáng nhiệt độ ngoài trời là 18 °C, đến trưa tăng thêm 12 °C, đến tối lại giảm 9 °C so với buổi trưa. Nhiệt độ buổi tối là:', opts: o4('30 °C', '21 °C', '15 °C', '39 °C'), ans: 'B', why: 'Nhiệt độ buổi trưa: 18 + 12 = 30 (°C). Nhiệt độ buổi tối: 30 − 9 = 21 (°C). Phương án A là dừng lại ở buổi trưa.' },
    { sec: 'Khái niệm nhiệt độ', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Nhiệt độ cho biết điều gì về một vật?', opts: o4('khối lượng của vật', 'thể tích của vật', 'chiều dài của vật', 'mức độ nóng, lạnh của vật'), ans: 'D', why: 'Nhiệt độ là số đo mức độ nóng hay lạnh của vật. Vật càng nóng thì nhiệt độ càng cao.' },
    { sec: 'Cách đo nhiệt độ', lvl: 'VD', name: 'Câu 12', pts: 1, text: 'Để đo nhiệt độ của nước trong cốc, cần đặt bầu nhiệt kế:', opts: o4('chạm sát vào đáy cốc', 'chỉ chạm vào mặt thoáng của nước', 'ngập trong nước, không chạm đáy và thành cốc', 'treo lơ lửng phía trên mặt nước'), ans: 'C', why: 'Bầu nhiệt kế phải ngập hẳn trong nước để nhận đúng nhiệt độ của nước. Nếu chạm đáy hoặc thành cốc, nhiệt kế sẽ đo lẫn nhiệt độ của cốc chứ không phải của nước.' },
    { sec: 'Thang nhiệt độ', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Thang nhiệt độ Celsius lấy mốc 0 °C ứng với:', opts: o4('nhiệt độ của nước đá đang tan', 'nhiệt độ của nước đang sôi', 'nhiệt độ của cơ thể người', 'nhiệt độ thấp nhất có thể có'), ans: 'A', why: 'Thang Celsius quy ước 0 °C là nhiệt độ nước đá đang tan và 100 °C là nhiệt độ nước đang sôi (ở áp suất thường), rồi chia đều khoảng giữa thành 100 phần.' },
    { sec: 'Cách đo nhiệt độ', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Vì sao khi đo nhiệt độ chất lỏng, phải để bầu nhiệt kế trong chất lỏng một lúc rồi mới đọc kết quả?', opts: o4('Để chất lỏng kịp bay hơi bớt đi một phần', 'Để nhiệt độ của nhiệt kế kịp bằng nhiệt độ chất lỏng', 'Để cột chất lỏng trong nhiệt kế kịp lắng xuống', 'Để người đo có thời gian chuẩn bị giấy bút ghi chép'), ans: 'B', why: 'Ban đầu nhiệt kế có nhiệt độ khác chất lỏng. Cần thời gian để nhiệt truyền qua lại cho tới khi hai bên cùng nhiệt độ; đọc quá sớm sẽ cho kết quả sai.' },
    { sec: 'Các loại nhiệt kế', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Loại nhiệt kế nào thường dùng để đo nhiệt độ cơ thể người?', opts: o4('Nhiệt kế rượu', 'Nhiệt kế kim loại', 'Nhiệt kế y tế', 'Nhiệt kế phòng thí nghiệm'), ans: 'C', why: 'Nhiệt kế y tế có thang đo hẹp (khoảng 35 – 42 °C) và độ chia nhỏ, phù hợp để đo thân nhiệt chính xác.' },
    { sec: 'Sự chuyển thể', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Ở nhiệt độ nào nước có thể tồn tại đồng thời ở cả thể rắn và thể lỏng?', opts: o4('100 °C', '37 °C', '−10 °C', '0 °C'), ans: 'D', why: 'Tại 0 °C, nước đá đang tan: một phần đã hóa lỏng còn một phần vẫn ở thể rắn. Trong suốt quá trình nóng chảy, nhiệt độ giữ nguyên ở 0 °C.' },
    { sec: 'Nhiệt độ trong đời sống', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Nhiệt độ của một phòng học thông thường vào khoảng:', opts: o4('5 °C', '25 °C', '50 °C', '80 °C'), ans: 'B', why: 'Nhiệt độ dễ chịu trong phòng ở nước ta vào khoảng 25 °C. 5 °C là rất lạnh, còn 50 °C và 80 °C thì con người không thể sinh hoạt bình thường.' },
    { sec: 'Nguyên tắc hoạt động', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Khi nhiệt độ tăng, chất lỏng trong nhiệt kế sẽ:', opts: o4('dãn nở ra và dâng lên', 'co lại và tụt xuống', 'bay hơi hết ra ngoài', 'đông đặc lại thành thể rắn'), ans: 'A', why: 'Chất lỏng nở ra khi nóng lên, thể tích tăng nên cột chất lỏng trong ống mao dẫn dâng lên, chỉ mức nhiệt độ cao hơn.' },
    { sec: 'Cách đo nhiệt độ', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Một bạn đặt nhiệt kế ra giữa trời nắng để đo nhiệt độ không khí, đọc được 45 °C trong khi bản tin thời tiết báo 33 °C. Nguyên nhân của sai lệch là:', opts: o4('Nhiệt kế của bạn đó đã bị hỏng hoàn toàn', 'Bản tin thời tiết hôm đó đã đưa tin sai', 'Không khí ngoài trời lạnh hơn trong bóng râm', 'Nhiệt kế bị Mặt Trời chiếu trực tiếp nên nóng hơn không khí'), ans: 'D', why: 'Khi bị nắng chiếu thẳng, nhiệt kế hấp thụ năng lượng ánh sáng nên nóng hơn không khí xung quanh. Muốn đo đúng nhiệt độ không khí phải đặt nhiệt kế trong bóng râm, nơi thoáng gió.' },
    { sec: 'Các loại nhiệt kế', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Nhiệt kế rượu thường được dùng để đo nhiệt độ:', opts: o4('của lò nung ở nhiệt độ rất cao', 'của cơ thể người khi bị sốt', 'của khí quyển, kể cả khi trời rất lạnh', 'của kim loại đang nóng chảy'), ans: 'C', why: 'Rượu đông đặc ở nhiệt độ rất thấp (khoảng −117 °C) nên nhiệt kế rượu đo được cả những vùng rất lạnh — điều mà nhiệt kế thủy ngân không làm được.' },
    { sec: 'Bài toán nhiệt độ', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Nhiệt độ ở Sa Pa buổi sáng là −2 °C, buổi trưa là 9 °C. Nhiệt độ buổi trưa cao hơn buổi sáng bao nhiêu độ?', opts: o4('7 °C', '11 °C', '−11 °C', '18 °C'), ans: 'B', why: 'Chênh lệch = 9 − (−2) = 9 + 2 = 11 (°C). Phương án A là lỗi tính 9 − 2, quên dấu âm.' },
    { sec: 'So sánh nhiệt độ', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Vật nào sau đây có nhiệt độ cao nhất?', opts: o4('Cốc nước đá', 'Không khí trong phòng lạnh', 'Nước máy chứa trong bể', 'Nước đang sôi trong ấm'), ans: 'D', why: 'Nước đang sôi có nhiệt độ 100 °C — cao hơn hẳn nước đá (0 °C), không khí phòng lạnh và nước máy (khoảng 25 – 30 °C).' },
    { sec: 'Chọn nhiệt kế', lvl: 'VD', name: 'Câu 23', pts: 1, text: 'Muốn đo nhiệt độ của một lò nung khoảng 800 °C, ta cần dùng:', opts: o4('nhiệt kế kim loại có giới hạn đo phù hợp', 'nhiệt kế y tế thủy ngân', 'nhiệt kế rượu thông thường', 'nhiệt kế điện tử đo trán'), ans: 'A', why: 'Nhiệt độ 800 °C vượt xa GHĐ của nhiệt kế y tế, nhiệt kế rượu và nhiệt kế đo trán (rượu còn sôi ở khoảng 78 °C). Phải dùng nhiệt kế kim loại chuyên dụng cho nhiệt độ cao.' },
    { sec: 'Sự chuyển thể', lvl: 'TH', name: 'Câu 24', pts: 1, text: 'Khi nhiệt độ hạ xuống dưới 0 °C thì nước sẽ:', opts: o4('sôi lên', 'bay hơi hết', 'đông đặc', 'nóng chảy'), ans: 'C', why: 'Dưới 0 °C, nước chuyển từ thể lỏng sang thể rắn — đó là sự đông đặc. Nóng chảy là quá trình ngược lại.' },
    { sec: 'Suy luận về nhiệt độ', lvl: 'NC', name: 'Câu 25', pts: 1, text: 'Có hai cốc nước giống nhau, cốc A ở 20 °C và cốc B ở 60 °C. Nếu đổ hai cốc vào chung một bình thì nhiệt độ của nước trong bình sẽ:', opts: o4('bằng đúng 80 °C', 'nằm trong khoảng từ 20 °C đến 60 °C', 'thấp hơn 20 °C', 'cao hơn 60 °C'), ans: 'B', why: 'Nước nóng truyền nhiệt cho nước lạnh cho tới khi cả hai cùng một nhiệt độ. Nhiệt độ chung phải cao hơn cốc lạnh và thấp hơn cốc nóng. Phương án A sai vì nhiệt độ không cộng được như khối lượng.' },
    { sec: 'Giới hạn đo của nhiệt kế', lvl: 'NB', name: 'Câu 26', pts: 1, text: 'Giới hạn đo của nhiệt kế y tế thường là:', opts: o4('từ 35 °C đến 42 °C', 'từ 0 °C đến 100 °C', 'từ −20 °C đến 50 °C', 'từ 0 °C đến 500 °C'), ans: 'A', why: 'Thang đo của nhiệt kế y tế được thiết kế hẹp, bao trọn khoảng thân nhiệt người (kể cả khi sốt cao) để có độ chia nhỏ và đọc chính xác.' },
    { sec: 'Các loại nhiệt kế', lvl: 'TH', name: 'Câu 27', pts: 1, text: 'Vì sao không dùng nhiệt kế thủy ngân để đo nhiệt độ ở vùng cực lạnh dưới −40 °C?', opts: o4('Vì thủy ngân sẽ bay hơi hết ở nhiệt độ đó', 'Vì thủy ngân nở ra quá nhanh khi gặp lạnh', 'Vì thủy ngân đông đặc ở khoảng −39 °C nên không còn dãn nở được', 'Vì nhiệt kế thủy ngân chỉ dùng được cho cơ thể người'), ans: 'C', why: 'Thủy ngân đông đặc ở khoảng −39 °C. Khi đã hóa rắn, nó không còn dãn nở theo nhiệt độ nữa nên nhiệt kế mất tác dụng. Ở vùng rất lạnh phải dùng nhiệt kế rượu.' },
    { sec: 'Đọc bảng số liệu', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Bảng ghi nhiệt độ một ngày ở Hà Nội: 6 giờ — 22 °C; 12 giờ — 33 °C; 18 giờ — 29 °C; 24 giờ — 24 °C. Chênh lệch giữa nhiệt độ cao nhất và thấp nhất trong ngày là:', opts: o4('5 °C', '9 °C', '7 °C', '11 °C'), ans: 'D', why: 'Nhiệt độ cao nhất là 33 °C (lúc 12 giờ), thấp nhất là 22 °C (lúc 6 giờ). Chênh lệch = 33 − 22 = 11 (°C).' },
    { sec: 'Các loại nhiệt kế', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Nhiệt kế điện tử có ưu điểm nào sau đây?', opts: o4('Đọc kết quả nhanh và không chứa thủy ngân độc hại', 'Đo được nhiệt độ cao tới hàng nghìn độ', 'Không cần nguồn điện vẫn hoạt động được', 'Giá thành rẻ hơn tất cả các loại nhiệt kế khác'), ans: 'A', why: 'Nhiệt kế điện tử cho kết quả sau vài giây, hiển thị số rõ ràng và an toàn vì không dùng thủy ngân — nhưng vẫn cần pin để hoạt động.' },
    { sec: 'Cách đo nhiệt độ', lvl: 'TH', name: 'Câu 30', pts: 1, text: 'Khi đo nhiệt độ không khí trong phòng, cần đặt nhiệt kế ở đâu?', opts: o4('sát ngay vào bóng đèn đang bật sáng', 'nơi thoáng, tránh ánh nắng và các nguồn nhiệt', 'ngay cạnh cửa sổ có gió lùa thật mạnh', 'áp sát vào bức tường phía ngoài của nhà'), ans: 'B', why: 'Đặt gần bóng đèn, tường bị nắng hay chỗ gió lùa mạnh đều làm nhiệt kế chịu ảnh hưởng riêng, không phản ánh đúng nhiệt độ chung của không khí trong phòng.' },
  ],
},


/* ═══════════ ĐỀ 4 — SỰ ĐA DẠNG CỦA CHẤT. BA THỂ CỦA CHẤT ═══════════ */
{
  id: 10654, title: 'Đề 4 · Sự đa dạng của chất. Ba thể của chất', time: 60,
  questions: [
    { sec: 'Vật thể tự nhiên', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Vật thể nào sau đây KHÔNG phải là vật thể tự nhiên?', opts: o4('núi đá vôi', 'chiếc cốc thủy tinh', 'con sông', 'cây bàng'), ans: 'B', why: 'Cốc thủy tinh do con người nấu từ cát rồi tạo hình nên là vật thể nhân tạo. Núi đá vôi, con sông và cây bàng đều có sẵn trong tự nhiên.' },
    { sec: 'Chất và vật thể', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Phát biểu nào sau đây ĐÚNG?', opts: o4('Mọi vật thể đều do một chất duy nhất tạo nên', 'Chất chỉ có trong các vật thể nhân tạo', 'Ở đâu có vật thể thì ở đó có chất', 'Vật thể tự nhiên không được tạo nên từ chất'), ans: 'C', why: 'Mọi vật thể — dù tự nhiên hay nhân tạo — đều được tạo nên từ chất. Một vật thể có thể do nhiều chất tạo nên (ví dụ chiếc xe đạp gồm thép, cao su, nhựa) nên phương án A sai.' },
    { sec: 'Phân loại vật thể', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Cho các vật thể: con chó, xe máy, cây cà chua, lọ hoa thủy tinh, núi đá vôi. Số vật thể tự nhiên là:', opts: o4('3', '2', '4', '1'), ans: 'A', why: 'Vật thể tự nhiên gồm con chó, cây cà chua và núi đá vôi — <b>3</b> vật thể. Xe máy và lọ hoa thủy tinh do con người tạo ra nên là vật thể nhân tạo.' },
    { sec: 'Thể của chất', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Ở điều kiện thường, chất nào sau đây ở thể khí?', opts: o4('nước', 'muối ăn', 'sắt', 'oxygen'), ans: 'D', why: 'Oxygen là chất khí ở điều kiện thường. Nước ở thể lỏng; muối ăn và sắt ở thể rắn.' },
    { sec: 'Tính chất thể lỏng', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Đặc điểm nào sau đây KHÔNG phải là đặc điểm của chất ở thể lỏng?', opts: o4('có thể tích xác định', 'có hình dạng riêng, không đổi', 'dễ chảy, mang hình dạng của vật chứa', 'khó bị nén'), ans: 'B', why: 'Chất lỏng có thể tích xác định nhưng KHÔNG có hình dạng riêng — nó mang hình dạng của phần vật chứa. Chỉ chất rắn mới có hình dạng xác định.' },
    { sec: 'Sự chuyển thể', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Quá trình nước đá tan thành nước lỏng được gọi là:', opts: o4('sự nóng chảy', 'sự đông đặc', 'sự bay hơi', 'sự ngưng tụ'), ans: 'A', why: 'Chuyển từ thể rắn sang thể lỏng là sự nóng chảy. Quá trình ngược lại (lỏng → rắn) là sự đông đặc.' },
    { sec: 'Tính chất hóa học', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Tính chất nào sau đây là tính chất hóa học của chất?', opts: o4('màu sắc', 'khối lượng riêng', 'khả năng cháy', 'nhiệt độ sôi'), ans: 'C', why: 'Tính chất hóa học chỉ bộc lộ khi chất biến đổi thành chất khác. Khả năng cháy tạo ra chất mới nên là tính chất hóa học; màu sắc, khối lượng riêng, nhiệt độ sôi đều là tính chất vật lí.' },
    { sec: 'Sự chuyển thể', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Sương mù xuất hiện vào sáng sớm là do quá trình:', opts: o4('nóng chảy', 'bay hơi', 'đông đặc', 'ngưng tụ'), ans: 'D', why: 'Ban đêm nhiệt độ hạ xuống, hơi nước trong không khí chuyển thành những giọt nước nhỏ li ti — đó là sự ngưng tụ (khí → lỏng).' },
    { sec: 'Sự bay hơi', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Vì sao phơi quần áo ngoài nắng và nơi có gió thì quần áo nhanh khô hơn?', opts: o4('vì nhiệt độ cao và gió làm tốc độ bay hơi của nước tăng lên', 'vì nắng và gió làm nước trong quần áo đông đặc lại', 'vì gió đẩy các hạt nước trong vải rơi xuống mặt đất', 'vì nhiệt độ cao làm nước trong quần áo ngưng tụ nhanh'), ans: 'A', why: 'Tốc độ bay hơi tăng khi nhiệt độ cao hơn, gió mạnh hơn và diện tích mặt thoáng lớn hơn. Nắng cung cấp nhiệt, gió cuốn hơi nước đi nên nước bay hơi nhanh.' },
    { sec: 'Sự ngưng tụ', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Một cốc nước đá được đặt ngoài không khí. Sau 10 phút, mặt ngoài thành cốc xuất hiện nhiều giọt nước nhỏ. Các giọt nước đó từ đâu ra?', opts: o4('từ nước đá trong cốc thấm qua thành cốc ra ngoài', 'từ hơi nước trong không khí ngưng tụ trên thành cốc lạnh', 'từ nước đá nóng chảy rồi tràn qua miệng cốc xuống', 'từ thành cốc thủy tinh bị nóng chảy thành nước'), ans: 'B', why: 'Thành cốc rất lạnh làm hơi nước trong không khí tiếp xúc với nó bị ngưng tụ thành giọt. Thủy tinh không thấm nước nên phương án A sai; thủy tinh cũng chỉ nóng chảy ở nhiệt độ rất cao.' },
    { sec: 'Tính chất thể rắn', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Chất ở thể rắn có đặc điểm:', opts: o4('không có hình dạng xác định', 'rất dễ bị nén lại', 'lan ra chiếm khắp vật chứa', 'có hình dạng và thể tích xác định'), ans: 'D', why: 'Chất rắn giữ nguyên cả hình dạng lẫn thể tích. Chất lỏng chỉ giữ thể tích, còn chất khí thì không giữ cả hai.' },
    { sec: 'Biến đổi chất', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Khi đun nóng đường trắng, đường chuyển dần sang màu nâu rồi đen và bốc mùi khét. Nhận xét nào sau đây ĐÚNG?', opts: o4('đường chỉ bị nóng chảy, chất không đổi', 'đường chuyển thẳng từ thể rắn sang thể khí', 'đường đã biến đổi thành chất khác', 'đây là hiện tượng đông đặc của đường'), ans: 'C', why: 'Màu sắc đổi hẳn và có mùi khét chứng tỏ đã xuất hiện chất mới (than và các chất khác) — đây là biến đổi hóa học, không phải chỉ đổi thể.' },
    { sec: 'Sự bay hơi', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Quá trình nào sau đây là sự bay hơi?', opts: o4('nước đá tan dần trong cốc', 'nước trong ruộng cạn dần dưới nắng', 'hơi nước đọng lại trên nắp nồi', 'nước đóng băng trong ngăn đá tủ lạnh'), ans: 'B', why: 'Bay hơi là chuyển từ thể lỏng sang thể khí. Nước ruộng cạn đi vì bay hơi. A là nóng chảy, C là ngưng tụ, D là đông đặc.' },
    { sec: 'Thể của chất', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Ở điều kiện thường, sắt tồn tại ở thể:', opts: o4('rắn', 'lỏng', 'khí', 'hơi'), ans: 'A', why: 'Sắt nóng chảy ở khoảng 1538 °C, cao hơn nhiệt độ thường rất nhiều, nên ở điều kiện thường sắt ở thể rắn.' },
    { sec: 'Biến đổi chất', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Cho các quá trình: (1) đốt cháy than; (2) nước sôi bốc hơi; (3) sắt để lâu bị gỉ; (4) hòa tan muối vào nước. Những quá trình có chất mới tạo thành là:', opts: o4('(1) và (2)', '(2) và (4)', '(3) và (4)', '(1) và (3)'), ans: 'D', why: 'Đốt than sinh ra khí carbon dioxide, sắt gỉ tạo thành gỉ sắt — đều là chất mới. Nước bốc hơi chỉ đổi thể; muối tan trong nước vẫn là muối, cô cạn lại thu được muối.' },
    { sec: 'Nhiệt độ nóng chảy', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Ở áp suất thường, nhiệt độ nóng chảy của nước đá là:', opts: o4('100 °C', '−10 °C', '0 °C', '37 °C'), ans: 'C', why: 'Nước đá nóng chảy ở 0 °C. Con số 100 °C là nhiệt độ sôi của nước.' },
    { sec: 'Ứng dụng tính chất', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Vì sao người ta dùng nồi bằng kim loại để nấu ăn mà không dùng nồi bằng nhựa?', opts: o4('vì kim loại dẫn nhiệt tốt và chịu được nhiệt độ cao', 'vì kim loại luôn nhẹ hơn nhựa rất nhiều lần', 'vì kim loại có nhiều màu sắc đẹp hơn hẳn nhựa', 'vì kim loại tan được trong nước nóng khi nấu'), ans: 'A', why: 'Nấu ăn cần truyền nhiệt nhanh và chịu được nhiệt độ cao — đó là hai tính chất của kim loại. Nhựa dẫn nhiệt kém và dễ biến dạng, cháy khét khi gặp nhiệt.' },
    { sec: 'Sự chuyển thể', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Sự chuyển từ thể lỏng sang thể rắn được gọi là:', opts: o4('sự nóng chảy', 'sự đông đặc', 'sự bay hơi', 'sự ngưng tụ'), ans: 'B', why: 'Lỏng → rắn là sự đông đặc, ví dụ nước để trong ngăn đá thành nước đá.' },
    { sec: 'Vật thể nhân tạo', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Dãy nào sau đây gồm toàn các vật thể nhân tạo?', opts: o4('cây cầu, con sông, ngôi nhà', 'quyển sách, cây lúa, cái ghế', 'quyển sách, cây cầu, ngôi nhà', 'con sông, cây lúa, cây tre'), ans: 'C', why: 'Quyển sách, cây cầu và ngôi nhà đều do con người tạo ra. Con sông, cây lúa, cây tre là vật thể tự nhiên (cây lúa dù được trồng vẫn là vật thể sống tự nhiên).' },
    { sec: 'Sự bay hơi', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Để làm khô nhanh một chiếc áo ướt trong ngày trời nồm ẩm, cách nào sau đây hiệu quả nhất?', opts: o4('gấp áo lại rồi cất vào trong tủ kín', 'treo áo trong phòng và đóng kín cửa', 'nhúng áo vào nước ấm rồi treo lên', 'treo áo trước quạt gió trong phòng có máy hút ẩm'), ans: 'D', why: 'Muốn nước bay hơi nhanh cần: diện tích mặt thoáng lớn (treo ra), gió mạnh (quạt) và không khí xung quanh ít hơi nước (máy hút ẩm). Ba cách còn lại đều làm giảm ít nhất một yếu tố đó.' },
    { sec: 'Thể của chất', lvl: 'NB', name: 'Câu 21', pts: 1, text: 'Chất nào sau đây ở thể lỏng tại điều kiện thường?', opts: o4('nước', 'đá vôi', 'nhôm', 'khí nitrogen'), ans: 'A', why: 'Nước ở thể lỏng ở nhiệt độ phòng. Đá vôi và nhôm ở thể rắn, nitrogen ở thể khí.' },
    { sec: 'Tính chất thể khí', lvl: 'NC', name: 'Câu 22', pts: 1, text: 'Bơm khí vào quả bóng bay thì bóng phồng to và khí chiếm đầy quả bóng. Điều đó chứng tỏ chất khí:', opts: o4('có hình dạng riêng không thay đổi', 'có thể tích luôn xác định', 'không có hình dạng và thể tích xác định', 'luôn nặng hơn chất lỏng'), ans: 'C', why: 'Chất khí lan ra chiếm toàn bộ vật chứa nên không có hình dạng riêng và cũng không có thể tích riêng — thể tích của nó chính là thể tích bình chứa.' },
    { sec: 'Tính chất vật lí', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Tính chất nào sau đây là tính chất vật lí của đường?', opts: o4('bị cháy thành than khi đun lâu', 'tan tốt trong nước', 'lên men tạo thành rượu', 'tác dụng với oxygen khi cháy'), ans: 'B', why: 'Tan trong nước không tạo ra chất mới (cô cạn lại thu được đường) nên là tính chất vật lí. Ba hiện tượng còn lại đều sinh ra chất khác.' },
    { sec: 'Vật thể nhân tạo', lvl: 'NB', name: 'Câu 24', pts: 1, text: 'Vật thể nào sau đây là vật thể nhân tạo?', opts: o4('con sông', 'quả cam', 'đám mây', 'chiếc bút bi'), ans: 'D', why: 'Chiếc bút bi do con người chế tạo. Con sông, quả cam, đám mây đều có sẵn trong tự nhiên.' },
    { sec: 'Cấu tạo chất', lvl: 'NC', name: 'Câu 25', pts: 1, text: 'Mở lọ nước hoa ở một góc phòng, sau một lúc cả phòng đều thơm. Hiện tượng này chứng tỏ:', opts: o4('các hạt tạo nên chất luôn chuyển động và giữa chúng có khoảng cách', 'nước hoa đã bị đông đặc lại rồi tan dần ra', 'không khí trong phòng đã biến đổi thành nước hoa', 'nước hoa nặng hơn không khí nên chìm xuống sàn'), ans: 'A', why: 'Mùi lan ra khắp phòng vì các hạt nước hoa chuyển động không ngừng và len vào khoảng cách giữa các hạt không khí. Đây là bằng chứng về cấu tạo hạt của chất.' },
    { sec: 'Sự ngưng tụ', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Hiện tượng nào sau đây KHÔNG phải là sự ngưng tụ?', opts: o4('sương đọng trên lá cây buổi sớm', 'hơi nước đọng trên nắp vung nồi', 'nước trong cốc cạn dần sau vài ngày', 'mây hình thành trên bầu trời'), ans: 'C', why: 'Nước trong cốc cạn dần là sự BAY HƠI (lỏng → khí). Ba hiện tượng còn lại đều là hơi nước chuyển thành nước lỏng.' },
    { sec: 'Ba thể của nước', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Chất nào sau đây tồn tại ở cả ba thể rắn, lỏng, khí trong tự nhiên?', opts: o4('sắt', 'muối ăn', 'đá vôi', 'nước'), ans: 'D', why: 'Nước có mặt trong tự nhiên ở cả ba thể: băng tuyết (rắn), sông biển (lỏng) và hơi nước trong không khí (khí).' },
    { sec: 'Bảo toàn khối lượng', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Vì sao khi một cục nước đá tan hết thì khối lượng nước thu được vẫn bằng khối lượng cục nước đá ban đầu?', opts: o4('vì nước đá đã biến thành một chất khác có cùng khối lượng', 'vì đây chỉ là sự chuyển thể, chất vẫn là nước nên khối lượng không đổi', 'vì khối lượng của mọi chất trong mọi trường hợp đều không đổi', 'vì nước đá nhẹ hơn nước lỏng nên phần chênh lệch bù trừ nhau'), ans: 'B', why: 'Nóng chảy chỉ làm thay đổi cách sắp xếp các hạt, số hạt không đổi nên khối lượng được bảo toàn. Nước đá và nước lỏng vẫn là cùng một chất.' },
    { sec: 'Tính chất vật lí', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Muốn biết một chất có tan được trong nước hay không, ta đang tìm hiểu tính chất:', opts: o4('vật lí', 'hóa học', 'sinh học', 'cơ học'), ans: 'A', why: 'Khả năng tan là tính chất vật lí vì quá trình hòa tan không tạo ra chất mới.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Đun nóng 100 g nước đá ở 0 °C cho đến khi tan hết thành nước lỏng ở 0 °C. Khối lượng nước lỏng thu được là:', opts: o4('50 g', '200 g', '100 g', 'không xác định được'), ans: 'C', why: 'Sự nóng chảy không làm mất đi hay sinh thêm chất, nên khối lượng giữ nguyên <b>100 g</b>. Thể tích có thay đổi (nước đá xốp hơn) nhưng khối lượng thì không.' },
  ],
},

/* ═══════════ ĐỀ 5 — OXYGEN VÀ KHÔNG KHÍ ═══════════ */
{
  id: 10655, title: 'Đề 5 · Oxygen và không khí', time: 60,
  questions: [
    { sec: 'Vai trò của oxygen', lvl: 'NC', name: 'Câu 1', pts: 1, text: 'Vì sao khi úp một cốc thủy tinh lên ngọn nến đang cháy thì sau ít phút nến tắt?', opts: o4('vì cốc làm nhiệt độ quanh ngọn nến hạ xuống đột ngột', 'vì khí nitrogen trong cốc đã dập tắt ngọn lửa', 'vì hơi nước trong cốc làm ướt bấc nến', 'vì lượng oxygen trong cốc đã bị dùng hết'), ans: 'D', why: 'Sự cháy cần oxygen. Cốc úp kín nên lượng oxygen có hạn, khi dùng hết thì nến tắt dù sáp còn nhiều. Nitrogen vốn không duy trì sự cháy nhưng nó đã có sẵn từ đầu, không phải nguyên nhân làm nến tắt.' },
    { sec: 'Thành phần không khí', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Khí chiếm tỉ lệ lớn nhất trong không khí là:', opts: o4('nitrogen', 'oxygen', 'carbon dioxide', 'hơi nước'), ans: 'A', why: 'Nitrogen chiếm khoảng 78% thể tích không khí, oxygen khoảng 21%, phần còn lại khoảng 1% gồm carbon dioxide, hơi nước và các khí khác.' },
    { sec: 'Thành phần không khí', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Thành phần phần trăm theo thể tích của oxygen trong không khí vào khoảng:', opts: o4('78%', '1%', '21%', '50%'), ans: 'C', why: 'Oxygen chiếm khoảng 21% thể tích không khí. Con số 78% là của nitrogen.' },
    { sec: 'Dập tắt sự cháy', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Cách dập tắt đám cháy nào sau đây KHÔNG dựa trên nguyên tắc ngăn oxygen tiếp xúc với chất cháy?', opts: o4('trùm chăn ướt lên vật đang cháy', 'di chuyển các vật dễ cháy ra xa đám cháy', 'phủ cát lên đám cháy xăng dầu', 'phun khí carbon dioxide từ bình chữa cháy'), ans: 'B', why: 'Chăn ướt, cát và khí carbon dioxide đều tạo lớp ngăn cách chất cháy với oxygen. Còn di chuyển vật dễ cháy ra xa là nguyên tắc khác: loại bỏ chất cháy khỏi vùng lửa.' },
    { sec: 'Tính chất oxygen', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Ở điều kiện thường, oxygen là chất khí:', opts: o4('có màu xanh nhạt và mùi hắc', 'tan rất nhiều trong nước', 'nhẹ hơn không khí rất nhiều lần', 'không màu, không mùi, không vị'), ans: 'D', why: 'Oxygen không màu, không mùi, không vị, ít tan trong nước và nặng hơn không khí một chút.' },
    { sec: 'Vai trò của oxygen', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Khí oxygen cần cho quá trình nào sau đây?', opts: o4('quang hợp của cây xanh', 'hô hấp của người và động vật', 'sự bay hơi của nước', 'sự nóng chảy của kim loại'), ans: 'B', why: 'Hô hấp là quá trình lấy oxygen và thải carbon dioxide. Quang hợp thì ngược lại: cây hút carbon dioxide và nhả oxygen.' },
    { sec: 'Oxygen hòa tan', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Người ta thường bơm sục khí vào bể nuôi cá cảnh nhằm mục đích gì?', opts: o4('làm tăng lượng oxygen hòa tan trong nước cho cá hô hấp', 'làm nước trong bể luôn mát hơn nhiệt độ phòng', 'giúp thức ăn của cá tan nhanh hơn trong nước', 'làm giảm lượng nitrogen hòa tan trong nước bể'), ans: 'A', why: 'Cá lấy oxygen hòa tan trong nước qua mang. Sục khí làm oxygen từ không khí tan thêm vào nước, nhất là khi bể đông cá hoặc trời nóng.' },
    { sec: 'Ô nhiễm không khí', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Chất khí gây hiệu ứng nhà kính, làm Trái Đất nóng lên là:', opts: o4('oxygen', 'nitrogen', 'carbon dioxide', 'khí hiếm'), ans: 'C', why: 'Carbon dioxide giữ lại nhiệt phản xạ từ mặt đất, gây hiệu ứng nhà kính. Lượng khí này tăng lên chủ yếu do đốt nhiên liệu hóa thạch.' },
    { sec: 'Thí nghiệm về oxygen', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Ba ngọn nến giống hệt nhau được úp bằng ba cốc thủy tinh có thể tích lần lượt là 200 mL, 500 mL và 1000 mL. Ngọn nến nào tắt sau cùng?', opts: o4('ngọn nến trong cốc 200 mL', 'ngọn nến trong cốc 1000 mL', 'ngọn nến trong cốc 500 mL', 'ba ngọn nến tắt cùng một lúc'), ans: 'B', why: 'Cốc càng lớn thì chứa càng nhiều không khí, tức càng nhiều oxygen, nên nến cháy được lâu hơn. Cốc 1000 mL có nhiều oxygen nhất nên nến trong đó tắt sau cùng.' },
    { sec: 'Sự cháy', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Sự cháy là:', opts: o4('quá trình chất bị nóng chảy do nhiệt', 'quá trình chất tan ra trong nước nóng', 'quá trình chất bay hơi thật mạnh', 'quá trình chất tác dụng với oxygen, có tỏa nhiệt và phát sáng'), ans: 'D', why: 'Dấu hiệu nhận biết sự cháy: có chất tác dụng với oxygen, kèm theo tỏa nhiệt và phát sáng. Nóng chảy, bay hơi, hòa tan đều không sinh ra chất mới.' },
    { sec: 'Nguồn oxygen', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Nguồn cung cấp oxygen chủ yếu cho khí quyển là:', opts: o4('các nhà máy công nghiệp', 'hoạt động của núi lửa', 'quá trình quang hợp của cây xanh', 'sự bay hơi của nước biển'), ans: 'C', why: 'Cây xanh (kể cả tảo trong đại dương) quang hợp, hút carbon dioxide và nhả oxygen — đây là nguồn oxygen chính của khí quyển.' },
    { sec: 'Không khí trong phòng kín', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Vì sao ở nơi đông người, phòng kín và ít cây xanh, ta thường cảm thấy ngột ngạt?', opts: o4('vì lượng oxygen giảm dần còn carbon dioxide tăng lên', 'vì lượng nitrogen trong phòng tăng lên rất nhanh', 'vì toàn bộ hơi nước trong phòng đã bị ngưng tụ hết', 'vì nhiệt độ trong phòng luôn thấp hơn bên ngoài'), ans: 'A', why: 'Nhiều người cùng hô hấp sẽ tiêu thụ oxygen và thải ra carbon dioxide. Phòng kín không có không khí mới thay thế nên tỉ lệ oxygen giảm, gây cảm giác ngột ngạt, buồn ngủ.' },
    { sec: 'Bảo vệ không khí', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Biện pháp nào sau đây góp phần bảo vệ môi trường không khí?', opts: o4('đốt rơm rạ ngay trên đồng sau thu hoạch', 'sử dụng nhiều xe máy chạy xăng', 'đốt rác thải nhựa tại khu dân cư', 'tăng cường trồng và bảo vệ cây xanh'), ans: 'D', why: 'Cây xanh hút carbon dioxide, nhả oxygen và giữ bụi. Ba việc còn lại đều thải khói bụi và khí độc vào không khí.' },
    { sec: 'Quang hợp – hô hấp', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Nhốt một con châu chấu vào lọ thủy tinh kín có đặt thêm vài cây xanh nhỏ rồi để ngoài sáng, châu chấu sống lâu hơn so với lọ không có cây. Giải thích ĐÚNG là:', opts: o4('cây xanh làm nhiệt độ trong lọ giảm xuống', 'cây xanh quang hợp tạo thêm oxygen cho châu chấu hô hấp', 'cây xanh đã hút hết hơi nước trong lọ', 'cây xanh là thức ăn nên châu chấu no lâu hơn'), ans: 'B', why: 'Ngoài ánh sáng, cây quang hợp: hút carbon dioxide do châu chấu thải ra và nhả oxygen. Nhờ vậy lượng oxygen trong lọ được bù lại nên châu chấu sống lâu hơn.' },
    { sec: 'Vai trò của oxygen', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Khí oxygen duy trì:', opts: o4('sự đông đặc và sự bay hơi', 'sự hòa tan của muối trong nước', 'sự cháy và sự sống', 'sự ngưng tụ của hơi nước'), ans: 'C', why: 'Hai vai trò cơ bản của oxygen là duy trì sự cháy và duy trì sự sống (hô hấp của sinh vật).' },
    { sec: 'Ô nhiễm không khí', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Cho các việc làm: (1) đun bếp than trong phòng kín; (2) trồng cây xanh quanh nhà; (3) xả khói nhà máy chưa qua xử lí; (4) đi xe đạp thay xe máy khi đi gần. Những việc làm gây ô nhiễm không khí là:', opts: o4('(1) và (3)', '(2) và (4)', '(1) và (4)', '(2) và (3)'), ans: 'A', why: 'Đun than trong phòng kín sinh khí độc, xả khói chưa xử lí thải bụi và khí độc ra môi trường. Trồng cây và đi xe đạp đều là việc làm bảo vệ không khí.' },
    { sec: 'Thành phần không khí', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Ngoài nitrogen và oxygen, trong không khí còn có:', opts: o4('chỉ duy nhất hơi nước, không còn chất nào khác', 'chỉ duy nhất các khí hiếm, không có chất nào khác', 'chỉ duy nhất carbon dioxide, không có chất nào khác', 'hơi nước, carbon dioxide và một số khí khác'), ans: 'D', why: 'Khoảng 1% còn lại của không khí gồm nhiều chất: hơi nước, carbon dioxide, các khí hiếm và cả bụi.' },
    { sec: 'Tính toán thành phần', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'Một bình chứa 5 lít không khí. Biết oxygen chiếm khoảng 21% thể tích không khí. Thể tích oxygen trong bình xấp xỉ:', opts: o4('0,21 lít', '2,1 lít', '1,05 lít', '3,9 lít'), ans: 'C', why: 'Thể tích oxygen = 5 × 21 : 100 = <b>1,05 lít</b>. (Chọn 3,9 lít là tính nhầm sang phần nitrogen 78%.)' },
    { sec: 'Tính chất oxygen', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Ở điều kiện thường, oxygen tồn tại ở thể:', opts: o4('rắn', 'khí', 'lỏng', 'vừa rắn vừa lỏng'), ans: 'B', why: 'Oxygen chỉ hóa lỏng ở khoảng −183 °C, nên ở nhiệt độ thường nó ở thể khí.' },
    { sec: 'Oxygen hòa tan', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Vì sao cá có thể sống được trong nước?', opts: o4('vì trong nước có oxygen hòa tan', 'vì cá không cần oxygen để sống', 'vì cá lấy oxygen từ muối trong nước', 'vì cá phải ngoi lên mặt nước mới thở được'), ans: 'A', why: 'Oxygen ít tan trong nước nhưng vẫn đủ để cá hấp thụ qua mang. Vì vậy nước bị ô nhiễm hoặc quá nóng, oxygen hòa tan giảm thì cá dễ chết.' },
    { sec: 'An toàn phòng cháy', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Khi xảy ra cháy do chập điện, KHÔNG được dùng nước để dập lửa. Lí do chính là:', opts: o4('nước làm ngọn lửa cháy to hơn vì có oxygen', 'nước làm chất cháy tan ra và lan rộng hơn', 'nước dẫn điện nên người dập lửa có thể bị điện giật', 'nước làm nhiệt độ đám cháy tăng lên đột ngột'), ans: 'C', why: 'Nước sinh hoạt dẫn điện, nếu phun vào đám cháy điện thì dòng điện có thể truyền theo tia nước đến người. Trước hết phải ngắt cầu dao, sau đó dùng bình chữa cháy phù hợp.' },
    { sec: 'Ô nhiễm không khí', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Chất nào sau đây KHÔNG phải là chất gây ô nhiễm không khí?', opts: o4('khói bụi từ nhà máy', 'khí thải từ động cơ xe', 'khí thải từ việc đốt rác', 'hơi nước trong khí quyển'), ans: 'D', why: 'Hơi nước là thành phần tự nhiên và vô hại của không khí. Khói bụi và khí thải mới là các tác nhân gây ô nhiễm.' },
    { sec: 'Ứng dụng oxygen', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Ứng dụng nào sau đây của oxygen thuộc lĩnh vực y tế?', opts: o4('bình dưỡng khí cho bệnh nhân khó thở', 'đèn xì oxygen dùng để hàn cắt kim loại', 'cung cấp oxygen cho lò luyện gang thép', 'bình khí cho thợ lặn xuống biển sâu'), ans: 'A', why: 'Bình dưỡng khí dùng trong bệnh viện để hỗ trợ hô hấp. Hàn cắt kim loại và luyện thép thuộc công nghiệp; bình khí của thợ lặn thuộc lĩnh vực thể thao – thám hiểm.' },
    { sec: 'Không khí là hỗn hợp', lvl: 'NB', name: 'Câu 24', pts: 1, text: 'Không khí là:', opts: o4('một chất tinh khiết', 'một hỗn hợp gồm nhiều chất khí', 'một chất lỏng ở điều kiện thường', 'một nguyên tố hóa học'), ans: 'B', why: 'Không khí gồm nhiều chất trộn lẫn (nitrogen, oxygen, carbon dioxide, hơi nước…) nên là hỗn hợp, không phải chất tinh khiết.' },
    { sec: 'Thí nghiệm về oxygen', lvl: 'NC', name: 'Câu 25', pts: 1, text: 'Hai cây nến giống hệt nhau cùng được đốt cháy: một cây để ngoài không khí, một cây úp trong bình kín. Nhận xét nào ĐÚNG?', opts: o4('cả hai cây nến đều cháy hết sáp rồi mới tắt', 'cây nến trong bình kín cháy sáng hơn hẳn', 'cây nến ngoài không khí sẽ tắt trước', 'cây nến trong bình kín tắt trước dù chưa cháy hết sáp'), ans: 'D', why: 'Bình kín chỉ có lượng oxygen hữu hạn; khi oxygen cạn, nến tắt dù sáp còn nhiều. Cây nến ngoài không khí luôn được cung cấp oxygen mới nên cháy đến hết sáp.' },
    { sec: 'Sức khỏe', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Không khí bị ô nhiễm ảnh hưởng trực tiếp và nặng nề nhất đến cơ quan nào của con người?', opts: o4('hệ tiêu hóa', 'hệ bài tiết', 'hệ hô hấp', 'hệ vận động'), ans: 'C', why: 'Bụi mịn và khí độc đi thẳng vào đường thở nên hệ hô hấp chịu tác động đầu tiên và nặng nhất (viêm mũi, viêm phế quản, hen suyễn).' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 27', pts: 1, text: 'Người ta bảo quản thực phẩm bằng cách hút chân không (hút hết không khí ra khỏi túi). Cách làm này giúp thực phẩm lâu hỏng vì:', opts: o4('nhiệt độ trong túi giảm mạnh khi hút hết không khí', 'không còn oxygen nên vi khuẩn hiếu khí không phát triển được', 'túi kín làm thực phẩm hoàn toàn không bị bay hơi nước', 'áp suất trong túi làm thực phẩm đông đặc lại'), ans: 'B', why: 'Phần lớn vi khuẩn làm hỏng thức ăn cần oxygen để sống. Hút hết không khí là lấy đi oxygen nên chúng không phát triển được, đồng thời hạn chế thực phẩm bị oxi hóa.' },
    { sec: 'An toàn phòng cháy', lvl: 'NB', name: 'Câu 28', pts: 1, text: 'Để dập tắt ngọn lửa của một chảo dầu nhỏ đang cháy, việc NÊN làm là:', opts: o4('đậy nắp chảo lại', 'đổ nước vào chảo', 'bê chảo chạy ra ngoài', 'thổi thật mạnh vào chảo'), ans: 'A', why: 'Đậy nắp chảo ngăn oxygen tiếp xúc với dầu nên lửa tắt. Đổ nước vào dầu sôi sẽ làm dầu bắn tung tóe, đám cháy lan rộng rất nguy hiểm.' },
    { sec: 'Dập tắt sự cháy', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Nguyên tắc chung để dập tắt sự cháy là:', opts: o4('làm tăng nhiệt độ của chất cháy', 'cung cấp thêm oxygen cho đám cháy', 'hạ nhiệt độ và ngăn chất cháy tiếp xúc với oxygen', 'làm cho chất cháy nóng chảy nhanh hơn'), ans: 'C', why: 'Sự cháy cần đồng thời chất cháy, oxygen và nhiệt độ đủ cao. Muốn dập lửa chỉ cần phá bỏ ít nhất một trong ba điều kiện đó.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Một phòng học đóng kín có 40 học sinh. Sau hai tiết học, nhiều bạn thấy buồn ngủ và khó tập trung. Cách xử lí hợp lí nhất là:', opts: o4('bật thêm đèn cho phòng sáng hơn', 'đóng kín cửa để giữ nhiệt độ ổn định', 'bật quạt trần nhưng vẫn đóng kín cửa', 'mở cửa sổ và cửa ra vào cho không khí lưu thông'), ans: 'D', why: 'Nguyên nhân là oxygen giảm và carbon dioxide tăng trong phòng kín. Chỉ có mở cửa mới đưa được không khí mới vào; bật quạt trong phòng kín chỉ làm khối khí cũ đảo qua đảo lại.' },
  ],
},

/* ═══════════ ĐỀ 6 — VẬT LIỆU, NHIÊN LIỆU, NGUYÊN LIỆU ═══════════ */
{
  id: 10656, title: 'Đề 6 · Một số vật liệu, nhiên liệu, nguyên liệu thông dụng', time: 60,
  questions: [
    { sec: 'Tính chất vật liệu', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Vật liệu nào sau đây dẫn điện tốt?', opts: o4('đồng', 'thủy tinh', 'gỗ khô', 'cao su'), ans: 'A', why: 'Kim loại như đồng dẫn điện tốt. Thủy tinh, gỗ khô và cao su đều là vật liệu cách điện.' },
    { sec: 'Ứng dụng vật liệu', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Vì sao lõi dây điện trong nhà thường làm bằng đồng còn vỏ bọc làm bằng nhựa?', opts: o4('vì đồng rẻ hơn nhựa rất nhiều lần', 'vì nhựa dẫn điện tốt hơn đồng nên an toàn hơn', 'vì đồng nhẹ hơn nhựa nên dây dễ uốn cong', 'vì đồng dẫn điện tốt còn nhựa cách điện, tránh điện giật'), ans: 'D', why: 'Mỗi bộ phận được chọn theo đúng tính chất cần dùng: lõi phải dẫn điện (đồng), vỏ phải cách điện để người chạm vào không bị giật (nhựa).' },
    { sec: 'Phân loại nhiên liệu', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Nhiên liệu nào sau đây là nhiên liệu ở thể khí?', opts: o4('than đá', 'khí gas', 'dầu hỏa', 'củi'), ans: 'B', why: 'Khí gas (gas đun bếp) là nhiên liệu khí. Than đá và củi là nhiên liệu rắn, dầu hỏa là nhiên liệu lỏng.' },
    { sec: 'Nguyên liệu', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'Nguyên liệu chính để sản xuất xi măng là:', opts: o4('quặng sắt', 'cát trắng', 'đá vôi và đất sét', 'dầu mỏ'), ans: 'C', why: 'Xi măng được nung từ hỗn hợp đá vôi và đất sét. Cát trắng là nguyên liệu làm thủy tinh, quặng sắt dùng để luyện gang thép.' },
    { sec: 'An toàn nhiên liệu', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Vì sao tuyệt đối không được đun bếp than trong phòng kín?', opts: o4('vì than cháy sinh khí carbon monoxide rất độc, dễ gây ngạt', 'vì than cháy làm nhiệt độ trong phòng giảm xuống đột ngột', 'vì than cháy sinh ra quá nhiều oxygen gây khó thở', 'vì than cháy tạo ra hơi nước làm phòng bị ẩm ướt'), ans: 'A', why: 'Trong phòng kín thiếu oxygen, than cháy không hoàn toàn sinh ra khí carbon monoxide không màu, không mùi và rất độc. Đây là nguyên nhân nhiều vụ ngạt khí thương tâm.' },
    { sec: 'Tính chất vật liệu', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'Vật liệu nào sau đây dễ bị gỉ khi để lâu trong không khí ẩm?', opts: o4('thủy tinh', 'nhựa', 'sắt', 'gốm'), ans: 'C', why: 'Sắt tác dụng với oxygen và hơi nước trong không khí tạo thành gỉ sắt. Thủy tinh, nhựa, gốm đều không bị gỉ.' },
    { sec: 'Ứng dụng vật liệu', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'Tính chất nào khiến nhựa được dùng rộng rãi để làm đồ gia dụng?', opts: o4('dẫn nhiệt và dẫn điện đều rất tốt', 'rất cứng và có khối lượng rất nặng', 'chịu được nhiệt độ rất cao khi đun nấu', 'nhẹ, bền, dễ tạo hình và không bị gỉ'), ans: 'D', why: 'Nhựa nhẹ, dễ ép thành mọi hình dạng, không gỉ và giá rẻ nên rất phổ biến. Nhược điểm của nhựa là không chịu được nhiệt cao và khó phân hủy.' },
    { sec: 'Rác thải nhựa', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Túi ni lông và chai nhựa dùng một lần gây hại cho môi trường chủ yếu vì:', opts: o4('chúng bốc cháy rất dễ dàng ngay trong tự nhiên', 'chúng rất khó phân hủy, tồn tại hàng trăm năm trong đất', 'chúng tan nhanh trong nước khiến nguồn nước bị đục', 'chúng hút hết oxygen có trong đất và trong nước'), ans: 'B', why: 'Nhựa phải mất hàng trăm năm mới phân hủy, tích tụ trong đất và đại dương, làm sinh vật mắc kẹt hoặc nuốt phải. Nhựa cũng không tan trong nước.' },
    { sec: 'Khái niệm nguyên liệu', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Nguyên liệu là:', opts: o4('vật liệu tự nhiên chưa qua xử lí, dùng để sản xuất', 'sản phẩm đã hoàn thiện, đem bán ra thị trường', 'chất đốt dùng để tạo ra nhiệt và ánh sáng', 'mọi vật thể nhân tạo có trong đời sống'), ans: 'A', why: 'Nguyên liệu là vật liệu tự nhiên chưa qua chế biến, được dùng làm đầu vào cho sản xuất — ví dụ đá vôi, quặng, cát. Phương án C là định nghĩa của nhiên liệu.' },
    { sec: 'Sử dụng nhiên liệu', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Một gia đình dùng hết một bình gas 12 kg trong 60 ngày. Nếu mỗi ngày dùng nhiều gấp đôi thì bình gas đó dùng được bao nhiêu ngày?', opts: o4('120 ngày', '60 ngày', '30 ngày', '24 ngày'), ans: 'C', why: 'Lượng gas không đổi, mỗi ngày dùng gấp đôi thì số ngày giảm đi một nửa: 60 : 2 = <b>30 ngày</b>. (Chọn 120 ngày là nhân thay vì chia.)' },
    { sec: 'Nhiên liệu tái tạo', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'Nhiên liệu nào sau đây thuộc nhóm nhiên liệu tái tạo?', opts: o4('than đá', 'củi gỗ', 'dầu mỏ', 'khí thiên nhiên'), ans: 'B', why: 'Củi gỗ lấy từ cây trồng — có thể trồng lại trong vài năm nên là nhiên liệu tái tạo. Than đá, dầu mỏ và khí thiên nhiên hình thành qua hàng triệu năm nên không tái tạo được.' },
    { sec: 'Tính chất vật liệu', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Cho các vật: cốc thủy tinh, thìa inox, lốp xe, bàn gỗ. Vật nào được làm từ vật liệu KHÔNG dẫn điện và có tính đàn hồi tốt?', opts: o4('cốc thủy tinh', 'thìa inox', 'bàn gỗ', 'lốp xe'), ans: 'D', why: 'Lốp xe làm từ cao su: vừa cách điện vừa đàn hồi tốt. Thủy tinh và gỗ tuy cách điện nhưng không đàn hồi; inox thì dẫn điện.' },
    { sec: 'Tính chất vật liệu', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Vật liệu nào sau đây trong suốt, cho ánh sáng truyền qua?', opts: o4('thủy tinh', 'gỗ', 'thép', 'gạch'), ans: 'A', why: 'Thủy tinh trong suốt nên được dùng làm cửa kính, cốc, ống nghiệm.' },
    { sec: 'Ứng dụng vật liệu', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Vì sao cán xoong, cán chảo thường làm bằng nhựa hoặc gỗ thay vì bằng kim loại?', opts: o4('vì nhựa và gỗ dẫn nhiệt tốt hơn hẳn kim loại', 'vì nhựa và gỗ nặng hơn nên cầm chắc tay hơn', 'vì nhựa và gỗ dẫn nhiệt kém nên cầm không bị bỏng', 'vì nhựa và gỗ chịu được nhiệt độ cao hơn kim loại'), ans: 'C', why: 'Nhựa và gỗ dẫn nhiệt kém nên nhiệt từ nồi truyền tới tay rất chậm. Ngược lại kim loại dẫn nhiệt tốt, chỉ một lúc là cán nóng rực.' },
    { sec: 'Tiết kiệm nhiên liệu', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Việc làm nào sau đây giúp sử dụng nhiên liệu tiết kiệm và hiệu quả?', opts: o4('để ngọn lửa bếp gas cháy loe rộng hơn đáy nồi', 'tắt bếp ngay khi thức ăn vừa chín tới', 'đun đầy ấm nước rồi đổ bỏ phần dùng không hết', 'mở nắp nồi trong suốt quá trình đun nấu'), ans: 'B', why: 'Tắt bếp đúng lúc tránh đốt nhiên liệu vô ích. Ngọn lửa loe ra ngoài đáy nồi, đun thừa nước và mở nắp nồi đều làm thất thoát nhiệt.' },
    { sec: 'Nhiên liệu hóa thạch', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Dầu mỏ, than đá và khí thiên nhiên được gọi chung là:', opts: o4('nhiên liệu tái tạo', 'nguyên liệu kim loại', 'vật liệu xây dựng', 'nhiên liệu hóa thạch'), ans: 'D', why: 'Chúng hình thành từ xác sinh vật bị vùi lấp hàng triệu năm nên gọi là nhiên liệu hóa thạch, và là nguồn không tái tạo.' },
    { sec: 'Giảm rác thải nhựa', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Cho các biện pháp: (1) phân loại rác tại nguồn; (2) dùng túi vải khi đi chợ; (3) đốt rác nhựa ngoài trời; (4) tái chế chai nhựa thành chậu trồng cây. Những biện pháp làm giảm tác hại của rác thải nhựa là:', opts: o4('(1), (2) và (3)', '(2), (3) và (4)', '(1), (2) và (4)', '(1), (3) và (4)'), ans: 'C', why: 'Phân loại, thay túi ni lông bằng túi vải và tái chế đều làm giảm lượng nhựa thải ra. Riêng đốt nhựa ngoài trời sinh khí độc, gây ô nhiễm không khí nên phải loại.' },
    { sec: 'Nguyên liệu', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Quặng là:', opts: o4('loại đá chứa nhiều khoáng chất dùng để khai thác kim loại', 'sản phẩm kim loại đã được luyện xong và đem bán', 'loại nhiên liệu chuyên dùng trong các lò nung gạch', 'vật liệu nhân tạo dùng nhiều trong xây dựng nhà cửa'), ans: 'A', why: 'Quặng là nguyên liệu tự nhiên: loại đá chứa hàm lượng khoáng chất đủ lớn để khai thác kim loại, ví dụ quặng sắt dùng luyện gang thép.' },
    { sec: 'Nguyên liệu', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Nguyên liệu chính để sản xuất thủy tinh là:', opts: o4('đất sét', 'quặng bauxite', 'gỗ', 'cát'), ans: 'D', why: 'Thủy tinh được nấu chủ yếu từ cát (cát trắng). Đất sét làm gốm, bauxite làm nhôm.' },
    { sec: 'Tiết kiệm năng lượng', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Một bóng đèn sợi đốt 100 W và một bóng đèn LED 10 W cho độ sáng tương đương. Nếu mỗi ngày bật 5 giờ, dùng đèn LED thay đèn sợi đốt tiết kiệm được bao nhiêu điện năng trong một ngày?', opts: o4('0,05 kWh', '0,45 kWh', '0,5 kWh', '4,5 kWh'), ans: 'B', why: 'Công suất tiết kiệm được là 100 − 10 = 90 W = 0,09 kW. Trong 5 giờ: 0,09 × 5 = <b>0,45 kWh</b>. (Chọn 0,5 kWh là quên trừ phần 10 W của đèn LED.)' },
    { sec: 'Tái chế', lvl: 'TH', name: 'Câu 21', pts: 1, text: 'Vật liệu nào sau đây có thể tái chế được?', opts: o4('lon nhôm đựng nước ngọt', 'giấy ăn đã qua sử dụng', 'vỏ trứng gà', 'thức ăn thừa'), ans: 'A', why: 'Nhôm nấu chảy được nên lon nhôm tái chế rất hiệu quả. Giấy ăn bẩn, vỏ trứng và thức ăn thừa thuộc nhóm rác hữu cơ, nên ủ làm phân chứ không tái chế.' },
    { sec: 'An toàn vật liệu', lvl: 'NC', name: 'Câu 22', pts: 1, text: 'Một bạn dùng cốc nhựa mỏng để đựng nước nóng 90 °C. Nhận xét nào sau đây ĐÚNG?', opts: o4('nên làm vậy vì nhựa dẫn nhiệt tốt, nước sẽ nhanh nguội', 'nên làm vậy vì cốc nhựa bền hơn cốc thủy tinh chịu nhiệt', 'không nên, vì nhựa sẽ tan hết hoàn toàn vào trong nước', 'không nên, vì cốc nhựa mỏng dễ biến dạng và có thể thôi chất độc ra nước'), ans: 'D', why: 'Nhựa mỏng không chịu được nhiệt độ cao: cốc dễ mềm, biến dạng và một số loại nhựa giải phóng chất có hại vào nước. Nên dùng cốc thủy tinh chịu nhiệt hoặc cốc sứ.' },
    { sec: 'Khái niệm nhiên liệu', lvl: 'NB', name: 'Câu 23', pts: 1, text: 'Nhiên liệu là những chất:', opts: o4('dùng để xây nhà và làm cầu đường', 'có sẵn trong tự nhiên, chưa qua chế biến', 'khi cháy tỏa nhiệt và phát sáng', 'dùng để hòa tan các chất khác'), ans: 'C', why: 'Nhiên liệu là chất cháy được, khi cháy tỏa nhiệt và phát sáng, dùng để cung cấp năng lượng — ví dụ than, củi, xăng, gas.' },
    { sec: 'Sự cháy', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Vì sao chẻ nhỏ củi rồi mới đốt thì củi cháy nhanh hơn để nguyên thanh to?', opts: o4('vì củi nhỏ chứa nhiều chất cháy hơn củi to', 'vì củi nhỏ có diện tích tiếp xúc với oxygen lớn hơn', 'vì củi nhỏ có nhiệt độ bắt cháy thấp hơn rất nhiều', 'vì củi nhỏ hút được nhiều hơi nước trong không khí'), ans: 'B', why: 'Cùng một khối lượng, củi chẻ nhỏ có tổng diện tích bề mặt lớn hơn nên tiếp xúc với oxygen nhiều hơn, phản ứng cháy xảy ra nhanh hơn. Đây cũng là lí do than tổ ong được đục nhiều lỗ.' },
    { sec: 'Tính chất vật liệu', lvl: 'TH', name: 'Câu 25', pts: 1, text: 'Vật liệu nào thường được dùng làm lốp xe nhờ tính đàn hồi tốt?', opts: o4('cao su', 'thủy tinh', 'gốm sứ', 'nhôm'), ans: 'A', why: 'Cao su đàn hồi, chịu mài mòn và không thấm nước nên rất thích hợp làm lốp xe.' },
    { sec: 'Phân biệt khái niệm', lvl: 'NC', name: 'Câu 26', pts: 1, text: 'Một bạn nói: "Mọi vật liệu đều là nguyên liệu." Nhận xét nào sau đây ĐÚNG?', opts: o4('đúng, vì hai khái niệm này hoàn toàn giống nhau', 'đúng, vì vật liệu nào cũng lấy trực tiếp từ tự nhiên', 'sai, vì nguyên liệu luôn là sản phẩm đã qua chế biến', 'sai, vì nhiều vật liệu như nhựa, thép là sản phẩm đã qua chế biến'), ans: 'D', why: 'Nguyên liệu là vật liệu tự nhiên chưa qua chế biến. Nhựa và thép do con người sản xuất từ dầu mỏ, quặng sắt nên là vật liệu nhưng không phải nguyên liệu. Phương án C nói ngược định nghĩa.' },
    { sec: 'Tính chất vật liệu', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Vật liệu nào sau đây cách nhiệt tốt, thường dùng làm tay cầm của nồi?', opts: o4('nhôm', 'đồng', 'gỗ', 'thép'), ans: 'C', why: 'Gỗ dẫn nhiệt kém nên cầm không bị nóng. Nhôm, đồng và thép đều là kim loại dẫn nhiệt tốt.' },
    { sec: 'Bảo quản vật liệu', lvl: 'TH', name: 'Câu 28', pts: 1, text: 'Để bảo quản đồ dùng bằng sắt được bền lâu, ta nên:', opts: o4('ngâm trong nước cho sạch bụi bẩn', 'lau khô rồi sơn phủ lên bề mặt', 'để nơi ẩm ướt cho khỏi bị khô nứt', 'rửa bằng nước muối rồi đem phơi nắng'), ans: 'B', why: 'Sắt gỉ khi tiếp xúc với oxygen và hơi nước, nên phải giữ khô và phủ sơn/dầu mỡ để ngăn cách với không khí ẩm. Nước và nước muối đều làm sắt gỉ nhanh hơn.' },
    { sec: 'Nguyên liệu', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Xăng và dầu diesel được sản xuất từ:', opts: o4('dầu mỏ', 'than đá', 'đá vôi', 'cát'), ans: 'A', why: 'Dầu mỏ được chưng cất tách thành xăng, dầu hỏa, dầu diesel, nhựa đường…' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Nhà bạn Nam mỗi tháng thải ra khoảng 60 chai nhựa. Nếu cả 20 nhà trong xóm đều phân loại và đem tái chế thì trong một năm có bao nhiêu chai nhựa được tái chế?', opts: o4('1200 chai', '7200 chai', '14400 chai', '1440 chai'), ans: 'C', why: 'Mỗi tháng cả xóm thải 60 × 20 = 1200 chai; trong 12 tháng là 1200 × 12 = <b>14400 chai</b>. (Chọn 1200 chai là quên nhân với 12 tháng.)' },
  ],
},

/* ═══════════ ĐỀ 7 — CHẤT TINH KHIẾT. HỖN HỢP. DUNG DỊCH ═══════════ */
{
  id: 10657, title: 'Đề 7 · Chất tinh khiết, hỗn hợp, dung dịch', time: 60,
  questions: [
    { sec: 'Chất tinh khiết', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Chất tinh khiết là chất:', opts: o4('chỉ gồm một chất duy nhất', 'gồm hai chất trở lên trộn lẫn', 'luôn tồn tại ở thể lỏng', 'luôn tan tốt trong nước'), ans: 'A', why: 'Chất tinh khiết chỉ do một chất tạo nên nên có tính chất xác định (nhiệt độ sôi, nhiệt độ nóng chảy cố định). Từ hai chất trở lên trộn lẫn thì gọi là hỗn hợp.' },
    { sec: 'Phân loại', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Cho các mẫu: nước biển, nước cất, không khí, khí oxygen tinh khiết. Số chất tinh khiết là:', opts: o4('1', '3', '2', '4'), ans: 'C', why: 'Chỉ có nước cất và khí oxygen tinh khiết là chất tinh khiết — <b>2</b> mẫu. Nước biển chứa muối và nhiều chất khác; không khí là hỗn hợp nhiều chất khí.' },
    { sec: 'Chất tan – dung môi', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Khi hòa tan đường vào nước, đường được gọi là:', opts: o4('dung môi', 'chất tan', 'dung dịch', 'huyền phù'), ans: 'B', why: 'Chất bị hòa tan là chất tan (đường); chất dùng để hòa tan là dung môi (nước); sản phẩm thu được là dung dịch (nước đường).' },
    { sec: 'Dung dịch', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Hỗn hợp nào sau đây là một dung dịch?', opts: o4('nước và cát', 'nước và dầu ăn', 'nước và bột mì', 'nước và muối ăn'), ans: 'D', why: 'Chỉ muối ăn tan hoàn toàn trong nước tạo hỗn hợp đồng nhất nên nước muối là dung dịch. Cát và bột mì không tan (huyền phù), dầu ăn không tan và nổi lên (nhũ tương).' },
    { sec: 'Chất tan – dung môi', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Trong nước đường, dung môi là:', opts: o4('nước', 'đường', 'cả nước và đường', 'không có dung môi'), ans: 'A', why: 'Nước là chất dùng để hòa tan đường nên nước là dung môi.' },
    { sec: 'Hỗn hợp đồng nhất', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Hỗn hợp đồng nhất là hỗn hợp:', opts: o4('có thể nhìn thấy rõ từng thành phần', 'gồm chất rắn lơ lửng trong chất lỏng', 'luôn tách lớp sau một thời gian', 'có thành phần giống nhau ở mọi vị trí'), ans: 'D', why: 'Trong hỗn hợp đồng nhất, các chất trộn đều tới mức lấy ở bất kì chỗ nào cũng có thành phần như nhau — ví dụ nước muối. Ba phương án còn lại đều mô tả hỗn hợp KHÔNG đồng nhất.' },
    { sec: 'Tốc độ hòa tan', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Vì sao khi khuấy đều và đun nóng thì đường tan nhanh hơn trong nước?', opts: o4('vì đường biến thành chất khác khi gặp nhiệt', 'vì nước nóng nặng hơn nước lạnh nhiều lần', 'vì các hạt chuyển động nhanh hơn nên trộn nhanh hơn', 'vì đường bị nóng chảy hoàn toàn trước khi tan'), ans: 'C', why: 'Khuấy và đun nóng đều làm các hạt đường và hạt nước chuyển động nhanh hơn, va chạm nhiều hơn nên quá trình hòa tan diễn ra nhanh hơn. Bản chất đường không đổi — cô cạn vẫn thu lại được đường.' },
    { sec: 'Dung dịch', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Nước muối sinh lí dùng để rửa mắt, rửa mũi là một:', opts: o4('chất tinh khiết', 'dung dịch', 'huyền phù', 'nhũ tương'), ans: 'B', why: 'Muối tan hoàn toàn trong nước tạo hỗn hợp đồng nhất, trong suốt — đó là dung dịch.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Hòa tan hoàn toàn 20 g muối vào 180 g nước. Khối lượng dung dịch nước muối thu được là:', opts: o4('160 g', '180 g', '20 g', '200 g'), ans: 'D', why: 'Khối lượng dung dịch = khối lượng chất tan + khối lượng dung môi = 20 + 180 = <b>200 g</b>. Hòa tan không làm mất đi chất nào.' },
    { sec: 'Huyền phù', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Hỗn hợp nào sau đây là huyền phù?', opts: o4('nước chanh đã lọc trong', 'nước bột sắn dây vừa khuấy lên', 'giấm ăn', 'nước muối'), ans: 'B', why: 'Huyền phù gồm các hạt chất RẮN nhỏ lơ lửng trong chất lỏng, để yên sẽ lắng xuống — đúng với nước bột sắn dây. Ba hỗn hợp còn lại đều đồng nhất.' },
    { sec: 'Phân loại', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Cho các hỗn hợp: (1) nước và cồn; (2) dầu ăn và nước; (3) muối và nước; (4) cát và nước. Những hỗn hợp đồng nhất là:', opts: o4('(1) và (3)', '(2) và (4)', '(1) và (2)', '(3) và (4)'), ans: 'A', why: 'Cồn tan vô hạn trong nước, muối tan hoàn toàn trong nước nên (1) và (3) đồng nhất. Dầu ăn tách lớp, cát lắng xuống đáy nên (2) và (4) không đồng nhất.' },
    { sec: 'Nhũ tương', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Sữa tươi là một ví dụ của:', opts: o4('chất tinh khiết', 'dung dịch trong suốt', 'nhũ tương', 'kim loại'), ans: 'C', why: 'Sữa gồm các giọt chất béo rất nhỏ lơ lửng trong nước nên là nhũ tương.' },
    { sec: 'Tốc độ hòa tan', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Yếu tố nào sau đây KHÔNG làm tăng tốc độ hòa tan một chất rắn trong nước?', opts: o4('khuấy đều hỗn hợp', 'đun nóng nước', 'nghiền nhỏ chất rắn', 'làm lạnh nước xuống gần 0 °C'), ans: 'D', why: 'Hạ nhiệt độ làm các hạt chuyển động chậm lại nên chất rắn tan CHẬM hơn. Ba yếu tố còn lại đều đẩy nhanh quá trình hòa tan.' },
    { sec: 'Không khí là hỗn hợp', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Vì sao không khí được coi là hỗn hợp chứ không phải chất tinh khiết?', opts: o4('vì không khí gồm nhiều chất khí khác nhau trộn lẫn', 'vì không khí luôn ở thể khí trong mọi điều kiện', 'vì không khí không có màu và cũng không có mùi', 'vì không khí có thể bị nén lại rất dễ dàng'), ans: 'A', why: 'Không khí chứa nitrogen, oxygen, carbon dioxide, hơi nước… trộn lẫn nên là hỗn hợp. Không màu, không mùi hay dễ nén đều không phải dấu hiệu phân biệt chất tinh khiết với hỗn hợp.' },
    { sec: 'Chất tinh khiết', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Nước cất là:', opts: o4('nước khoáng được đóng chai', 'nước tinh khiết, không lẫn chất khác', 'nước biển đã được lọc sạch cát', 'nước máy đã được đun sôi'), ans: 'B', why: 'Nước cất thu được bằng cách chưng cất nên chỉ còn nước, không lẫn tạp chất. Nước khoáng và nước máy đun sôi vẫn còn muối khoáng hòa tan.' },
    { sec: 'Dung dịch bão hòa', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Bạn An cho 5 g muối vào 100 mL nước và khuấy tan hết. Bạn cho tiếp nhiều muối nữa, khuấy mãi vẫn còn muối lắng dưới đáy. Nhận xét nào ĐÚNG?', opts: o4('muối đã biến đổi thành một chất khác', 'nước không còn là dung môi nữa', 'dung dịch đã bão hòa, không hòa tan thêm được muối', 'lượng muối cho vào quá ít nên không tan được'), ans: 'C', why: 'Ở mỗi nhiệt độ, một lượng nước chỉ hòa tan được tối đa một lượng chất tan nhất định. Khi đạt mức đó thì dung dịch bão hòa và muối thêm vào sẽ lắng xuống.' },
    { sec: 'Nhũ tương', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Nhũ tương là hỗn hợp:', opts: o4('gồm các giọt chất lỏng lơ lửng trong chất lỏng khác', 'gồm chất rắn tan hoàn toàn trong chất lỏng', 'gồm hai chất khí trộn lẫn hoàn toàn vào nhau', 'gồm chất rắn không tan lắng hết xuống đáy'), ans: 'A', why: 'Nhũ tương là hỗn hợp của hai chất LỎNG không tan vào nhau, một chất phân tán thành giọt nhỏ trong chất kia — ví dụ sữa, mayonnaise.' },
    { sec: 'Dung dịch', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Dung dịch là hỗn hợp:', opts: o4('không đồng nhất của chất rắn và chất lỏng', 'gồm các giọt dầu lơ lửng trong nước', 'luôn tách thành hai lớp khi để yên', 'đồng nhất của chất tan và dung môi'), ans: 'D', why: 'Định nghĩa: dung dịch là hỗn hợp đồng nhất của chất tan và dung môi, ví dụ nước muối, nước đường.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'Để pha nước chanh, bạn Lan dùng 2 thìa đường cho mỗi cốc 200 mL nước. Muốn pha 1 lít nước chanh theo đúng tỉ lệ đó, Lan cần bao nhiêu thìa đường?', opts: o4('5 thìa', '10 thìa', '4 thìa', '20 thìa'), ans: 'B', why: 'Đổi 1 lít = 1000 mL. Số cốc 200 mL là 1000 : 200 = 5. Số thìa đường = 5 × 2 = <b>10 thìa</b>. (Chọn 5 thìa là quên nhân với 2 thìa mỗi cốc.)' },
    { sec: 'Huyền phù', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Hiện tượng chất rắn lắng xuống đáy cốc sau khi để yên cho thấy hỗn hợp đó là:', opts: o4('dung dịch', 'chất tinh khiết', 'huyền phù', 'nhũ tương'), ans: 'C', why: 'Chất rắn không tan, lơ lửng rồi lắng xuống là đặc điểm của huyền phù. Dung dịch thì trong suốt và không lắng.' },
    { sec: 'Nhũ tương', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Trộn dầu ăn với nước rồi lắc mạnh; sau một lúc để yên thì hỗn hợp tách thành hai lớp. Nhận xét nào ĐÚNG?', opts: o4('dầu ăn không tan trong nước nên tạo nhũ tương không bền', 'dầu ăn đã tan hoàn toàn tạo thành một dung dịch', 'dầu ăn đã biến đổi thành chất mới khi bị lắc mạnh', 'nước đã bay hơi hết nên dầu ăn nổi lên trên'), ans: 'A', why: 'Lắc mạnh chỉ chia dầu thành các giọt nhỏ phân tán tạm thời trong nước (nhũ tương). Vì dầu không tan và nhẹ hơn nước nên các giọt gộp lại rồi nổi lên, hỗn hợp tách lớp.' },
    { sec: 'Chất tinh khiết', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Chất nào sau đây là chất tinh khiết?', opts: o4('nước khoáng', 'nước ngọt có ga', 'nước mắm', 'khí nitrogen tinh khiết'), ans: 'D', why: 'Ba mẫu đầu đều chứa nhiều chất trộn lẫn nên là hỗn hợp; chỉ khí nitrogen tinh khiết chỉ gồm một chất.' },
    { sec: 'Chất tan – dung môi', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Trong cốc nước muối, thành phần nào là chất tan?', opts: o4('nước', 'cốc thủy tinh', 'muối ăn', 'không khí'), ans: 'C', why: 'Muối ăn là chất bị hòa tan nên là chất tan; nước đóng vai trò dung môi.' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Vì sao ở vùng ven biển người ta có thể làm ra muối ăn từ nước biển?', opts: o4('vì muối trong nước biển tự đông đặc khi trời nắng to', 'vì nước bay hơi dần, còn muối không bay hơi nên kết tinh lại', 'vì ánh nắng mặt trời biến nước biển thành muối', 'vì muối nặng hơn nước nên lắng xuống đáy ruộng'), ans: 'B', why: 'Nắng và gió làm nước bay hơi, muối vốn không bay hơi nên ngày càng đặc lại rồi kết tinh thành hạt. Đây chính là phương pháp cô cạn nhờ năng lượng Mặt Trời.' },
    { sec: 'Hỗn hợp', lvl: 'NB', name: 'Câu 25', pts: 1, text: 'Hỗn hợp là:', opts: o4('gồm từ hai chất trở lên trộn lẫn với nhau', 'chỉ gồm duy nhất một chất', 'luôn là chất lỏng trong suốt', 'một nguyên tố hóa học'), ans: 'A', why: 'Hỗn hợp gồm từ hai chất trở lên trộn lẫn; mỗi chất trong hỗn hợp vẫn giữ nguyên tính chất của nó.' },
    { sec: 'Tốc độ hòa tan', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Với phần lớn chất rắn, khả năng hòa tan trong nước sẽ:', opts: o4('giảm đi khi nhiệt độ tăng', 'không phụ thuộc vào nhiệt độ', 'tăng lên khi nhiệt độ tăng', 'bằng 0 khi nước được đun nóng'), ans: 'C', why: 'Nước càng nóng thì hòa tan được càng nhiều chất rắn — vì vậy pha nước đường bằng nước ấm dễ hơn nước lạnh.' },
    { sec: 'Phân loại', lvl: 'NC', name: 'Câu 27', pts: 1, text: 'Trong các hỗn hợp sau, hỗn hợp KHÔNG đồng nhất là:', opts: o4('nước ngọt có ga', 'nước muối', 'nước đường', 'nước phù sa'), ans: 'D', why: 'Nước phù sa chứa các hạt đất nhỏ lơ lửng, để lâu sẽ lắng xuống nên không đồng nhất (huyền phù). Ba hỗn hợp còn lại đều trong suốt và đồng nhất.' },
    { sec: 'Chất không tan', lvl: 'NB', name: 'Câu 28', pts: 1, text: 'Trong hỗn hợp nước và cát, cát:', opts: o4('tan hoàn toàn trong nước', 'không tan và lắng xuống đáy', 'bay hơi cùng với nước', 'biến đổi thành một chất mới'), ans: 'B', why: 'Cát không tan trong nước; khi để yên, các hạt cát nặng hơn nước nên lắng xuống đáy.' },
    { sec: 'Dung môi', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Dung môi phổ biến nhất trong đời sống là:', opts: o4('nước', 'dầu ăn', 'cồn', 'xăng'), ans: 'A', why: 'Nước hòa tan được rất nhiều chất nên được gọi là dung môi phổ biến. Cồn và xăng cũng là dung môi nhưng ít dùng hơn trong sinh hoạt.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Hòa tan hết 15 g đường vào 135 g nước, sau đó đun cho nước bay hơi hoàn toàn. Khối lượng chất rắn thu được là:', opts: o4('150 g', '135 g', '0 g', '15 g'), ans: 'D', why: 'Chỉ có nước bay hơi, còn đường ở lại nên thu được đúng <b>15 g</b> đường như ban đầu. (Chọn 150 g là cộng cả khối lượng nước đã bay đi.)' },
  ],
},

/* ═══════════ ĐỀ 8 — TÁCH CHẤT RA KHỎI HỖN HỢP ═══════════ */
{
  id: 10658, title: 'Đề 8 · Tách chất ra khỏi hỗn hợp', time: 60,
  questions: [
    { sec: 'Phương pháp lọc', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Để tách cát ra khỏi hỗn hợp cát và nước, ta dùng phương pháp:', opts: o4('cô cạn', 'lọc', 'chưng cất', 'chiết'), ans: 'B', why: 'Cát không tan trong nước nên giấy lọc giữ lại được cát, nước chảy qua. Cô cạn sẽ làm mất nước một cách vô ích.' },
    { sec: 'Phương pháp lọc', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Vì sao dùng được phương pháp lọc để tách cát khỏi nước nhưng KHÔNG tách được muối khỏi nước muối?', opts: o4('vì muối nặng hơn cát rất nhiều lần', 'vì giấy lọc chỉ giữ lại được chất lỏng', 'vì muối bay hơi cùng với nước khi lọc', 'vì muối tan trong nước nên đi qua giấy lọc cùng với nước'), ans: 'D', why: 'Lọc chỉ giữ lại được chất rắn KHÔNG tan. Muối đã tan thành những hạt rất nhỏ hòa lẫn trong nước nên lọt qua lỗ giấy lọc cùng với nước.' },
    { sec: 'Phương pháp cô cạn', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Để tách muối ra khỏi nước muối, ta dùng phương pháp:', opts: o4('cô cạn', 'lọc', 'chiết', 'dùng nam châm'), ans: 'A', why: 'Đun cho nước bay hơi hết, muối không bay hơi nên còn lại — đó là phương pháp cô cạn.' },
    { sec: 'Dùng từ tính', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'Người ta dùng nam châm để tách:', opts: o4('muối khỏi nước muối', 'cát khỏi nước', 'mạt sắt khỏi bột gỗ', 'dầu ăn khỏi nước'), ans: 'C', why: 'Sắt bị nam châm hút còn bột gỗ thì không, nên đưa nam châm qua hỗn hợp sẽ hút riêng được mạt sắt.' },
    { sec: 'Phương pháp chiết', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Dùng phễu chiết để tách hỗn hợp dầu ăn và nước là dựa trên tính chất nào?', opts: o4('dầu ăn bay hơi nhanh hơn nước rất nhiều', 'dầu ăn không tan trong nước và nổi lên trên', 'dầu ăn có màu vàng còn nước thì không màu', 'dầu ăn đông đặc ngay ở nhiệt độ thường'), ans: 'B', why: 'Vì không tan và nhẹ hơn nước, dầu nổi thành lớp riêng phía trên. Mở khóa phễu chiết cho nước chảy xuống trước, dầu sẽ ở lại — tách được hai chất.' },
    { sec: 'Dụng cụ', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'Dụng cụ nào sau đây dùng để lọc?', opts: o4('phễu lọc và giấy lọc', 'nam châm', 'đèn cồn', 'nhiệt kế'), ans: 'A', why: 'Giấy lọc đặt trong phễu giữ lại chất rắn không tan, chất lỏng chảy qua xuống bình hứng.' },
    { sec: 'Tách hỗn hợp nhiều chất', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Cho hỗn hợp gồm muối ăn, cát và mạt sắt. Thứ tự các bước tách hợp lí nhất là:', opts: o4('lọc → cô cạn → dùng nam châm', 'cô cạn → lọc → dùng nam châm', 'lọc → dùng nam châm → cô cạn', 'dùng nam châm → hòa tan và lọc → cô cạn'), ans: 'D', why: 'Phải hút mạt sắt bằng nam châm khi hỗn hợp còn khô. Sau đó hòa vào nước: cát bị giữ lại trên giấy lọc, cuối cùng cô cạn nước lọc để thu muối. Nếu hòa nước trước thì mạt sắt ướt sẽ dính vào cát, rất khó tách.' },
    { sec: 'Phương pháp cô cạn', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Phương pháp cô cạn tách chất dựa trên sự khác nhau về:', opts: o4('kích thước hạt', 'từ tính', 'khả năng bay hơi', 'màu sắc'), ans: 'C', why: 'Nước bay hơi được còn muối thì không, nhờ chênh lệch khả năng bay hơi mà tách được hai chất.' },
    { sec: 'Phương pháp chưng cất', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Nước cất được điều chế bằng phương pháp:', opts: o4('chưng cất', 'lọc', 'dùng nam châm', 'chiết'), ans: 'A', why: 'Đun nước cho bay hơi rồi làm lạnh cho hơi nước ngưng tụ lại, thu được nước tinh khiết — đó là chưng cất.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Một cốc chứa hỗn hợp 200 mL nước và 20 g cát. Sau khi lọc và sấy khô, khối lượng cát thu được trên giấy lọc là:', opts: o4('0 g', '200 g', '10 g', '20 g'), ans: 'D', why: 'Cát không tan và không bay hơi nên được giữ lại toàn bộ: <b>20 g</b>. Lọc chỉ tách chất chứ không làm mất chất.' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Vì sao khi làm muối, người ta dẫn nước biển vào ruộng rồi phơi nắng thay vì đun sôi?', opts: o4('vì đun sôi sẽ làm muối biến thành chất khác', 'vì muối chỉ kết tinh được dưới ánh nắng mặt trời', 'vì phơi nắng tận dụng năng lượng Mặt Trời, không tốn nhiên liệu', 'vì nước biển không thể sôi được ở nhiệt độ thường'), ans: 'C', why: 'Cả hai cách đều làm nước bay hơi, nhưng đun sôi hàng nghìn mét khối nước biển thì tốn nhiên liệu khổng lồ. Phơi nắng dùng năng lượng miễn phí nên rẻ hơn nhiều.' },
    { sec: 'Phương pháp chiết', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Phương pháp chiết dùng để tách:', opts: o4('hai chất rắn có kích thước hạt khác nhau', 'hai chất lỏng không tan vào nhau', 'chất rắn tan ra khỏi dung dịch', 'hai chất khí khác nhau'), ans: 'B', why: 'Chiết dựa trên việc hai chất lỏng không hòa tan vào nhau sẽ tách thành hai lớp riêng biệt, ví dụ dầu ăn và nước.' },
    { sec: 'Phương pháp lọc', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Trong quá trình lọc, phần chất lỏng đi qua giấy lọc được gọi là:', opts: o4('nước lọc', 'chất rắn', 'cặn', 'dung môi tinh khiết'), ans: 'A', why: 'Phần chảy qua giấy lọc gọi là nước lọc (dịch lọc); phần giữ lại trên giấy gọi là cặn.' },
    { sec: 'Tách hỗn hợp nhiều chất', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Muốn tách riêng đường ra khỏi hỗn hợp đường và cát, cách làm ĐÚNG là:', opts: o4('lọc trực tiếp hỗn hợp khô rồi cô cạn phần cặn', 'dùng nam châm để hút riêng đường ra', 'đun nóng hỗn hợp cho cát bay hơi hết', 'hòa tan vào nước, lọc bỏ cát rồi cô cạn nước đường'), ans: 'D', why: 'Đường tan còn cát không tan, nên hòa vào nước rồi lọc sẽ giữ lại cát; cô cạn nước lọc thu lại đường. Đường và cát đều không có từ tính, còn cát thì không bay hơi.' },
    { sec: 'Phương pháp lọc', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Khi lọc nước đục lấy từ ao, chất còn lại trên giấy lọc là:', opts: o4('nước sạch', 'bùn đất và tạp chất không tan', 'muối khoáng hòa tan', 'khí oxygen'), ans: 'B', why: 'Giấy lọc chỉ giữ được các hạt rắn không tan như bùn đất. Muối khoáng đã hòa tan vẫn đi qua giấy lọc.' },
    { sec: 'Phương pháp chưng cất', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Phương pháp nào dùng để tách hai chất lỏng có nhiệt độ sôi khác nhau?', opts: o4('lọc', 'dùng nam châm', 'chưng cất', 'cô cạn hoàn toàn'), ans: 'C', why: 'Chưng cất lợi dụng việc chất có nhiệt độ sôi thấp hơn sẽ bay hơi trước, sau đó ngưng tụ và thu riêng được.' },
    { sec: 'Phương pháp chưng cất', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Trong thí nghiệm chưng cất nước muối, chất thu được ở bình hứng là:', opts: o4('nước cất', 'muối khan', 'nước muối đậm đặc', 'hỗn hợp nước và muối'), ans: 'A', why: 'Chỉ nước bay hơi rồi ngưng tụ chảy sang bình hứng nên thu được nước cất. Muối không bay hơi nên ở lại trong bình đun.' },
    { sec: 'Phương pháp lắng gạn', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Để tách bột sắn dây ra khỏi nước bột sắn dây, cách đơn giản nhất là:', opts: o4('đun sôi cho nước bay hơi hết', 'để lắng rồi gạn lấy phần nước ở trên', 'dùng nam châm hút bột lên', 'cho thêm muối vào để bột tan hết'), ans: 'B', why: 'Bột sắn dây không tan, nặng hơn nước nên để yên sẽ lắng xuống đáy; khi đó chỉ cần nghiêng cốc gạn phần nước trong ở trên.' },
    { sec: 'Dùng từ tính', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Hỗn hợp nào sau đây có thể tách bằng cách dùng nam châm?', opts: o4('muối và nước', 'đường và nước', 'dầu ăn và nước', 'bột sắt và bột lưu huỳnh'), ans: 'D', why: 'Chỉ sắt bị nam châm hút, lưu huỳnh thì không, nên nam châm tách được hai bột này. Ba hỗn hợp còn lại đều không có chất nào nhiễm từ.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Bạn Mai có 250 mL nước muối chứa 10 g muối. Sau khi cô cạn hoàn toàn, Mai thu được bao nhiêu gam muối?', opts: o4('250 g', '0 g', '10 g', '260 g'), ans: 'C', why: 'Chỉ nước bay hơi, muối ở lại nguyên vẹn nên thu được đúng <b>10 g</b> muối.' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Vì sao khi pha trà, người ta rót nước trà qua lưới lọc?', opts: o4('để giữ lại bã trà, chỉ lấy phần nước trà', 'để làm cho nước trà nóng hơn', 'để tách muối khoáng ra khỏi nước trà', 'để nước trà bay hơi nhanh hơn'), ans: 'A', why: 'Đây chính là phương pháp lọc: bã trà là chất rắn không tan nên bị lưới giữ lại, phần nước trà chảy qua.' },
    { sec: 'Nguyên tắc tách chất', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Nguyên tắc chung của việc tách chất ra khỏi hỗn hợp là dựa vào:', opts: o4('màu sắc của từng chất', 'giá thành của từng chất', 'sự khác nhau về tính chất của các chất', 'khối lượng bằng nhau của các chất'), ans: 'C', why: 'Muốn tách được, các chất phải khác nhau ở ít nhất một tính chất: tính tan, nhiệt độ sôi, từ tính, kích thước hạt…' },
    { sec: 'Ứng dụng thực tế', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Muốn thu được nước sạch từ nước sông có nhiều phù sa, bước đầu tiên nên làm là:', opts: o4('cô cạn toàn bộ nước sông', 'lắng và lọc bỏ phù sa', 'cho thêm muối vào nước', 'dùng nam châm hút phù sa'), ans: 'B', why: 'Phù sa là chất rắn không tan nên phải loại bỏ trước bằng cách để lắng rồi lọc; các bước xử lí tiếp theo mới hiệu quả.' },
    { sec: 'Tách hỗn hợp nhiều chất', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Một bạn muốn tách riêng hỗn hợp gồm bột gỗ và muối ăn. Cách làm ĐÚNG là:', opts: o4('dùng nam châm hút muối ra khỏi bột gỗ', 'đun nóng hỗn hợp cho bột gỗ bay hơi hết', 'lọc trực tiếp hỗn hợp khô qua giấy lọc', 'hòa tan vào nước, lọc lấy bột gỗ rồi cô cạn nước lọc'), ans: 'D', why: 'Muối tan trong nước còn bột gỗ thì không, nên lọc sẽ giữ lại bột gỗ; cô cạn nước lọc thu lại muối. Muối không có từ tính và bột gỗ không bay hơi nên các cách kia đều sai.' },
    { sec: 'Phương pháp chưng cất', lvl: 'NB', name: 'Câu 25', pts: 1, text: 'Chưng cất là phương pháp tách chất dựa trên sự khác nhau về:', opts: o4('nhiệt độ sôi', 'màu sắc', 'khối lượng', 'từ tính'), ans: 'A', why: 'Chất nào có nhiệt độ sôi thấp hơn sẽ bay hơi trước và được ngưng tụ thu riêng.' },
    { sec: 'Phương pháp lọc', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Trong các hỗn hợp sau, hỗn hợp nào KHÔNG thể tách bằng phương pháp lọc?', opts: o4('nước và cát', 'nước và bột mì', 'nước và đường', 'nước và bã chè'), ans: 'C', why: 'Đường tan hoàn toàn trong nước nên đi qua giấy lọc; muốn tách phải cô cạn. Ba hỗn hợp còn lại đều có chất rắn không tan.' },
    { sec: 'Dụng cụ', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Dụng cụ dùng để chiết hai chất lỏng không trộn lẫn vào nhau là:', opts: o4('ống nghiệm', 'cốc đong', 'đèn cồn', 'phễu chiết'), ans: 'D', why: 'Phễu chiết có khóa ở dưới để mở cho lớp chất lỏng nặng hơn chảy ra trước, giữ lại lớp nhẹ hơn ở trên.' },
    { sec: 'Phương pháp chưng cất', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Chưng cất hỗn hợp nước và cồn (cồn sôi ở 78 °C, nước sôi ở 100 °C). Chất bay hơi và được thu trước là:', opts: o4('nước', 'cồn', 'cả hai cùng lúc', 'không chất nào bay hơi'), ans: 'B', why: 'Cồn có nhiệt độ sôi thấp hơn (78 °C < 100 °C) nên sôi và bay hơi trước, được ngưng tụ thu lại trước nước.' },
    { sec: 'Phương pháp lọc', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Vì sao sau khi lọc, nước vẫn có thể còn muối khoáng hòa tan?', opts: o4('vì lọc chỉ giữ lại được chất rắn KHÔNG tan', 'vì giấy lọc bị rách trong quá trình lọc', 'vì muối khoáng bám vào thành phễu lọc', 'vì nước đã hòa tan thêm muối từ giấy lọc'), ans: 'A', why: 'Các hạt chất tan phân tán rất nhỏ giữa các hạt nước nên lọt qua lỗ giấy lọc. Muốn loại bỏ chúng phải dùng chưng cất chứ không dùng lọc.' },
    { sec: 'Bảo toàn khối lượng', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Trộn 30 g muối với 70 g cát rồi hòa vào nước, lọc bỏ cát và cô cạn nước lọc. Khối lượng muối và cát thu được lần lượt là:', opts: o4('70 g và 30 g', '100 g và 0 g', '30 g và 70 g', '15 g và 35 g'), ans: 'C', why: 'Tách chất không làm mất chất, nên thu lại đúng <b>30 g muối và 70 g cát</b>. (Phương án A đảo ngược hai số liệu.)' },
  ],
},

/* ═══════════ ĐỀ 9 — TẾ BÀO: ĐƠN VỊ CƠ SỞ CỦA SỰ SỐNG ═══════════ */
{
  id: 10659, title: 'Đề 9 · Tế bào — đơn vị cơ sở của sự sống', time: 60,
  questions: [
    { sec: 'Khái niệm tế bào', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Đơn vị cấu tạo cơ bản của mọi cơ thể sống là:', opts: o4('tế bào', 'mô', 'cơ quan', 'hệ cơ quan'), ans: 'A', why: 'Mọi cơ thể sống đều được cấu tạo từ tế bào; mô, cơ quan, hệ cơ quan đều là các cấp tổ chức CAO hơn tế bào.' },
    { sec: 'Vai trò của tế bào', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Vì sao nói tế bào là đơn vị cơ bản của sự sống?', opts: o4('vì tế bào có kích thước rất nhỏ, phải dùng kính hiển vi', 'vì mọi tế bào đều có hình dạng giống hệt nhau', 'vì mọi cơ thể sống đều cấu tạo từ tế bào và tế bào thực hiện các hoạt động sống', 'vì tế bào chỉ có ở thực vật và động vật'), ans: 'C', why: 'Có hai lí do gộp lại: tế bào là viên gạch cấu tạo nên mọi cơ thể, và mọi hoạt động sống (trao đổi chất, lớn lên, sinh sản) đều diễn ra ở cấp tế bào. Kích thước nhỏ chỉ là đặc điểm, không phải lí do.' },
    { sec: 'Tế bào thực vật', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Thành phần nào sau đây CÓ ở tế bào thực vật nhưng KHÔNG có ở tế bào động vật?', opts: o4('màng tế bào', 'lục lạp', 'nhân tế bào', 'chất tế bào'), ans: 'B', why: 'Lục lạp (và thành tế bào) chỉ có ở tế bào thực vật. Màng tế bào, nhân và chất tế bào đều có ở cả hai loại.' },
    { sec: 'Cấu tạo tế bào', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Bộ phận điều khiển mọi hoạt động sống của tế bào là:', opts: o4('màng tế bào', 'chất tế bào', 'lục lạp', 'nhân tế bào'), ans: 'D', why: 'Nhân chứa vật chất di truyền và là trung tâm điều khiển mọi hoạt động của tế bào.' },
    { sec: 'Thành tế bào', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Vì sao tế bào thực vật thường có hình dạng cố định còn tế bào động vật thì không?', opts: o4('vì tế bào thực vật có thành tế bào cứng bao bên ngoài', 'vì tế bào thực vật có kích thước lớn hơn rất nhiều', 'vì tế bào thực vật không có màng tế bào bao bọc', 'vì tế bào động vật không có nhân tế bào'), ans: 'A', why: 'Thành tế bào bằng cellulose vừa cứng vừa bền, giữ cho tế bào thực vật có hình dạng ổn định. Tế bào động vật chỉ có màng mềm nên hình dạng dễ thay đổi.' },
    { sec: 'Màng tế bào', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Chức năng của màng tế bào là:', opts: o4('quang hợp tạo ra chất dinh dưỡng', 'điều khiển mọi hoạt động của tế bào', 'chứa các chất dự trữ cho tế bào', 'bao bọc và kiểm soát các chất ra vào tế bào'), ans: 'D', why: 'Màng tế bào vừa bao bọc vừa đóng vai trò "cổng kiểm soát", quyết định chất nào được đi vào hay đi ra. Điều khiển hoạt động là việc của nhân, quang hợp là việc của lục lạp.' },
    { sec: 'Nhân sơ – nhân thực', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Tế bào nhân thực khác tế bào nhân sơ ở chỗ:', opts: o4('không có màng tế bào', 'có nhân được bao bọc bởi màng nhân', 'không có chất tế bào', 'luôn luôn có lục lạp'), ans: 'B', why: 'Đúng như tên gọi: tế bào nhân thực có nhân hoàn chỉnh được màng nhân bao bọc, còn tế bào nhân sơ thì vật chất di truyền nằm trần trong chất tế bào.' },
    { sec: 'Nhân sơ – nhân thực', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Cho các sinh vật: vi khuẩn lactic, cây bàng, con mèo, trùng roi. Sinh vật có cấu tạo tế bào nhân sơ là:', opts: o4('cây bàng', 'con mèo', 'vi khuẩn lactic', 'trùng roi'), ans: 'C', why: 'Chỉ vi khuẩn mới là tế bào nhân sơ. Trùng roi tuy chỉ có một tế bào nhưng đã có nhân hoàn chỉnh nên vẫn là tế bào nhân thực — đây là chỗ hay nhầm.' },
    { sec: 'Phân chia tế bào', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Một tế bào sau 3 lần phân chia liên tiếp sẽ tạo ra bao nhiêu tế bào con?', opts: o4('8 tế bào', '6 tế bào', '3 tế bào', '4 tế bào'), ans: 'A', why: 'Mỗi lần phân chia, số tế bào tăng gấp đôi: 1 → 2 → 4 → <b>8</b>, tức 2³ = 8. (Chọn 6 là nhân 3 với 2; chọn 4 là mới đếm 2 lần phân chia.)' },
    { sec: 'Quan sát tế bào', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Để quan sát được tế bào biểu bì vảy hành, ta cần dùng:', opts: o4('mắt thường', 'kính lúp cầm tay', 'ống nhòm', 'kính hiển vi quang học'), ans: 'D', why: 'Tế bào biểu bì vảy hành chỉ vài chục micromet nên kính lúp (phóng đại vài lần) không đủ; phải dùng kính hiển vi quang học.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Sinh vật đơn bào là sinh vật:', opts: o4('được cấu tạo từ rất nhiều tế bào', 'hoàn toàn không có tế bào nào', 'chỉ được cấu tạo từ một tế bào', 'chỉ gặp ở các động vật bậc cao'), ans: 'C', why: 'Đơn = một. Cơ thể đơn bào chỉ gồm một tế bào nhưng tế bào ấy làm đủ mọi việc để sống.' },
    { sec: 'Lớn lên và phân chia', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Vì sao cơ thể chúng ta lớn lên được?', opts: o4('vì các tế bào ngày càng to ra mãi không có giới hạn', 'vì các tế bào lớn lên và phân chia làm tăng số lượng tế bào', 'vì số lượng tế bào giảm đi nhưng kích thước lại tăng', 'vì các tế bào cũ chết đi mà không được thay thế'), ans: 'B', why: 'Tế bào chỉ lớn đến một mức nhất định rồi phân chia. Cơ thể lớn lên chủ yếu nhờ SỐ LƯỢNG tế bào tăng, chứ không phải mỗi tế bào phình to mãi.' },
    { sec: 'Ý nghĩa phân chia', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Sự lớn lên và phân chia của tế bào có ý nghĩa gì với cơ thể?', opts: o4('giúp cơ thể lớn lên và thay thế tế bào già, tế bào bị tổn thương', 'giúp cơ thể giảm bớt số tế bào không còn cần thiết', 'giúp tế bào thay đổi hoàn toàn hình dạng ban đầu', 'giúp cơ thể ngừng phát triển khi đã trưởng thành'), ans: 'A', why: 'Hai ý nghĩa: làm cơ thể lớn lên và thay thế những tế bào đã già hoặc bị thương (nhờ vậy vết thương mới lành được).' },
    { sec: 'So sánh tế bào', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Cho các thành phần: (1) màng tế bào; (2) thành tế bào; (3) chất tế bào; (4) nhân; (5) lục lạp. Những thành phần có ở CẢ tế bào động vật và tế bào thực vật là:', opts: o4('(1), (2) và (3)', '(2), (4) và (5)', '(1), (2) và (5)', '(1), (3) và (4)'), ans: 'D', why: 'Màng tế bào, chất tế bào và nhân là ba thành phần chung. Thành tế bào (2) và lục lạp (5) chỉ có ở tế bào thực vật nên phải loại.' },
    { sec: 'Chất tế bào', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Nơi diễn ra các hoạt động sống của tế bào là:', opts: o4('thành tế bào', 'chất tế bào', 'màng nhân', 'không bào co bóp'), ans: 'B', why: 'Chất tế bào là khối chất keo bên trong màng, nơi diễn ra phần lớn các hoạt động sống của tế bào.' },
    { sec: 'Cơ thể đa bào', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Sinh vật nào sau đây là sinh vật đa bào?', opts: o4('vi khuẩn E. coli', 'trùng giày', 'cây hoa hồng', 'tảo lục đơn bào'), ans: 'C', why: 'Cây hoa hồng gồm rất nhiều tế bào phân hóa thành rễ, thân, lá, hoa. Ba sinh vật còn lại đều chỉ có một tế bào.' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Vì sao khi bị đứt tay, sau vài ngày vết thương lại liền lại?', opts: o4('vì các tế bào ở vùng bị thương phân chia tạo tế bào mới lấp đầy vết thương', 'vì các tế bào cũ tự phình to ra để bịt kín miệng vết thương', 'vì máu đông lại rồi biến thành các tế bào da mới', 'vì cơ thể lấy tế bào từ nơi khác chuyển đến vết thương'), ans: 'A', why: 'Đó chính là ý nghĩa của sự phân chia tế bào: tạo ra tế bào mới thay thế phần bị tổn thương. Máu đông chỉ tạm bịt vết thương chứ không biến thành tế bào da.' },
    { sec: 'Thành tế bào', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Thành tế bào của thực vật được cấu tạo chủ yếu từ:', opts: o4('chất béo', 'muối khoáng', 'nước', 'cellulose'), ans: 'D', why: 'Cellulose là chất tạo nên thành tế bào thực vật, giúp thành vừa cứng vừa bền.' },
    { sec: 'Kính hiển vi', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'Quan sát tế bào bằng kính hiển vi có vật kính 40× và thị kính 10×. Độ phóng đại của ảnh thu được là:', opts: o4('50 lần', '40 lần', '400 lần', '4 lần'), ans: 'C', why: 'Độ phóng đại của kính hiển vi = độ phóng đại vật kính × thị kính = 40 × 10 = <b>400 lần</b>. (Chọn 50 là cộng hai số thay vì nhân.)' },
    { sec: 'Kích thước tế bào', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Trong các tế bào sau, tế bào nào có thể nhìn thấy bằng mắt thường?', opts: o4('tế bào vi khuẩn', 'tế bào trứng gà', 'tế bào biểu bì da người', 'tế bào hồng cầu'), ans: 'B', why: 'Lòng đỏ trứng gà chính là một tế bào rất lớn, nhìn rõ bằng mắt thường. Ba loại tế bào còn lại đều phải quan sát bằng kính hiển vi.' },
    { sec: 'Nhân sơ – nhân thực', lvl: 'NB', name: 'Câu 21', pts: 1, text: 'Tế bào nhân sơ là tế bào:', opts: o4('chưa có màng nhân bao bọc vật chất di truyền', 'hoàn toàn không có chất tế bào', 'luôn luôn có kích thước rất lớn', 'chỉ có ở các cơ thể đa bào'), ans: 'A', why: 'Tế bào nhân sơ vẫn có màng, chất tế bào và vật chất di truyền, chỉ thiếu màng nhân nên vùng nhân không tách riêng khỏi chất tế bào.' },
    { sec: 'Lục lạp', lvl: 'NC', name: 'Câu 22', pts: 1, text: 'Một bạn nói: "Mọi tế bào đều có lục lạp nên đều quang hợp được." Nhận xét nào ĐÚNG?', opts: o4('đúng, vì lục lạp là thành phần bắt buộc của mọi tế bào', 'đúng, vì tế bào động vật cũng tự tạo được chất dinh dưỡng', 'sai, vì chỉ tế bào động vật mới có lục lạp', 'sai, vì chỉ một số tế bào thực vật mới có lục lạp'), ans: 'D', why: 'Tế bào động vật không có lục lạp; ngay ở thực vật cũng chỉ những tế bào ở phần xanh (chủ yếu là lá) mới có lục lạp, còn tế bào rễ thì không.' },
    { sec: 'Kích thước tế bào', lvl: 'NC', name: 'Câu 23', pts: 1, text: 'Kích thước rất nhỏ của tế bào mang lại lợi ích gì?', opts: o4('giúp cơ thể nhẹ hơn nên di chuyển nhanh hơn', 'giúp trao đổi chất nhanh, tế bào lớn lên và phân chia thuận lợi', 'giúp tế bào không cần lấy chất dinh dưỡng từ bên ngoài', 'giúp cơ thể có ít tế bào hơn nên tiết kiệm năng lượng'), ans: 'B', why: 'Tế bào nhỏ thì quãng đường vận chuyển chất ngắn, trao đổi chất với môi trường nhanh và dễ phân chia. Đó là lí do cơ thể lớn lên bằng cách tăng SỐ tế bào chứ không tăng kích thước từng tế bào.' },
    { sec: 'Phân chia tế bào', lvl: 'TH', name: 'Câu 24', pts: 1, text: 'Quá trình tế bào lớn lên đến một kích thước nhất định rồi tách thành hai tế bào con gọi là:', opts: o4('sự lớn lên của tế bào', 'sự trao đổi chất', 'sự phân chia tế bào', 'sự cảm ứng'), ans: 'C', why: 'Đó là sự phân chia (sinh sản) của tế bào — từ một tế bào mẹ tạo ra hai tế bào con giống nó.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NB', name: 'Câu 25', pts: 1, text: 'Trùng giày và trùng roi là ví dụ về:', opts: o4('sinh vật đơn bào', 'sinh vật đa bào', 'vi khuẩn', 'tế bào nhân sơ'), ans: 'A', why: 'Chúng chỉ gồm một tế bào nên là sinh vật đơn bào, nhưng tế bào đó có nhân hoàn chỉnh nên KHÔNG phải vi khuẩn hay tế bào nhân sơ.' },
    { sec: 'Cấp độ tổ chức', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Thứ tự đúng từ nhỏ đến lớn trong tổ chức của cơ thể đa bào là:', opts: o4('mô → tế bào → cơ quan → hệ cơ quan', 'tế bào → cơ quan → mô → hệ cơ quan', 'cơ quan → mô → tế bào → hệ cơ quan', 'tế bào → mô → cơ quan → hệ cơ quan'), ans: 'D', why: 'Tế bào hợp thành mô, các mô hợp thành cơ quan, các cơ quan hợp thành hệ cơ quan.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NC', name: 'Câu 27', pts: 1, text: 'Quan sát một giọt nước ao dưới kính hiển vi, bạn Nam thấy một sinh vật chỉ gồm một tế bào nhưng vẫn di chuyển, lấy thức ăn và sinh sản. Nhận xét nào ĐÚNG?', opts: o4('đó là một mô tách ra từ cơ thể đa bào', 'đó không phải sinh vật vì chỉ có một tế bào', 'đó là sinh vật đơn bào, một tế bào làm mọi hoạt động sống', 'đó là một tế bào đã chết đang trôi nổi trong nước'), ans: 'C', why: 'Dấu hiệu di chuyển, lấy thức ăn và sinh sản cho thấy đây là một cơ thể sống hoàn chỉnh. Vì chỉ có một tế bào nên nó là sinh vật đơn bào.' },
    { sec: 'Thành tế bào', lvl: 'NB', name: 'Câu 28', pts: 1, text: 'Bộ phận giúp tế bào thực vật giữ được hình dạng ổn định là:', opts: o4('màng tế bào', 'thành tế bào', 'nhân tế bào', 'chất tế bào'), ans: 'B', why: 'Thành tế bào cứng bao ngoài màng, tạo bộ khung giữ hình dạng cho tế bào thực vật.' },
    { sec: 'Kích thước tế bào', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Kích thước của phần lớn tế bào được đo bằng đơn vị:', opts: o4('micrômét (µm)', 'kilômét (km)', 'mét (m)', 'đềximét (dm)'), ans: 'A', why: 'Phần lớn tế bào chỉ vài chục micrômét (1 µm = 0,001 mm) nên mới phải quan sát bằng kính hiển vi.' },
    { sec: 'Phân chia tế bào', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Một tế bào vi khuẩn cứ 20 phút lại phân chia một lần. Sau 1 giờ, từ một tế bào ban đầu tạo ra bao nhiêu tế bào?', opts: o4('3 tế bào', '6 tế bào', '8 tế bào', '20 tế bào'), ans: 'C', why: '1 giờ = 60 phút nên có 60 : 20 = 3 lần phân chia. Số tế bào: 1 → 2 → 4 → <b>8</b>. (Chọn 3 là nhầm số LẦN phân chia với số tế bào; chọn 6 là lấy 3 × 2.)' },
  ],
},

/* ═══════════ ĐỀ 10 — TỪ TẾ BÀO ĐẾN CƠ THỂ ═══════════ */
{
  id: 10660, title: 'Đề 10 · Từ tế bào đến cơ thể', time: 60,
  questions: [
    { sec: 'Khái niệm mô', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Nhóm các tế bào giống nhau cùng thực hiện một chức năng được gọi là:', opts: o4('cơ quan', 'mô', 'hệ cơ quan', 'cơ thể'), ans: 'B', why: 'Mô là tập hợp các tế bào GIỐNG NHAU cùng làm một nhiệm vụ. Cơ quan thì gồm nhiều loại mô khác nhau.' },
    { sec: 'Cơ thể đa bào', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Cơ thể đa bào là cơ thể được cấu tạo từ:', opts: o4('một tế bào duy nhất', 'chỉ toàn các tế bào nhân sơ', 'các chất vô cơ không có tế bào', 'nhiều tế bào'), ans: 'D', why: 'Đa = nhiều. Cơ thể đa bào gồm nhiều tế bào, thường phân hóa thành nhiều loại mô và cơ quan khác nhau.' },
    { sec: 'Cấp độ tổ chức', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Cho các cấp độ tổ chức: mô, cơ quan, tế bào, hệ cơ quan, cơ thể. Sắp xếp từ thấp đến cao ta được:', opts: o4('tế bào → mô → cơ quan → hệ cơ quan → cơ thể', 'tế bào → cơ quan → mô → hệ cơ quan → cơ thể', 'mô → tế bào → cơ quan → cơ thể → hệ cơ quan', 'cơ thể → hệ cơ quan → cơ quan → mô → tế bào'), ans: 'A', why: 'Tế bào hợp thành mô; các mô khác nhau hợp thành cơ quan; các cơ quan cùng nhiệm vụ hợp thành hệ cơ quan; các hệ cơ quan tạo nên cơ thể. Phương án D đúng thứ tự nhưng ngược chiều (từ cao xuống thấp).' },
    { sec: 'Cơ quan ở thực vật', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'Lá cây là một ví dụ về:', opts: o4('mô', 'tế bào', 'cơ quan', 'hệ cơ quan'), ans: 'C', why: 'Lá gồm nhiều loại mô (mô biểu bì, mô dẫn, mô giậu) cùng thực hiện chức năng quang hợp nên là một cơ quan.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Sinh vật nào sau đây là sinh vật đơn bào?', opts: o4('cây phượng', 'trùng biến hình', 'con ếch', 'con giun đất'), ans: 'B', why: 'Trùng biến hình chỉ gồm một tế bào. Ba sinh vật còn lại đều có rất nhiều tế bào và nhiều cơ quan.' },
    { sec: 'So sánh đơn bào – đa bào', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Vì sao cơ thể đa bào thực hiện được nhiều hoạt động sống phức tạp hơn cơ thể đơn bào?', opts: o4('vì các tế bào phân hóa thành nhiều loại mô, cơ quan chuyên biệt', 'vì mỗi tế bào của cơ thể đa bào đều lớn hơn rất nhiều', 'vì cơ thể đa bào không cần trao đổi chất với môi trường', 'vì cơ thể đa bào chỉ gồm một loại tế bào duy nhất'), ans: 'A', why: 'Ở cơ thể đa bào, mỗi nhóm tế bào chuyên làm một việc (tế bào cơ co rút, tế bào thần kinh dẫn truyền…), nhờ sự phân công đó mà cơ thể làm được nhiều việc phức tạp.' },
    { sec: 'Hệ cơ quan', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'Hệ cơ quan là:', opts: o4('tập hợp các tế bào giống hệt nhau', 'một cơ quan duy nhất trong cơ thể', 'tập hợp mọi chất có trong cơ thể sống', 'tập hợp các cơ quan cùng thực hiện một quá trình sống'), ans: 'D', why: 'Ví dụ hệ tiêu hóa gồm miệng, dạ dày, ruột, gan… cùng tham gia tiêu hóa thức ăn.' },
    { sec: 'Hệ cơ quan', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Dạ dày, ruột non và gan cùng tham gia tiêu hóa thức ăn. Chúng hợp thành:', opts: o4('một mô', 'một tế bào lớn', 'hệ tiêu hóa', 'hệ tuần hoàn'), ans: 'C', why: 'Nhiều CƠ QUAN cùng thực hiện một quá trình sống thì hợp thành một hệ cơ quan — ở đây là hệ tiêu hóa.' },
    { sec: 'Cơ quan ở thực vật', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Ở thực vật có hoa, các cơ quan sinh dưỡng gồm:', opts: o4('rễ, thân, lá', 'hoa, quả, hạt', 'rễ, hoa, hạt', 'thân, hoa, quả'), ans: 'A', why: 'Rễ, thân, lá nuôi sống cây nên là cơ quan sinh dưỡng; hoa, quả, hạt làm nhiệm vụ sinh sản.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Quan sát một con giun đất, bạn Lan thấy nó có ruột, có mạch máu và có hệ thần kinh. Nhận xét nào ĐÚNG?', opts: o4('giun đất là sinh vật đơn bào', 'giun đất là cơ thể đa bào, có nhiều hệ cơ quan', 'giun đất chỉ có một loại mô duy nhất', 'giun đất không có cấu tạo tế bào'), ans: 'B', why: 'Có ruột, mạch máu, thần kinh nghĩa là đã có nhiều hệ cơ quan khác nhau — chỉ cơ thể đa bào mới đạt tới mức tổ chức này.' },
    { sec: 'Hệ cơ quan ở người', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'Ở người, tim thuộc hệ cơ quan nào?', opts: o4('hệ tiêu hóa', 'hệ hô hấp', 'hệ tuần hoàn', 'hệ bài tiết'), ans: 'C', why: 'Tim cùng với mạch máu tạo thành hệ tuần hoàn, làm nhiệm vụ vận chuyển máu đi khắp cơ thể.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Vì sao trùng roi chỉ gồm một tế bào nhưng vẫn được gọi là một cơ thể sống?', opts: o4('vì nó có kích thước lớn như một cơ thể đa bào', 'vì nó được cấu tạo từ nhiều loại mô khác nhau', 'vì nó sống bám trên cơ thể của sinh vật khác', 'vì một tế bào đó thực hiện đầy đủ các hoạt động sống'), ans: 'D', why: 'Tiêu chí của một cơ thể sống là thực hiện đủ các hoạt động sống: trao đổi chất, lớn lên, sinh sản, cảm ứng. Trùng roi làm đủ những việc đó chỉ với một tế bào.' },
    { sec: 'Mô ở động vật', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Mô cơ ở người được tạo nên từ:', opts: o4('các tế bào cơ', 'các tế bào thần kinh', 'các tế bào biểu bì lá', 'các muối khoáng'), ans: 'A', why: 'Mô là tập hợp các tế bào cùng loại, nên mô cơ gồm các tế bào cơ.' },
    { sec: 'Cơ quan ở thực vật', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Cơ quan sinh sản của cây có hoa gồm:', opts: o4('rễ, thân, lá', 'hoa, quả, hạt', 'thân và rễ', 'lá và hoa'), ans: 'B', why: 'Hoa tạo quả, quả chứa hạt, hạt mọc thành cây mới — cả ba đều phục vụ việc duy trì nòi giống.' },
    { sec: 'Cấp độ tổ chức', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Sắp xếp các đối tượng sau theo cấp độ tổ chức từ thấp đến cao: mô dẫn, lá, cây cà chua, tế bào lá.', opts: o4('lá → tế bào lá → mô dẫn → cây cà chua', 'mô dẫn → tế bào lá → lá → cây cà chua', 'tế bào lá → mô dẫn → lá → cây cà chua', 'cây cà chua → lá → mô dẫn → tế bào lá'), ans: 'C', why: 'Tế bào (tế bào lá) → mô (mô dẫn) → cơ quan (lá) → cơ thể (cây cà chua). Phương án D đúng thứ tự nhưng xếp ngược từ cao xuống thấp.' },
    { sec: 'Hệ cơ quan ở người', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Phổi là cơ quan của hệ:', opts: o4('tiêu hóa', 'tuần hoàn', 'bài tiết', 'hô hấp'), ans: 'D', why: 'Phổi làm nhiệm vụ trao đổi khí nên thuộc hệ hô hấp.' },
    { sec: 'So sánh đơn bào – đa bào', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Điểm GIỐNG nhau giữa cơ thể đơn bào và cơ thể đa bào là:', opts: o4('đều có nhiều hệ cơ quan khác nhau', 'đều cấu tạo từ tế bào và thực hiện các hoạt động sống', 'đều chỉ gồm đúng một tế bào duy nhất', 'đều có kích thước nhìn được bằng mắt thường'), ans: 'B', why: 'Dù khác nhau về số lượng tế bào, cả hai đều lấy tế bào làm đơn vị cấu tạo và đều phải trao đổi chất, lớn lên, sinh sản, cảm ứng.' },
    { sec: 'Mô ở thực vật', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Ở thực vật, mô dẫn có chức năng:', opts: o4('vận chuyển nước và chất dinh dưỡng trong cây', 'bảo vệ bề mặt lá khỏi bị mất nước', 'trực tiếp quang hợp tạo ra chất hữu cơ', 'giúp cây hút khí oxygen từ trong đất'), ans: 'A', why: 'Mô dẫn gồm các ống dẫn chạy suốt từ rễ lên lá, làm nhiệm vụ vận chuyển nước, muối khoáng và chất hữu cơ. Bảo vệ bề mặt là việc của mô biểu bì.' },
    { sec: 'Cơ thể đa bào', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Sinh vật nào sau đây KHÔNG phải là sinh vật đa bào?', opts: o4('cây xoài', 'con cá chép', 'vi khuẩn lactic', 'con chim bồ câu'), ans: 'C', why: 'Vi khuẩn lactic chỉ gồm một tế bào nên là sinh vật đơn bào.' },
    { sec: 'Cấp độ tổ chức', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Sắp xếp các đối tượng sau theo cấp độ tổ chức tăng dần: tế bào thần kinh, não, mô thần kinh, hệ thần kinh.', opts: o4('não → mô thần kinh → tế bào thần kinh → hệ thần kinh', 'mô thần kinh → tế bào thần kinh → não → hệ thần kinh', 'tế bào thần kinh → não → mô thần kinh → hệ thần kinh', 'tế bào thần kinh → mô thần kinh → não → hệ thần kinh'), ans: 'D', why: 'Tế bào thần kinh (tế bào) → mô thần kinh (mô) → não (cơ quan) → hệ thần kinh (hệ cơ quan). Não là một cơ quan chứ không phải cả hệ.' },
    { sec: 'Cơ thể thống nhất', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Vì sao khi một cơ quan trong cơ thể bị tổn thương thì các cơ quan khác cũng có thể bị ảnh hưởng?', opts: o4('vì các cơ quan phối hợp chặt chẽ trong một cơ thể thống nhất', 'vì mọi cơ quan đều nằm trong cùng một hệ cơ quan duy nhất', 'vì các cơ quan đều được cấu tạo từ cùng một loại tế bào', 'vì cơ thể chỉ có một cơ quan hoạt động ở mỗi thời điểm'), ans: 'A', why: 'Cơ thể là một khối thống nhất: các cơ quan phụ thuộc lẫn nhau. Ví dụ phổi tổn thương thì máu thiếu oxygen, kéo theo tim và mọi cơ quan khác đều bị ảnh hưởng.' },
    { sec: 'Hệ cơ quan ở người', lvl: 'TH', name: 'Câu 22', pts: 1, text: 'Ở người, hệ cơ quan nào có chức năng vận chuyển máu đi nuôi cơ thể?', opts: o4('hệ hô hấp', 'hệ tiêu hóa', 'hệ tuần hoàn', 'hệ thần kinh'), ans: 'C', why: 'Hệ tuần hoàn gồm tim và hệ mạch, đưa máu mang oxygen và chất dinh dưỡng tới mọi tế bào.' },
    { sec: 'Khái niệm cơ quan', lvl: 'NB', name: 'Câu 23', pts: 1, text: 'Cơ quan là:', opts: o4('một tế bào có kích thước rất lớn', 'tập hợp nhiều mô cùng thực hiện một chức năng', 'tập hợp các chất vô cơ trong cơ thể', 'tập hợp các cơ thể sống cùng một loài'), ans: 'B', why: 'Cơ quan gồm nhiều loại MÔ phối hợp; ví dụ dạ dày có mô cơ, mô biểu bì, mô liên kết cùng làm nhiệm vụ tiêu hóa.' },
    { sec: 'So sánh đơn bào – đa bào', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Tảo lục đơn bào và cây rêu đều quang hợp được. Điểm KHÁC nhau cơ bản giữa chúng là:', opts: o4('tảo lục không có lục lạp còn cây rêu thì có', 'cây rêu là sinh vật đơn bào còn tảo lục là đa bào', 'tảo lục không thực hiện bất kì hoạt động sống nào', 'tảo lục là cơ thể đơn bào còn cây rêu là cơ thể đa bào'), ans: 'D', why: 'Cả hai đều có lục lạp và đều quang hợp; khác nhau ở số lượng tế bào: tảo lục đơn bào chỉ một tế bào, còn cây rêu gồm rất nhiều tế bào. Phương án B nói ngược.' },
    { sec: 'Cơ quan ở thực vật', lvl: 'TH', name: 'Câu 25', pts: 1, text: 'Rễ cây được coi là một cơ quan vì:', opts: o4('nó gồm nhiều loại mô cùng làm nhiệm vụ hút nước và muối khoáng', 'nó chỉ gồm duy nhất một loại tế bào giống hệt nhau', 'nó chính là toàn bộ cơ thể của một cây xanh', 'nó hoàn toàn không được cấu tạo từ tế bào'), ans: 'A', why: 'Đúng định nghĩa cơ quan: nhiều loại mô (biểu bì, mô dẫn, mô mềm) phối hợp thực hiện chung một chức năng.' },
    { sec: 'Cơ thể đơn bào', lvl: 'NB', name: 'Câu 26', pts: 1, text: 'Trùng giày thuộc nhóm:', opts: o4('cơ thể đa bào', 'thực vật bậc cao', 'cơ thể đơn bào', 'nấm nhiều tế bào'), ans: 'C', why: 'Trùng giày chỉ gồm một tế bào nên là cơ thể đơn bào.' },
    { sec: 'Tổng hợp', lvl: 'NC', name: 'Câu 27', pts: 1, text: 'Cho các nhận định: (1) cơ thể đơn bào luôn nhỏ hơn cơ thể đa bào; (2) mọi cơ thể sống đều cấu tạo từ tế bào; (3) mô là tập hợp các tế bào giống nhau cùng chức năng; (4) hệ cơ quan chỉ có ở thực vật. Những nhận định ĐÚNG là:', opts: o4('(1) và (2)', '(1) và (4)', '(3) và (4)', '(2) và (3)'), ans: 'D', why: 'Nhận định (1) sai vì có tế bào đơn bào rất lớn; (4) sai vì hệ cơ quan chủ yếu gặp ở động vật và người. Chỉ (2) và (3) đúng.' },
    { sec: 'Hệ cơ quan ở người', lvl: 'TH', name: 'Câu 28', pts: 1, text: 'Ở người, hệ cơ quan nào biến đổi thức ăn thành chất dinh dưỡng cơ thể hấp thụ được?', opts: o4('hệ hô hấp', 'hệ tiêu hóa', 'hệ bài tiết', 'hệ vận động'), ans: 'B', why: 'Hệ tiêu hóa nghiền nhỏ và biến đổi thức ăn thành các chất đơn giản để cơ thể hấp thụ.' },
    { sec: 'Mô ở thực vật', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Ví dụ nào sau đây là một MÔ ở thực vật?', opts: o4('mô biểu bì lá', 'cây hoa hồng', 'rễ cây', 'quả cà chua'), ans: 'A', why: 'Mô biểu bì lá gồm các tế bào biểu bì giống nhau cùng bảo vệ bề mặt lá. Rễ và quả là cơ quan, cây hoa hồng là cả cơ thể.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Bạn Minh quan sát một giọt nước ao và thấy nhiều sinh vật nhỏ chỉ gồm một tế bào. Minh kết luận: "Nước ao có chứa các cơ thể đơn bào." Kết luận đó:', opts: o4('sai, vì một tế bào không thể là một cơ thể', 'sai, vì mọi sinh vật đều phải là cơ thể đa bào', 'đúng, nhưng chỉ khi các sinh vật đó không di chuyển', 'đúng, vì mỗi sinh vật đó là một cơ thể chỉ gồm một tế bào'), ans: 'D', why: 'Một tế bào hoàn toàn có thể là một cơ thể sống độc lập nếu nó thực hiện đủ các hoạt động sống — đó chính là định nghĩa cơ thể đơn bào.' },
  ],
},

/* ═══════════ ĐỀ 11 — PHÂN LOẠI THẾ GIỚI SỐNG. KHÓA LƯỠNG PHÂN ═══════════ */
{
  id: 10661, title: 'Đề 11 · Phân loại thế giới sống. Khóa lưỡng phân', time: 60,
  questions: [
    { sec: 'Khái niệm phân loại', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Phân loại thế giới sống là việc:', opts: o4('sắp xếp sinh vật theo thứ tự lớn bé của kích thước cơ thể', 'sắp xếp sinh vật theo thứ tự thời gian chúng được phát hiện', 'sắp xếp sinh vật vào các nhóm theo những đặc điểm giống nhau', 'sắp xếp sinh vật theo mức độ có ích hay có hại với con người'), ans: 'C', why: 'Phân loại là xếp sinh vật vào các nhóm dựa trên đặc điểm giống nhau về hình thái, cấu tạo. Kích thước hay mức độ có lợi — có hại chỉ là tiêu chí cảm tính, không dùng để phân loại khoa học.' },
    { sec: 'Ý nghĩa phân loại', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Việc phân loại thế giới sống có ý nghĩa gì?', opts: o4('giúp các loài sinh vật sinh sản nhanh hơn trong tự nhiên', 'giúp làm tăng số lượng loài sinh vật có trên Trái Đất', 'giúp mọi sinh vật đều sống chung được trong một môi trường', 'giúp xác định vị trí của loài, thuận lợi khi tìm hiểu và sử dụng'), ans: 'D', why: 'Phân loại chỉ là cách con người sắp xếp lại hiểu biết của mình, không làm thay đổi số lượng loài hay khả năng sinh sản của chúng. Nhờ phân loại ta biết một loài nằm ở đâu trong thế giới sống để tra cứu và sử dụng.' },
    { sec: 'Bậc phân loại', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Hai loài sinh vật được xếp cùng một chi. Kết luận nào sau đây chắc chắn đúng?', opts: o4('Hai loài đó thực ra chỉ là một loài vì chi là bậc thấp nhất', 'Hai loài đó cùng họ, cùng bộ vì chi nằm trong họ và trong bộ', 'Hai loài đó thuộc hai giới khác nhau vì mỗi chi thuộc một giới', 'Hai loài đó có hình dạng ngoài giống hệt nhau, khó phân biệt'), ans: 'B', why: 'Các bậc phân loại xếp từ lớn đến nhỏ: giới – ngành – lớp – bộ – họ – chi – loài. Bậc càng nhỏ thì các sinh vật trong đó càng giống nhau, và khi đã cùng một bậc nhỏ thì đương nhiên cùng tất cả các bậc lớn hơn. Bẫy ở phương án A: chi vẫn lớn hơn loài, một chi có thể gồm nhiều loài khác nhau (ví dụ chi Citrus có cả cam, bưởi, chanh).' },
    { sec: 'Bậc phân loại', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Thứ tự các bậc phân loại từ lớn đến nhỏ là:', opts: o4('giới – ngành – lớp – bộ – họ – chi – loài', 'loài – chi – họ – bộ – lớp – ngành – giới', 'giới – lớp – ngành – họ – bộ – loài – chi', 'ngành – giới – bộ – lớp – chi – họ – loài'), ans: 'A', why: 'Trình tự đúng là giới – ngành – lớp – bộ – họ – chi – loài. Phương án B chính là trình tự ngược lại (từ nhỏ đến lớn) nên rất dễ chọn nhầm nếu không đọc kĩ yêu cầu đề.' },
    { sec: 'Năm giới sinh vật', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Thế giới sống được chia thành mấy giới, gồm những giới nào?', opts: o4('3 giới: Thực vật, Động vật, Nấm', '4 giới: Khởi sinh, Nấm, Thực vật, Động vật', '5 giới: Khởi sinh, Nguyên sinh, Nấm, Thực vật, Động vật', '6 giới: Virus, Khởi sinh, Nguyên sinh, Nấm, Thực vật, Động vật'), ans: 'C', why: 'Hệ thống năm giới gồm: Khởi sinh, Nguyên sinh, Nấm, Thực vật, Động vật. Virus không được coi là một giới vì chưa có cấu tạo tế bào.' },
    { sec: 'Năm giới sinh vật', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Vì sao virus KHÔNG được xếp vào bất kì giới nào trong năm giới sinh vật?', opts: o4('vì virus chưa có cấu tạo tế bào nên chưa được coi là cơ thể sống', 'vì virus có kích thước quá nhỏ, kính hiển vi thường không nhìn được', 'vì virus chỉ mới được các nhà khoa học phát hiện ra trong thời gian gần đây', 'vì virus vừa sống được ở trong nước vừa sống được ở trên cạn và trong không khí'), ans: 'A', why: 'Tiêu chuẩn để xếp vào năm giới là sinh vật phải có cấu tạo tế bào. Virus chỉ gồm lớp vỏ protein và vật chất di truyền, phải sống nhờ trong tế bào khác nên chưa được coi là một cơ thể sống hoàn chỉnh. Bẫy ở phương án B: kích thước nhỏ không phải tiêu chí phân loại — vi khuẩn cũng rất nhỏ nhưng vẫn có một giới riêng.' },
    { sec: 'Khóa lưỡng phân', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Khi xây dựng khóa lưỡng phân, ở mỗi bước ta phải làm gì?', opts: o4('chia nhóm sinh vật thành ba nhóm nhỏ dựa vào ba đặc điểm', 'chọn ra đặc điểm mà tất cả sinh vật trong nhóm đều có', 'sắp xếp các sinh vật theo thứ tự kích thước từ nhỏ đến lớn', 'chọn một đặc điểm đối lập để tách nhóm thành hai nhóm nhỏ'), ans: 'D', why: 'Chữ "lưỡng phân" nghĩa là chia đôi: mỗi bước chỉ dùng một cặp đặc điểm đối lập (có — không có) để tách nhóm thành đúng hai nhóm. Bẫy ở phương án B: nếu chọn đặc điểm mà mọi sinh vật đều có thì không tách được nhóm nào cả, khóa sẽ vô nghĩa.' },
    { sec: 'Giới Khởi sinh', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Giới Khởi sinh gồm những sinh vật nào?', opts: o4('các loài nấm men và các loài nấm sợi', 'các loài vi khuẩn có tế bào nhân sơ', 'các loài tảo và trùng roi sống trong nước', 'các loài rêu và dương xỉ sống nơi ẩm ướt'), ans: 'B', why: 'Giới Khởi sinh gồm vi khuẩn — nhóm sinh vật đơn bào có tế bào nhân sơ. Nấm thuộc giới Nấm, trùng roi thuộc giới Nguyên sinh, rêu và dương xỉ thuộc giới Thực vật.' },
    { sec: 'Vận dụng phân loại', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Bạn An tìm thấy ở gốc cây mục một sinh vật: cơ thể đa bào, không có diệp lục, sống bằng cách lấy chất dinh dưỡng từ gỗ mục. Sinh vật đó nhiều khả năng thuộc giới nào?', opts: o4('giới Thực vật', 'giới Động vật', 'giới Nấm', 'giới Khởi sinh'), ans: 'C', why: 'Không có diệp lục ⇒ loại giới Thực vật. Sống bám tại chỗ, hút chất từ gỗ mục chứ không bắt mồi ⇒ không phải Động vật. Cơ thể đa bào ⇒ không phải giới Khởi sinh (vi khuẩn luôn đơn bào). Còn lại là giới Nấm, đúng với đặc điểm nấm hoại sinh trên gỗ mục.' },
    { sec: 'Tên khoa học', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Tên khoa học của loài người là <i>Homo sapiens</i>. Từ "Homo" cho biết:', opts: o4('tên loài', 'tên chi', 'tên họ', 'tên ngành'), ans: 'B', why: 'Tên khoa học của loài gồm hai phần: phần đầu là tên chi (viết hoa chữ cái đầu), phần sau là tên loài. Vậy "Homo" là tên chi, "sapiens" mới là tên loài.' },
    { sec: 'Bậc phân loại', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Đơn vị phân loại nhỏ nhất của thế giới sống là:', opts: o4('loài', 'chi', 'họ', 'giới'), ans: 'A', why: 'Loài là bậc phân loại nhỏ nhất, gồm các cá thể giống nhau nhiều nhất. Giới là bậc lớn nhất.' },
    { sec: 'Khóa lưỡng phân', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Lập khóa lưỡng phân để nhận biết bốn cây: rêu, dương xỉ, cây thông, cây bưởi. Cặp đặc điểm nào KHÔNG dùng được cho một bước của khóa?', opts: o4('có mạch dẫn / không có mạch dẫn', 'có hạt / không có hạt', 'có hoa và quả / không có hoa và quả', 'cây to và cao / cây nhỏ và thấp'), ans: 'D', why: 'Đặc điểm dùng trong khóa lưỡng phân phải rõ ràng, đối lập và ai quan sát cũng cho cùng kết quả. "To và cao" hay "nhỏ và thấp" là đánh giá cảm tính, không có ranh giới rõ nên hai người có thể xếp khác nhau. Bẫy ở phương án A: nhiều bạn tưởng mạch dẫn khó quan sát nên loại, nhưng đây lại là đặc điểm chuẩn để tách rêu ra khỏi ba cây còn lại.' },
    { sec: 'Giới Nguyên sinh', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Sinh vật nào sau đây thuộc giới Nguyên sinh?', opts: o4('cây rêu tường', 'nấm rơm', 'trùng giày', 'vi khuẩn lactic'), ans: 'C', why: 'Trùng giày là sinh vật đơn bào nhân thực sống trong nước, thuộc giới Nguyên sinh. Vi khuẩn lactic thuộc giới Khởi sinh vì có tế bào nhân sơ.' },
    { sec: 'Tên khoa học', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Tên khoa học của một loài được viết theo thứ tự nào?', opts: o4('tên chi viết trước, tên loài viết sau', 'tên loài viết trước, tên chi viết sau', 'tên họ viết trước, tên chi viết sau', 'tên giới viết trước, tên ngành viết sau'), ans: 'A', why: 'Tên khoa học gồm hai phần theo thứ tự: tên chi rồi đến tên loài, viết nghiêng, chữ cái đầu của tên chi viết hoa.' },
    { sec: 'Cơ sở phân loại', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Vì sao hai sinh vật rất giống nhau về hình dạng ngoài vẫn có thể được xếp vào hai loài khác nhau?', opts: o4('vì chúng sống ở hai môi trường khác nhau nên phải khác loài', 'vì phân loại còn dựa vào cấu tạo và đặc điểm sinh sản, không chỉ hình dạng', 'vì chúng có kích thước cơ thể chênh lệch nhau khá nhiều', 'vì chúng được các nhà khoa học phát hiện ở hai thời điểm khác nhau'), ans: 'B', why: 'Hình dạng ngoài chỉ là một trong nhiều tiêu chí. Muốn xếp loài, người ta còn xét cấu tạo bên trong và khả năng sinh sản tạo ra thế hệ con. Bẫy ở phương án A: nhiều loài sống ở hai môi trường khác nhau vẫn là một loài, ví dụ cùng một loài cá sống được ở cả ao và sông.' },
    { sec: 'Thực vật và động vật', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Đặc điểm nào dùng để phân biệt giới Thực vật với giới Động vật?', opts: o4('thực vật có tế bào nhân thực, động vật có tế bào nhân sơ', 'thực vật là cơ thể đa bào, động vật là cơ thể đơn bào', 'thực vật sống ở cạn, còn động vật chỉ sống được ở dưới nước', 'thực vật có thành tế bào và lục lạp, động vật thì không có'), ans: 'D', why: 'Cả thực vật và động vật đều đa bào và đều có tế bào nhân thực, nên hai phương án đầu sai. Điểm khác cơ bản là tế bào thực vật có thành tế bào và lục lạp, còn tế bào động vật thì không.' },
    { sec: 'Giới Động vật', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Giới Động vật gồm các sinh vật có đặc điểm:', opts: o4('đa bào, nhân thực, dị dưỡng, phần lớn di chuyển được', 'đơn bào, nhân sơ, tự dưỡng và sống cố định một chỗ', 'đa bào, nhân thực, tự dưỡng nhờ có chứa nhiều lục lạp', 'đơn bào hoặc đa bào, nhân thực và sống kí sinh bắt buộc'), ans: 'A', why: 'Động vật là sinh vật đa bào, tế bào nhân thực, không tự tạo được chất hữu cơ (dị dưỡng) và phần lớn có khả năng di chuyển.' },
    { sec: 'Giới Nấm', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Nhóm nào sau đây gồm toàn sinh vật thuộc giới Nấm?', opts: o4('tảo lục, nấm rơm, cây rêu', 'trùng roi, nấm men, vi khuẩn', 'nấm hương, nấm men, nấm mốc', 'nấm rơm, cây thông, trùng giày'), ans: 'C', why: 'Nấm hương, nấm men và nấm mốc đều thuộc giới Nấm. Các nhóm còn lại đều bị pha thêm sinh vật của giới khác: tảo lục và trùng roi thuộc Nguyên sinh, cây rêu và cây thông thuộc Thực vật, vi khuẩn thuộc Khởi sinh.' },
    { sec: 'Vận dụng phân loại', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Quan sát một mẫu nước ao dưới kính hiển vi, em thấy cơ thể chỉ gồm một tế bào có nhân, có roi, di chuyển được và có màu xanh lục. Sinh vật đó thuộc giới nào?', opts: o4('giới Khởi sinh', 'giới Nguyên sinh', 'giới Thực vật', 'giới Động vật'), ans: 'B', why: 'Phải nối ba dữ kiện: "có nhân" ⇒ nhân thực, loại giới Khởi sinh (vi khuẩn nhân sơ); "chỉ gồm một tế bào" ⇒ loại Thực vật và Động vật vì hai giới này luôn đa bào. Còn lại là giới Nguyên sinh — đây chính là trùng roi xanh, vừa có lục lạp nên màu xanh, vừa có roi để bơi. Bẫy ở phương án C: thấy màu xanh lục liền nghĩ ngay đến thực vật.' },
    { sec: 'Vận dụng khóa lưỡng phân', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Một cửa hàng xếp rau củ vào hai khay: khay 1 "phần ăn được mọc trên mặt đất", khay 2 "phần ăn được nằm dưới mặt đất". Loại nào được xếp vào khay 2?', opts: o4('cải bắp', 'rau muống', 'quả bí đỏ', 'củ cà rốt'), ans: 'D', why: 'Củ cà rốt là phần rễ phình to nằm dưới mặt đất nên thuộc khay 2. Cải bắp, rau muống và quả bí đỏ đều là phần mọc trên mặt đất.' },
    { sec: 'Giới Khởi sinh', lvl: 'TH', name: 'Câu 21', pts: 1, text: 'Sinh vật nào sau đây thuộc giới Khởi sinh?', opts: o4('trùng biến hình', 'nấm mốc trắng', 'vi khuẩn lam', 'cây dương xỉ'), ans: 'C', why: 'Vi khuẩn lam là vi khuẩn, có tế bào nhân sơ nên thuộc giới Khởi sinh. Bẫy nằm ở chỗ vi khuẩn lam có màu xanh và tự tạo được chất hữu cơ nên nhiều bạn nhầm sang giới Thực vật.' },
    { sec: 'Cơ sở phân loại', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Việc phân loại sinh vật dựa trên cơ sở nào?', opts: o4('đặc điểm giống và khác nhau về hình thái, cấu tạo của sinh vật', 'số lượng cá thể của mỗi loài đang có ở trên Trái Đất', 'thời gian mà loài sinh vật đó được con người phát hiện ra', 'mức độ có lợi hay có hại của sinh vật đối với con người'), ans: 'A', why: 'Cơ sở của phân loại là những đặc điểm giống và khác nhau về hình thái, cấu tạo, cách sinh sản của sinh vật, chứ không phải số lượng hay lợi ích với con người.' },
    { sec: 'Bậc phân loại', lvl: 'NC', name: 'Câu 23', pts: 1, text: 'Cây bưởi và cây cam đều thuộc chi <i>Citrus</i>. Nhận định nào sau đây ĐÚNG?', opts: o4('Bưởi và cam là hai cá thể của cùng một loài duy nhất', 'Bưởi và cam thuộc hai giới khác nhau vì quả khác nhau', 'Bưởi và cam cùng một chi nhưng lại khác ngành với nhau', 'Bưởi và cam cùng chi nên chắc chắn cùng họ và cùng bộ'), ans: 'D', why: 'Chi là bậc nằm trong họ, họ nằm trong bộ. Vì thế cùng chi thì bắt buộc cùng họ, cùng bộ và cùng mọi bậc lớn hơn. Bẫy ở phương án A: cùng chi không có nghĩa là cùng loài — bưởi và cam là hai loài riêng, chỉ chung nhau tên chi <i>Citrus</i>.' },
    { sec: 'Khóa lưỡng phân', lvl: 'TH', name: 'Câu 24', pts: 1, text: 'Khóa lưỡng phân được dùng để làm gì?', opts: o4('đếm chính xác số lượng cá thể của mỗi loài sinh vật', 'nhận biết và xác định tên của một sinh vật chưa biết', 'làm cho các loài sinh vật trong tự nhiên đa dạng hơn', 'ghi lại nơi sống và thời gian hoạt động của sinh vật'), ans: 'B', why: 'Khóa lưỡng phân là công cụ tra cứu: đi theo từng cặp đặc điểm đối lập để dần dần xác định được tên của sinh vật đang quan sát.' },
    { sec: 'Tên khoa học', lvl: 'NB', name: 'Câu 25', pts: 1, text: 'Tên khoa học của loài được viết bằng ngôn ngữ nào?', opts: o4('tiếng Anh', 'tiếng Pháp', 'tiếng Latin', 'tiếng Việt'), ans: 'C', why: 'Tên khoa học được viết bằng tiếng Latin (hoặc chữ Latin hóa) và viết nghiêng, nhờ đó các nhà khoa học ở mọi quốc gia đều hiểu giống nhau.' },
    { sec: 'Khóa lưỡng phân', lvl: 'NC', name: 'Câu 26', pts: 1, text: 'Bạn Bình lập khóa lưỡng phân cho: chim bồ câu, dơi, cá voi, cá chép, ếch. Bình gộp dơi và cá voi cùng nhóm với chim bồ câu vì "đều biết bay hoặc bơi nhanh". Cách làm này sai vì:', opts: o4('dơi và cá voi là hai loài sinh vật thuộc giới Thực vật', 'khóa lưỡng phân chỉ dùng được cho các loài thực vật', 'ngay ở bước đầu phải chia năm loài này thành năm nhóm', 'mỗi bước chỉ được dùng một cặp đặc điểm đối lập rõ ràng'), ans: 'D', why: 'Bình đã gộp hai đặc điểm khác nhau ("biết bay" và "bơi nhanh") vào cùng một bước, nên nhóm tạo ra không có đặc điểm chung thật sự. Quy tắc là mỗi bước chỉ dùng đúng một cặp đặc điểm đối lập, ví dụ "có lông vũ / không có lông vũ". Bẫy ở phương án C: khóa lưỡng phân luôn chia đôi ở mỗi bước, không bao giờ chia thành năm nhóm cùng lúc.' },
    { sec: 'Vận dụng khóa lưỡng phân', lvl: 'VD', name: 'Câu 27', pts: 1, text: 'Một khu vườn có: cây mít, cây ớt, cây thông, cây rêu. Nếu dùng cặp đặc điểm "có hoa / không có hoa" để chia thì nhóm "có hoa" gồm:', opts: o4('cây mít và cây ớt', 'cây mít và cây thông', 'cây thông và cây rêu', 'cây ớt và cây rêu'), ans: 'A', why: 'Mít và ớt là cây Hạt kín nên có hoa. Cây thông thuộc Hạt trần, chỉ có nón chứ chưa có hoa thật; cây rêu sinh sản bằng bào tử, cũng không có hoa.' },
    { sec: 'Giới Thực vật', lvl: 'TH', name: 'Câu 28', pts: 1, text: 'Sinh vật nào sau đây KHÔNG thuộc giới Thực vật?', opts: o4('cây dương xỉ', 'nấm linh chi', 'cây rêu tường', 'cây lúa nước'), ans: 'B', why: 'Nấm linh chi thuộc giới Nấm vì không có lục lạp, không tự tạo được chất hữu cơ. Dương xỉ, rêu và lúa đều là thực vật.' },
    { sec: 'Đa dạng sinh vật', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Sự đa dạng của thế giới sống thể hiện rõ nhất ở:', opts: o4('số lượng cá thể của một loài sống trong cùng một đàn', 'kích thước cơ thể của từng cá thể sinh vật cụ thể', 'số lượng loài và số lượng cá thể trong mỗi loài', 'thời gian sống được của một cá thể sinh vật bất kì'), ans: 'C', why: 'Đa dạng sinh học thể hiện ở số lượng loài, số lượng cá thể trong mỗi loài và sự đa dạng về môi trường sống của chúng.' },
    { sec: 'Tên khoa học', lvl: 'NC', name: 'Câu 30', pts: 1, text: 'Vì sao khi nghiên cứu một sinh vật lạ, các nhà khoa học phải xác định tên khoa học của nó thay vì chỉ dùng tên gọi ở địa phương?', opts: o4('vì mỗi loài chỉ có một tên khoa học dùng chung trên toàn thế giới', 'vì tên khoa học luôn ngắn và dễ nhớ hơn tên gọi ở địa phương', 'vì tên địa phương chỉ dùng cho thực vật, không dùng cho động vật', 'vì tên khoa học cho biết chính xác nơi sống của loài sinh vật đó'), ans: 'A', why: 'Cùng một loài có thể mang rất nhiều tên địa phương khác nhau, và ngược lại một tên địa phương có khi chỉ nhiều loài, dễ gây nhầm lẫn. Tên khoa học là duy nhất cho mỗi loài và được dùng thống nhất ở mọi quốc gia. Bẫy ở phương án D: tên khoa học chỉ cho biết chi và loài, hoàn toàn không cho biết nơi sống.' },
  ],
},

/* ═══════════ ĐỀ 12 — VIRUS VÀ VI KHUẨN ═══════════ */
{
  id: 10662, title: 'Đề 12 · Virus và vi khuẩn', time: 60,
  questions: [
    { sec: 'Đặc điểm virus', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Virus có đặc điểm nào sau đây?', opts: o4('có cấu tạo tế bào hoàn chỉnh như vi khuẩn', 'chưa có cấu tạo tế bào, kích thước rất nhỏ', 'là cơ thể đa bào, có nhân và chất tế bào', 'có thành tế bào và lục lạp như thực vật'), ans: 'B', why: 'Virus chưa có cấu tạo tế bào, kích thước rất nhỏ (khoảng vài chục nanomet), chỉ gồm lớp vỏ protein bọc vật chất di truyền.' },
    { sec: 'Đời sống của virus', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Vì sao virus chỉ nhân lên được khi ở bên trong tế bào vật chủ?', opts: o4('vì virus chưa có cấu tạo tế bào nên phải dùng bộ máy của tế bào chủ', 'vì bên ngoài tế bào chủ nhiệt độ luôn quá thấp đối với virus', 'vì virus cần ánh sáng của tế bào chủ để tạo ra chất hữu cơ', 'vì virus có kích thước quá nhỏ nên không tự di chuyển được'), ans: 'A', why: 'Virus không có chất tế bào, không có bộ máy tổng hợp riêng nên không thể tự tạo ra vật chất cho bản thân. Nó phải xâm nhập vào tế bào sống và sử dụng nguyên liệu, bộ máy của tế bào đó để tạo ra virus mới. Bẫy ở phương án C: tế bào chủ không "phát sáng" và virus cũng không tự tạo chất hữu cơ.' },
    { sec: 'Bệnh do virus', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Bệnh nào sau đây do virus gây ra?', opts: o4('bệnh lao phổi', 'bệnh uốn ván', 'bệnh tả cấp', 'bệnh cúm mùa'), ans: 'D', why: 'Cúm mùa do virus cúm gây ra. Lao, uốn ván và tả đều là bệnh do vi khuẩn, vì vậy có thể điều trị bằng kháng sinh còn cúm thì không.' },
    { sec: 'Đặc điểm vi khuẩn', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Vi khuẩn là sinh vật có cấu tạo:', opts: o4('đa bào, tế bào nhân thực', 'đa bào, tế bào nhân sơ', 'đơn bào, tế bào nhân sơ', 'đơn bào, tế bào nhân thực'), ans: 'C', why: 'Vi khuẩn là sinh vật đơn bào, tế bào nhân sơ (chưa có nhân hoàn chỉnh). Phương án D là đặc điểm của nguyên sinh vật, rất dễ nhầm.' },
    { sec: 'Cấu tạo vi khuẩn', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Tế bào vi khuẩn KHÔNG có bộ phận nào sau đây?', opts: o4('màng tế bào', 'nhân hoàn chỉnh', 'chất tế bào', 'thành tế bào'), ans: 'B', why: 'Vi khuẩn là tế bào nhân sơ: vật chất di truyền nằm trong vùng nhân, chưa có màng nhân bao bọc nên chưa có nhân hoàn chỉnh. Màng, chất tế bào và thành tế bào thì vi khuẩn vẫn có.' },
    { sec: 'Kháng sinh', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Vì sao dùng thuốc kháng sinh để chữa bệnh cúm lại không có tác dụng?', opts: o4('vì thuốc kháng sinh chỉ dùng được cho trẻ em dưới sáu tuổi', 'vì virus cúm đã bị tiêu diệt hết trước khi người bệnh uống thuốc', 'vì bệnh cúm là bệnh nhẹ nên cơ thể không cần dùng đến thuốc', 'vì kháng sinh chỉ diệt được vi khuẩn, còn cúm là bệnh do virus'), ans: 'D', why: 'Kháng sinh tác động lên các bộ phận đặc trưng của tế bào vi khuẩn (thành tế bào, bộ máy tổng hợp chất). Virus chưa có cấu tạo tế bào nên kháng sinh không có "đích" để tác động. Dùng kháng sinh bừa bãi còn làm vi khuẩn trong cơ thể quen thuốc, sau này khó chữa.' },
    { sec: 'Hình dạng vi khuẩn', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Các hình dạng thường gặp của vi khuẩn là:', opts: o4('hình cầu, hình que, hình xoắn', 'hình vuông, hình tam giác, hình thoi', 'hình sao, hình lá, hình chóp nón', 'hình đĩa lõm, hình nón, hình trụ dẹt'), ans: 'A', why: 'Vi khuẩn thường có ba dạng chính: hình cầu (cầu khuẩn), hình que (trực khuẩn) và hình xoắn (xoắn khuẩn), ngoài ra còn có dạng dấu phẩy.' },
    { sec: 'Ứng dụng vi khuẩn', lvl: 'VD', name: 'Câu 8', pts: 1, text: 'Khi làm sữa chua, người ta cho sữa đã pha men vào hũ rồi ủ ấm khoảng 6 – 8 giờ. Việc ủ ấm nhằm mục đích:', opts: o4('làm cho sữa bay hơi bớt nước để đặc lại', 'giết chết toàn bộ vi khuẩn có trong hũ sữa', 'tạo nhiệt độ thích hợp cho vi khuẩn lactic hoạt động', 'giúp đường trong sữa tự phân hủy thành chất chua'), ans: 'C', why: 'Vi khuẩn lactic hoạt động mạnh ở khoảng 40 – 45 °C. Ủ ấm giữ nhiệt độ thích hợp để chúng lên men đường trong sữa tạo vị chua và làm sữa đông lại. Nếu ủ quá nóng, vi khuẩn sẽ chết và sữa không lên men được.' },
    { sec: 'Bảo quản thức ăn', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Cơm nguội để ngoài trời nóng ẩm, sau một ngày bị thiu và có mùi chua. Nguyên nhân chính là:', opts: o4('nước trong cơm bay hơi hết nên cơm bị biến đổi mùi vị', 'vi khuẩn gặp điều kiện ấm và ẩm nên sinh sản rất nhanh', 'ánh sáng mặt trời đã làm tinh bột trong cơm thành chất chua', 'không khí lạnh ban đêm làm các hạt cơm bị đông cứng lại'), ans: 'B', why: 'Cơm giàu tinh bột, lại ấm và ẩm nên là môi trường lí tưởng cho vi khuẩn. Vi khuẩn sinh sản bằng cách phân đôi rất nhanh, phân giải thức ăn và thải ra chất làm cơm chua, có mùi. Bẫy ở phương án A: nếu cơm khô đi thì lại lâu thiu hơn, chứ không phải nguyên nhân gây thiu.' },
    { sec: 'Vai trò vi khuẩn', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Vai trò nào sau đây là của vi khuẩn có lợi?', opts: o4('phân hủy xác sinh vật, làm sạch môi trường', 'gây ra bệnh tả và bệnh lị cho con người', 'làm cho thức ăn nhanh bị ôi thiu và hỏng', 'phá hủy cấu trúc tế bào của cây trồng'), ans: 'A', why: 'Vi khuẩn phân hủy xác động vật, thực vật thành chất khoáng trả lại cho đất, nhờ đó môi trường được làm sạch và cây trồng có chất dinh dưỡng. Ba phương án còn lại đều là tác hại.' },
    { sec: 'Cấu tạo virus', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Virus được cấu tạo gồm:', opts: o4('màng tế bào và nhân tế bào', 'thành tế bào và chất tế bào', 'lớp vỏ đường và nhiều lục lạp', 'lớp vỏ protein và vật chất di truyền'), ans: 'D', why: 'Virus chỉ gồm hai phần: lớp vỏ protein bên ngoài và vật chất di truyền bên trong. Các thành phần như màng tế bào, chất tế bào, nhân chỉ có ở sinh vật có cấu tạo tế bào.' },
    { sec: 'Phòng bệnh', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Biện pháp hiệu quả nhất để phòng các bệnh do virus gây ra là:', opts: o4('uống thật nhiều thuốc kháng sinh mỗi ngày', 'tiêm vaccine phòng bệnh đầy đủ, đúng lịch', 'ăn thật nhiều thức ăn có chứa chất đạm', 'tắm nước thật nóng vào mỗi buổi tối'), ans: 'B', why: 'Vaccine giúp cơ thể tạo được khả năng chống lại mầm bệnh trước khi mắc bệnh, nên là cách phòng bệnh do virus hiệu quả nhất. Kháng sinh không diệt được virus.' },
    { sec: 'Bảo quản thức ăn', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Vì sao thức ăn để trong tủ lạnh lại lâu hỏng hơn để ở ngoài?', opts: o4('vì trong tủ lạnh không hề có một vi khuẩn nào tồn tại được', 'vì hơi lạnh đã tiêu diệt hoàn toàn mọi vi khuẩn trong thức ăn', 'vì nhiệt độ thấp làm vi khuẩn sinh sản chậm lại rất nhiều', 'vì thức ăn trong tủ lạnh được giữ kín nên không cần bảo quản'), ans: 'C', why: 'Nhiệt độ thấp không giết được vi khuẩn mà chỉ làm chúng hoạt động và sinh sản chậm lại, nhờ đó thức ăn lâu hỏng hơn. Bẫy ở phương án B: nếu vi khuẩn bị diệt hết thì thức ăn để tủ lạnh sẽ không bao giờ hỏng — thực tế để lâu vẫn hỏng.' },
    { sec: 'Bệnh do virus', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Bạn Lan bị bệnh sởi, bác sĩ cho biết đây là bệnh do virus. Lời khuyên nào sau đây ĐÚNG?', opts: o4('nghỉ ngơi, ăn uống đủ chất và cách li để không lây cho người khác', 'tự mua thuốc kháng sinh liều cao về uống cho nhanh khỏi bệnh', 'vẫn đến lớp học bình thường vì bệnh sởi hoàn toàn không lây', 'tắm nước thật lạnh nhiều lần trong ngày để hạ nhanh cơn sốt'), ans: 'A', why: 'Bệnh do virus chưa có thuốc đặc trị thông thường, cách xử lí là nâng cao sức khỏe để cơ thể tự chống lại, đồng thời cách li vì sởi lây rất mạnh qua đường hô hấp. Bẫy ở phương án B: kháng sinh không diệt được virus, uống bừa còn gây hại cho cơ thể.' },
    { sec: 'Bệnh do vi khuẩn', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Nhóm bệnh nào sau đây đều do vi khuẩn gây ra?', opts: o4('cúm mùa, sởi, bệnh dại', 'sởi, quai bị, thủy đậu', 'bệnh dại, viêm gan B, cúm', 'bệnh lao, bệnh tả, uốn ván'), ans: 'D', why: 'Lao, tả và uốn ván đều do vi khuẩn gây ra. Cúm, sởi, dại, quai bị, thủy đậu, viêm gan B đều do virus.' },
    { sec: 'Nơi sống vi khuẩn', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Vi khuẩn sống được ở đâu?', opts: o4('chỉ sống được trong cơ thể người', 'chỉ sống được ở trong nước biển', 'ở khắp nơi: đất, nước, không khí, cơ thể sinh vật', 'chỉ sống được ở nơi có nhiệt độ rất cao'), ans: 'C', why: 'Vi khuẩn có mặt ở hầu hết mọi nơi: trong đất, nước, không khí, trên da và trong cơ thể sinh vật, kể cả những nơi khắc nghiệt.' },
    { sec: 'Ứng dụng vi khuẩn', lvl: 'VD', name: 'Câu 17', pts: 1, text: 'Khi muối dưa cải, người ta thường cho thêm một ít đường và dùng nước ấm. Lí do là:', opts: o4('đường làm cho dưa có vị ngọt nên bớt chua hơn', 'đường và nước ấm tạo điều kiện cho vi khuẩn lên men mạnh', 'nước ấm giúp rửa sạch hết vi khuẩn bám trên lá dưa', 'đường làm cho lá dưa mềm ra và đổi sang màu vàng'), ans: 'B', why: 'Vi khuẩn lactic cần đường làm nguyên liệu lên men và cần nhiệt độ ấm để hoạt động mạnh. Nhờ đó dưa nhanh chua và bảo quản được lâu. Bẫy ở phương án C: nếu rửa sạch hết vi khuẩn thì dưa sẽ không bao giờ chua được.' },
    { sec: 'Vệ sinh phòng bệnh', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Vì sao phải rửa tay bằng xà phòng trước khi ăn?', opts: o4('để loại bỏ vi khuẩn gây bệnh bám ở trên da tay', 'để làm cho bàn tay có mùi thơm dễ chịu hơn', 'để cho da tay trở nên mềm mại và trắng hơn', 'để bàn tay bớt nóng trước khi cầm vào thức ăn'), ans: 'A', why: 'Tay tiếp xúc với nhiều vật nên mang theo rất nhiều vi khuẩn. Xà phòng giúp cuốn trôi chúng, ngăn vi khuẩn theo thức ăn vào cơ thể gây bệnh đường tiêu hóa.' },
    { sec: 'Vai trò vi khuẩn', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Trong tự nhiên, nếu không có vi khuẩn phân hủy thì điều gì sẽ xảy ra?', opts: o4('các loài động vật sẽ sinh sản nhanh hơn rất nhiều lần', 'cây xanh sẽ không còn cần đến ánh sáng mặt trời nữa', 'xác sinh vật chất đống lại, chất khoáng không trở về đất', 'nước ở trong ao hồ sẽ trở nên trong sạch hơn hiện nay'), ans: 'C', why: 'Vi khuẩn phân hủy là mắt xích trả chất khoáng từ xác sinh vật về cho đất. Thiếu chúng, xác sinh vật sẽ tồn đọng, đất nghèo dần chất khoáng và cây trồng không phát triển được. Bẫy ở phương án D: xác phân hủy dở dang càng làm nước bẩn hơn chứ không trong sạch hơn.' },
    { sec: 'Kích thước virus', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'So với vi khuẩn, kích thước của virus:', opts: o4('lớn hơn tế bào vi khuẩn nhiều lần', 'bằng kích thước của một tế bào người', 'đủ lớn để nhìn rõ bằng mắt thường', 'nhỏ hơn vi khuẩn rất nhiều lần'), ans: 'D', why: 'Virus nhỏ hơn vi khuẩn hàng chục đến hàng trăm lần, phải dùng kính hiển vi điện tử mới quan sát được.' },
    { sec: 'Phòng dịch bệnh', lvl: 'VD', name: 'Câu 21', pts: 1, text: 'Khi có dịch bệnh lây qua đường hô hấp, biện pháp nào sau đây giúp hạn chế lây lan hiệu quả nhất?', opts: o4('uống thật nhiều nước ngọt có ga mỗi ngày', 'đeo khẩu trang và giữ khoảng cách nơi đông người', 'mở hết cửa sổ rồi bật quạt thổi mạnh vào nhau', 'ăn thật nhiều thức ăn nhanh cho đủ năng lượng'), ans: 'B', why: 'Bệnh lây qua đường hô hấp truyền theo các giọt bắn khi nói, ho, hắt hơi. Khẩu trang và khoảng cách chặn con đường lây này. Bẫy ở phương án C: quạt thổi thẳng vào nhau lại đẩy giọt bắn đi xa hơn.' },
    { sec: 'So sánh virus – vi khuẩn', lvl: 'NC', name: 'Câu 22', pts: 1, text: 'So sánh virus và vi khuẩn, nhận định nào sau đây ĐÚNG?', opts: o4('cả hai đều là cơ thể đơn bào có nhân hoàn chỉnh', 'cả hai đều sống kí sinh bắt buộc trong tế bào chủ', 'vi khuẩn có cấu tạo tế bào, còn virus thì chưa có', 'virus có cấu tạo tế bào, còn vi khuẩn thì chưa có'), ans: 'C', why: 'Vi khuẩn là một tế bào hoàn chỉnh (dù là nhân sơ), còn virus chưa có cấu tạo tế bào. Phương án D đảo ngược hoàn toàn nên sai; phương án B cũng sai vì nhiều vi khuẩn sống tự do trong đất, nước chứ không kí sinh bắt buộc.' },
    { sec: 'Ứng dụng vi khuẩn', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Sữa chua, dưa muối, nem chua là những sản phẩm được tạo ra nhờ:', opts: o4('hoạt động lên men của vi khuẩn có lợi', 'sự nhân lên của virus trong thực phẩm', 'phản ứng giữa muối ăn với nước sạch', 'ánh sáng mặt trời chiếu vào thực phẩm'), ans: 'A', why: 'Đây đều là sản phẩm lên men: vi khuẩn lactic phân giải đường tạo vị chua, đồng thời ức chế vi khuẩn gây hỏng nên thực phẩm bảo quản được lâu hơn.' },
    { sec: 'Bệnh do virus', lvl: 'NB', name: 'Câu 24', pts: 1, text: 'Virus HIV gây bệnh làm suy giảm:', opts: o4('khả năng tiêu hóa thức ăn của cơ thể', 'khả năng nhìn rõ của mắt vào ban đêm', 'khả năng vận động của hệ cơ và xương', 'khả năng miễn dịch của cơ thể người'), ans: 'D', why: 'HIV tấn công các tế bào bảo vệ cơ thể nên làm suy giảm miễn dịch, khiến người bệnh dễ mắc nhiều bệnh khác.' },
    { sec: 'Điều kiện sống', lvl: 'TH', name: 'Câu 25', pts: 1, text: 'Điều kiện nào sau đây giúp vi khuẩn sinh sản nhanh nhất?', opts: o4('khô ráo, lạnh và không có chất dinh dưỡng', 'ấm áp, ẩm ướt và có nhiều chất dinh dưỡng', 'nhiệt độ rất cao, trên một trăm độ C', 'ngâm trong dung dịch muối đặc và khô'), ans: 'B', why: 'Vi khuẩn cần ba yếu tố: nhiệt độ ấm, độ ẩm và chất dinh dưỡng. Đây cũng chính là lí do các biện pháp bảo quản thức ăn đều nhằm làm mất đi một trong ba yếu tố đó (phơi khô, ướp muối, để lạnh).' },
    { sec: 'Vai trò vi khuẩn', lvl: 'NC', name: 'Câu 26', pts: 1, text: 'Một bạn nói: "Mọi vi khuẩn đều có hại nên cần tiêu diệt hết." Nhận định này SAI vì:', opts: o4('nhiều vi khuẩn có lợi: phân hủy xác, lên men, sống trong ruột người', 'vi khuẩn không thể bị tiêu diệt bằng bất cứ cách nào của con người', 'vi khuẩn có hại chỉ sống được ở trong nước, không sống ở trên cạn', 'vi khuẩn không gây ra bệnh nào cho người và các loài động vật khác'), ans: 'A', why: 'Chỉ một phần nhỏ vi khuẩn gây bệnh. Rất nhiều loài có lợi: phân hủy xác sinh vật, lên men làm sữa chua và dưa muối, sống trong ruột người giúp tiêu hóa thức ăn. Bẫy ở phương án D: nói vi khuẩn không gây bệnh nào là sai hẳn theo hướng ngược lại — lao, tả, uốn ván đều do vi khuẩn.' },
    { sec: 'Sinh sản vi khuẩn', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Vi khuẩn sinh sản bằng cách:', opts: o4('nảy chồi liên tục', 'tạo ra nhiều bào tử', 'phân đôi tế bào', 'kết hợp hai cá thể'), ans: 'C', why: 'Vi khuẩn sinh sản bằng cách phân đôi: một tế bào tách thành hai tế bào con. Nhờ vậy số lượng tăng rất nhanh khi gặp điều kiện thuận lợi.' },
    { sec: 'Vệ sinh an toàn thực phẩm', lvl: 'TH', name: 'Câu 28', pts: 1, text: 'Vì sao không nên ăn thức ăn đã bị ôi thiu?', opts: o4('vì thức ăn ôi thiu không còn mùi thơm hấp dẫn nữa', 'vì thức ăn ôi thiu thường có màu sắc không đẹp mắt', 'vì thức ăn ôi thiu đã mất hết toàn bộ lượng nước', 'vì trong đó có nhiều vi khuẩn và chất độc do chúng tạo ra'), ans: 'D', why: 'Thức ăn ôi thiu chứa lượng lớn vi khuẩn cùng các chất độc chúng thải ra, ăn vào dễ gây ngộ độc, đau bụng, tiêu chảy. Mùi và màu chỉ là dấu hiệu nhận biết chứ không phải lí do chính.' },
    { sec: 'Vaccine', lvl: 'NC', name: 'Câu 29', pts: 1, text: 'Vì sao sau khi tiêm vaccine, cơ thể lại có khả năng phòng được bệnh đó về sau?', opts: o4('vì vaccine tiêu diệt hết mọi loại virus đang có trong không khí', 'vì cơ thể được tập nhận biết mầm bệnh và tạo ra khả năng chống lại', 'vì vaccine bổ sung chất dinh dưỡng giúp cơ thể khỏe hơn hẳn', 'vì sau khi tiêm, da người được tiêm dày lên nên mầm bệnh khó vào'), ans: 'B', why: 'Vaccine chứa mầm bệnh đã bị làm yếu hoặc chết, đưa vào cơ thể để cơ thể "tập dượt" nhận biết và tạo ra khả năng chống lại. Khi mầm bệnh thật xâm nhập, cơ thể phản ứng nhanh nên không mắc bệnh hoặc bệnh nhẹ. Bẫy ở phương án A: vaccine tác động lên cơ thể người, không diệt virus ngoài không khí.' },
    { sec: 'Giới Khởi sinh', lvl: 'NB', name: 'Câu 30', pts: 1, text: 'Nhóm sinh vật nào sau đây thuộc giới Khởi sinh?', opts: o4('các loài nấm men', 'các loài trùng roi', 'các loài vi khuẩn', 'các loài rêu nhỏ'), ans: 'C', why: 'Giới Khởi sinh gồm vi khuẩn — sinh vật đơn bào nhân sơ. Nấm men thuộc giới Nấm, trùng roi thuộc giới Nguyên sinh, rêu thuộc giới Thực vật.' },
  ],
},

/* ═══════════ ĐỀ 13 — NGUYÊN SINH VẬT VÀ NẤM ═══════════ */
{
  id: 10663, title: 'Đề 13 · Nguyên sinh vật và nấm', time: 60,
  questions: [
    { sec: 'Đặc điểm nguyên sinh vật', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Nguyên sinh vật phần lớn là những sinh vật:', opts: o4('đa bào, tế bào nhân sơ', 'đa bào, tế bào nhân thực', 'đơn bào, tế bào nhân sơ', 'đơn bào, tế bào nhân thực'), ans: 'D', why: 'Nguyên sinh vật đa số là cơ thể đơn bào nhưng đã có nhân hoàn chỉnh (nhân thực). Phương án C là đặc điểm của vi khuẩn — giới Khởi sinh, rất dễ nhầm.' },
    { sec: 'Nhận biết nguyên sinh vật', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Sinh vật nào sau đây là nguyên sinh vật?', opts: o4('nấm rơm', 'vi khuẩn lam', 'trùng roi', 'cây rêu'), ans: 'C', why: 'Trùng roi là sinh vật đơn bào nhân thực sống trong nước, thuộc giới Nguyên sinh. Vi khuẩn lam thuộc giới Khởi sinh vì có tế bào nhân sơ.' },
    { sec: 'Trùng roi xanh', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Vì sao trùng roi xanh vừa có đặc điểm giống thực vật lại vừa có đặc điểm giống động vật?', opts: o4('vì nó có lục lạp để tự tạo chất hữu cơ và có roi để di chuyển', 'vì nó vừa sống được ở dưới nước lại vừa sống được ở trên cạn', 'vì nó có cơ thể đa bào giống thực vật và có nhân giống động vật', 'vì nó sinh sản bằng hạt giống thực vật và đẻ con giống động vật'), ans: 'A', why: 'Trùng roi xanh có lục lạp nên tự tạo được chất hữu cơ như thực vật, đồng thời có roi bơi và có thể lấy chất hữu cơ có sẵn như động vật. Chính vì mang đặc điểm của cả hai nhóm mà nó được xếp riêng vào giới Nguyên sinh. Bẫy ở phương án C: mọi nguyên sinh vật đều có nhân, và trùng roi là cơ thể đơn bào chứ không đa bào.' },
    { sec: 'Bệnh sốt rét', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'Trùng sốt rét kí sinh ở đâu trong cơ thể người?', opts: o4('trong thành ruột non', 'trong tế bào hồng cầu', 'trong hai lá phổi', 'trên bề mặt của da'), ans: 'B', why: 'Trùng sốt rét chui vào tế bào hồng cầu, sinh sản rồi phá vỡ hồng cầu làm người bệnh sốt theo cơn và thiếu máu.' },
    { sec: 'Nấm men', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Nấm men là loại nấm có cơ thể:', opts: o4('đa bào, dạng sợi dài', 'đa bào, dạng mũ tán', 'đa bào, dạng phiến mỏng', 'đơn bào, hình trứng nhỏ'), ans: 'D', why: 'Nấm men là nấm đơn bào, tế bào thường có hình trứng. Nấm mốc và nấm mũ mới là nấm đa bào dạng sợi.' },
    { sec: 'Ứng dụng nấm men', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Vì sao bột bánh mì khi ủ với men thì nở xốp lên?', opts: o4('vì nấm men phân giải đường và thải ra khí carbon dioxide', 'vì nấm men làm cho bột hút thêm thật nhiều nước vào trong', 'vì nấm men làm cho bột nóng lên nên các hạt bột nở rộng ra', 'vì nấm men tạo ra rất nhiều sợi nấm đan xen nhau trong bột'), ans: 'A', why: 'Nấm men phân giải đường trong bột, thải ra khí carbon dioxide. Khí này bị mạng bột giữ lại tạo thành vô số bọt nhỏ nên khối bột phồng lên và ruột bánh xốp. Bẫy ở phương án D: nấm men là nấm đơn bào, không tạo sợi.' },
    { sec: 'Phòng bệnh sốt rét', lvl: 'VD', name: 'Câu 7', pts: 1, text: 'Để phòng bệnh sốt rét, biện pháp quan trọng nhất là:', opts: o4('uống thật nhiều nước đun sôi để nguội', 'rửa tay bằng xà phòng trước khi ăn cơm', 'ngủ màn, diệt muỗi và diệt bọ gậy', 'ăn chín uống sôi, không ăn rau sống'), ans: 'C', why: 'Trùng sốt rét truyền từ người bệnh sang người lành qua vết đốt của muỗi Anopheles, không lây qua đường ăn uống. Vì vậy phải chặn đường lây bằng cách ngủ màn và diệt muỗi, diệt bọ gậy.' },
    { sec: 'Bệnh lị', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Sinh vật nào sau đây gây ra bệnh lị ở người, làm người bệnh đau bụng và đi ngoài ra máu?', opts: o4('trùng roi xanh', 'trùng kiết lị', 'trùng giày', 'tảo lục đơn bào'), ans: 'B', why: 'Trùng kiết lị theo thức ăn, nước uống vào ruột, phá hoại niêm mạc ruột gây đau bụng và đi ngoài ra máu. Trùng giày và tảo lục sống tự do trong nước, không gây bệnh này.' },
    { sec: 'Giới Nấm', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Nấm thuộc giới nào trong hệ thống năm giới?', opts: o4('giới Nấm', 'giới Thực vật', 'giới Động vật', 'giới Khởi sinh'), ans: 'A', why: 'Nấm được xếp thành một giới riêng vì có nhiều đặc điểm khác hẳn thực vật và động vật.' },
    { sec: 'Phân biệt nấm – thực vật', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Vì sao nấm KHÔNG được xếp vào giới Thực vật?', opts: o4('vì nấm có kích thước nhỏ hơn hẳn so với các loài thực vật', 'vì nấm chỉ sống được ở những nơi ẩm ướt và thiếu ánh sáng', 'vì nấm sinh sản bằng bào tử còn thực vật sinh sản bằng hạt', 'vì nấm không có lục lạp nên không tự tạo được chất hữu cơ'), ans: 'D', why: 'Điểm khác cơ bản là nấm không có lục lạp, phải lấy chất hữu cơ có sẵn từ xác sinh vật hoặc vật chủ, trong khi thực vật tự tạo được chất hữu cơ. Bẫy ở phương án C: sinh sản bằng bào tử không phải dấu hiệu phân biệt, vì rêu và dương xỉ là thực vật nhưng cũng sinh sản bằng bào tử.' },
    { sec: 'Nấm ăn được', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'Nhóm nào sau đây gồm toàn các loại nấm ăn được?', opts: o4('nấm độc đỏ, nấm mốc, nấm men', 'nấm mốc xanh, nấm rơm, nấm lim', 'nấm rơm, nấm hương, nấm sò', 'nấm mực, nấm độc tán trắng, nấm rơm'), ans: 'C', why: 'Nấm rơm, nấm hương và nấm sò đều là nấm ăn được, được nuôi trồng phổ biến. Các nhóm còn lại đều lẫn nấm độc hoặc nấm mốc không dùng làm thức ăn.' },
    { sec: 'Cấu tạo nấm mũ', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Bộ phận mang bào tử của nấm mũ nằm ở:', opts: o4('phần gốc nấm cắm xuống đất', 'các phiến mỏng dưới mũ nấm', 'mặt trên nhẵn của mũ nấm', 'phần lõi bên trong cuống nấm'), ans: 'B', why: 'Bào tử nằm ở các phiến mỏng xếp sát nhau dưới mũ nấm; khi chín, bào tử rơi xuống và được gió phát tán đi xa.' },
    { sec: 'Nấm mốc', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Một bạn để ổ bánh mì trong túi kín nơi ẩm, vài ngày sau thấy xuất hiện các đốm mốc màu xanh. Giải thích đúng là:', opts: o4('bột mì trong bánh đã tự biến đổi thành chất có màu xanh', 'túi kín làm bánh mì nóng lên rồi chuyển dần sang màu xanh', 'ánh sáng chiếu qua túi làm bề mặt bánh mì đổi sang màu xanh', 'bào tử nấm mốc có trong không khí gặp ẩm đã nảy mầm, phát triển'), ans: 'D', why: 'Trong không khí luôn có sẵn rất nhiều bào tử nấm mốc. Khi rơi vào nơi có chất dinh dưỡng, ẩm và ấm như ổ bánh mì trong túi kín, bào tử nảy mầm thành sợi nấm và tạo ra các đốm mốc. Bẫy ở phương án C: nấm mốc phát triển mạnh ở nơi tối và ẩm, ánh sáng không phải nguyên nhân.' },
    { sec: 'Nấm độc', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Vì sao không nên hái nấm lạ mọc hoang trong rừng để ăn?', opts: o4('vì nhiều nấm độc trông rất giống nấm ăn được, khó phân biệt', 'vì nấm mọc hoang trong rừng luôn có kích thước quá nhỏ', 'vì nấm mọc hoang trong rừng đều không có chất dinh dưỡng', 'vì nấm hoang chỉ ăn được sau khi đã phơi khô dưới nắng to'), ans: 'A', why: 'Nhiều loại nấm độc có hình dạng và màu sắc rất giống nấm ăn được, người không chuyên rất dễ nhầm, ăn vào có thể ngộ độc nặng hoặc tử vong. Bẫy ở phương án D: phơi khô hay nấu chín đều không phá hủy được chất độc trong nấm độc.' },
    { sec: 'Vai trò của nấm', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Nấm có vai trò nào sau đây trong tự nhiên?', opts: o4('tạo ra khí oxygen cho bầu khí quyển', 'giúp cây xanh hấp thụ ánh sáng mặt trời', 'phân hủy xác động vật và thực vật', 'làm tăng lượng nước ngầm trong lòng đất'), ans: 'C', why: 'Nấm hoại sinh phân hủy xác động vật, thực vật thành chất khoáng trả lại cho đất. Nấm không có lục lạp nên không thể tạo ra khí oxygen.' },
    { sec: 'Phòng chống nấm mốc', lvl: 'VD', name: 'Câu 16', pts: 1, text: 'Quần áo phơi chưa khô đã gấp cất vào tủ thường có mùi hôi và xuất hiện đốm mốc. Cách khắc phục hợp lí nhất là:', opts: o4('cất quần áo còn ẩm vào túi nylon buộc thật kín', 'phơi thật khô rồi mới cất, giữ tủ luôn khô thoáng', 'xếp quần áo ẩm sát vào nhau cho nhanh khô hơn', 'để quần áo ẩm ở nơi tối và kín gió ở trong tủ'), ans: 'B', why: 'Nấm mốc cần độ ẩm để phát triển, nên loại bỏ độ ẩm là cách phòng hiệu quả nhất. Các phương án còn lại đều giữ hoặc tăng độ ẩm, làm nấm mốc mọc nhanh hơn.' },
    { sec: 'Trùng giày', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Trùng giày di chuyển được nhờ bộ phận nào?', opts: o4('roi bơi dài ở phía trước', 'chân giả do chất tế bào tạo ra', 'các vây nhỏ ở hai bên cơ thể', 'lông bơi phủ khắp cơ thể'), ans: 'D', why: 'Trùng giày di chuyển nhờ lông bơi phủ khắp bề mặt cơ thể. Trùng roi dùng roi, trùng biến hình dùng chân giả.' },
    { sec: 'Trùng biến hình', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Trùng biến hình di chuyển và bắt mồi bằng:', opts: o4('chân giả', 'lông bơi', 'roi bơi', 'vây bơi'), ans: 'A', why: 'Trùng biến hình dồn chất tế bào về một phía tạo thành chân giả để bò và bao lấy thức ăn, vì thế hình dạng cơ thể luôn thay đổi.' },
    { sec: 'Phòng bệnh', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Vì sao bệnh do nguyên sinh vật gây ra thường lây lan mạnh ở vùng nhiều ao tù, nước đọng?', opts: o4('vì nước tù đọng làm nguyên sinh vật mất hẳn khả năng sinh sản', 'vì nước tù đọng là nơi nguyên sinh vật và muỗi phát triển mạnh', 'vì nước tù đọng chứa rất nhiều oxygen nên mọi sinh vật sống khỏe', 'vì nước tù đọng có nhiệt độ rất thấp, thích hợp với mọi mầm bệnh'), ans: 'B', why: 'Ao tù, nước đọng vừa là môi trường sống của nhiều nguyên sinh vật gây bệnh, vừa là nơi muỗi đẻ trứng và bọ gậy phát triển — mà muỗi lại là vật trung gian truyền trùng sốt rét. Hai yếu tố này cộng lại khiến bệnh lây lan mạnh. Bẫy ở phương án C: nước tù đọng thường thiếu oxygen chứ không nhiều oxygen.' },
    { sec: 'Tảo đơn bào', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'Tảo lục đơn bào có màu xanh lục là do trong tế bào có:', opts: o4('chân giả', 'lông bơi', 'lục lạp', 'không bào'), ans: 'C', why: 'Lục lạp chứa chất diệp lục màu xanh lục, giúp tảo tự tạo được chất hữu cơ.' },
    { sec: 'Sinh sản của nấm', lvl: 'TH', name: 'Câu 21', pts: 1, text: 'Hình thức sinh sản chủ yếu của nấm là:', opts: o4('sinh sản bằng bào tử', 'sinh sản bằng hạt nhỏ', 'sinh sản bằng hoa kín', 'sinh sản bằng quả khô'), ans: 'A', why: 'Nấm sinh sản chủ yếu bằng bào tử. Nấm không có hoa, quả hay hạt vì đó là cơ quan của thực vật Hạt kín.' },
    { sec: 'Ứng dụng nấm men', lvl: 'NC', name: 'Câu 22', pts: 1, text: 'Nấm men được dùng trong sản xuất rượu, bia và bánh mì vì nấm men:', opts: o4('tạo ra rất nhiều sợi nấm làm cho sản phẩm dai và chắc hơn', 'có màu sắc đẹp nên làm cho sản phẩm hấp dẫn người mua hơn', 'hút hết nước trong nguyên liệu nên sản phẩm bảo quản được lâu', 'phân giải đường trong nguyên liệu, tạo ra khí và rượu'), ans: 'D', why: 'Nấm men lên men đường: sản phẩm tạo ra gồm rượu và khí carbon dioxide. Khí làm bánh mì nở xốp, còn rượu là thành phần chính của rượu và bia. Bẫy ở phương án A: nấm men là nấm đơn bào nên không tạo sợi nấm.' },
    { sec: 'Nấm mốc', lvl: 'NB', name: 'Câu 23', pts: 1, text: 'Nấm mốc thường mọc trên:', opts: o4('mặt kính khô và sạch', 'thức ăn để lâu nơi ẩm', 'mặt kim loại khô ráo', 'nền gạch vừa lau khô'), ans: 'B', why: 'Nấm mốc cần chất dinh dưỡng và độ ẩm, nên phát triển mạnh trên thức ăn, bánh trái để lâu ở nơi ẩm thấp.' },
    { sec: 'Ứng dụng của nấm', lvl: 'TH', name: 'Câu 24', pts: 1, text: 'Loại nấm nào sau đây được dùng để chế tạo thuốc kháng sinh penicillin?', opts: o4('nấm rơm', 'nấm hương', 'nấm mốc xanh', 'nấm men bia'), ans: 'C', why: 'Penicillin được chiết từ nấm mốc xanh. Nấm rơm và nấm hương là nấm ăn, nấm men bia dùng để lên men.' },
    { sec: 'Bệnh do nấm', lvl: 'VD', name: 'Câu 25', pts: 1, text: 'Người bị bệnh lang ben, hắc lào ngoài da là do:', opts: o4('nấm kí sinh ở trên da gây ra', 'virus xâm nhập vào máu gây ra', 'trùng roi kí sinh ở trong ruột', 'thiếu chất đạm trong khẩu phần ăn'), ans: 'A', why: 'Lang ben và hắc lào do nấm kí sinh trên da gây ra, thường gặp khi da ẩm ướt lâu, mặc quần áo ẩm hoặc dùng chung khăn tắm.' },
    { sec: 'Thí nghiệm về nấm mốc', lvl: 'NC', name: 'Câu 26', pts: 1, text: 'Hai bạn để hai lát bánh mì giống nhau: lát A trong hộp kín có bông ẩm, lát B trong hộp kín có gói hút ẩm. Sau 3 ngày lát A mốc nhiều hơn hẳn. Kết luận đúng là:', opts: o4('nấm mốc chỉ mọc được ở trong hộp có nắp đậy thật kín', 'độ ẩm cao là điều kiện thuận lợi cho nấm mốc phát triển', 'ánh sáng là yếu tố quyết định tốc độ phát triển của nấm mốc', 'nhiệt độ trong hộp A cao hơn nên nấm mốc phát triển nhanh hơn'), ans: 'B', why: 'Hai hộp giống nhau hoàn toàn về loại bánh, độ kín, ánh sáng và nhiệt độ, chỉ khác nhau đúng một yếu tố là độ ẩm. Vì vậy chỉ được kết luận về yếu tố độ ẩm. Bẫy ở phương án D: đề không cho dữ kiện nào về nhiệt độ, hai hộp cùng đặt trong một điều kiện nên không thể kết luận như vậy.' },
    { sec: 'Nơi sống', lvl: 'NB', name: 'Câu 27', pts: 1, text: 'Nguyên sinh vật thường sống ở đâu?', opts: o4('trong lớp đất đá khô cằn', 'trên bề mặt kim loại khô', 'trong không khí trên cao', 'trong nước ao, hồ, biển'), ans: 'D', why: 'Nguyên sinh vật sống chủ yếu trong môi trường nước như ao, hồ, biển; một số sống kí sinh trong cơ thể sinh vật khác.' },
    { sec: 'So sánh nấm – thực vật', lvl: 'TH', name: 'Câu 28', pts: 1, text: 'Đặc điểm nào sau đây có ở cả nấm và thực vật?', opts: o4('đều có lục lạp ở trong tế bào', 'đều tự tạo được chất hữu cơ', 'đều có tế bào nhân thực', 'đều có rễ, thân và lá thật'), ans: 'C', why: 'Cả nấm và thực vật đều có tế bào nhân thực. Còn lục lạp, khả năng tự dưỡng và các cơ quan rễ – thân – lá thì chỉ thực vật mới có.' },
    { sec: 'Nấm sợi', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Cơ thể nấm sợi (nấm mốc) được cấu tạo từ:', opts: o4('nhiều sợi nấm đan xen vào nhau', 'một tế bào duy nhất hình trứng', 'nhiều lá nhỏ xếp thành từng tầng', 'các mạch dẫn nối từ gốc lên ngọn'), ans: 'A', why: 'Nấm sợi là nấm đa bào, cơ thể gồm nhiều sợi nấm đan xen tạo thành hệ sợi. Phương án B là mô tả nấm men.' },
    { sec: 'Ứng dụng thực tế', lvl: 'NC', name: 'Câu 30', pts: 1, text: 'Vì sao khi ủ phân chuồng, người ta thường đậy kín và giữ cho đống phân luôn ẩm?', opts: o4('để ánh sáng mặt trời chiếu vào làm phân nhanh hoai mục hơn', 'để giữ ấm và ẩm cho vi khuẩn, nấm phân hủy chất hữu cơ nhanh', 'để ngăn không cho bất kì vi sinh vật nào xâm nhập vào đống phân', 'để nước mưa chảy vào đống phân làm tăng thêm lượng chất khoáng'), ans: 'B', why: 'Phân hoai mục được là nhờ vi khuẩn và nấm phân hủy chất hữu cơ. Muốn chúng hoạt động mạnh phải có đủ ấm và ẩm, nên người ta đậy kín để giữ nhiệt, giữ ẩm. Bẫy ở phương án C: đậy kín không phải để ngăn vi sinh vật — ngược lại, chính vi sinh vật mới là thứ làm phân hoai.' },
  ],
},

/* ═══════════ ĐỀ 14 — THỰC VẬT ═══════════ */
{
  id: 10664, title: 'Đề 14 · Thực vật: rêu, dương xỉ, hạt trần, hạt kín', time: 60,
  questions: [
    { sec: 'Các nhóm thực vật', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Giới Thực vật được chia thành các nhóm chính nào?', opts: o4('Rêu, Dương xỉ, Hạt trần, Hạt kín', 'Rêu, Tảo, Nấm, Hạt kín', 'Tảo, Dương xỉ, Nấm, Hạt trần', 'Rêu, Vi khuẩn, Hạt trần, Hạt kín'), ans: 'A', why: 'Thực vật gồm bốn nhóm: Rêu, Dương xỉ, Hạt trần và Hạt kín. Nấm và vi khuẩn thuộc giới khác, không phải thực vật.' },
    { sec: 'Cây rêu', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Cây rêu KHÔNG có đặc điểm nào sau đây?', opts: o4('thân và lá nhỏ, chưa phân hóa rõ ràng', 'sống ở nơi ẩm ướt và ít ánh nắng', 'có mạch dẫn và có rễ thật', 'sinh sản bằng bào tử trong túi bào tử'), ans: 'C', why: 'Rêu chưa có mạch dẫn và chỉ có rễ giả. Đây chính là lí do rêu không thể cao lớn và phải sống ở nơi ẩm ướt.' },
    { sec: 'Cây dương xỉ', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Cây dương xỉ sinh sản bằng:', opts: o4('hạt nằm trong quả', 'bào tử ở mặt dưới lá', 'hạt nằm trên lá noãn', 'hoa mọc ở đầu cành'), ans: 'B', why: 'Dương xỉ sinh sản bằng bào tử nằm trong các túi bào tử tập trung thành đốm ở mặt dưới lá già.' },
    { sec: 'Cây rêu', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Vì sao cây rêu chỉ sống được ở những nơi ẩm ướt?', opts: o4('vì rêu cần rất nhiều ánh nắng gay gắt mới sống được', 'vì rêu có bộ rễ thật rất dài nên hút được nhiều nước', 'vì rêu chỉ sinh sản được khi nhiệt độ môi trường rất cao', 'vì rêu chưa có mạch dẫn và rễ thật, hút nước qua bề mặt'), ans: 'D', why: 'Không có mạch dẫn nghĩa là rêu không vận chuyển được nước từ dưới lên trên, còn rễ giả thì không hút nước được. Rêu phải thấm nước trực tiếp qua bề mặt cơ thể nên chỉ sống được nơi luôn ẩm. Bẫy ở phương án B: rêu chỉ có rễ giả bám giữ chứ chưa có rễ thật.' },
    { sec: 'Hạt kín – Hạt trần', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Đặc điểm để phân biệt cây Hạt kín với cây Hạt trần là:', opts: o4('Hạt kín có hoa và hạt nằm trong quả', 'Hạt kín có mạch dẫn còn Hạt trần thì không', 'Hạt kín sinh sản bằng bào tử, Hạt trần bằng hạt', 'Hạt kín có rễ thật còn Hạt trần chỉ có rễ giả'), ans: 'A', why: 'Cả hai nhóm đều có mạch dẫn, rễ thật và đều sinh sản bằng hạt. Khác biệt là Hạt kín có hoa, hạt được quả bao bọc, còn Hạt trần chưa có hoa và quả, hạt nằm lộ trên lá noãn.' },
    { sec: 'Cây Hạt trần', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Cây thông được xếp vào nhóm Hạt trần vì:', opts: o4('thân cây thông rất to và sống được rất nhiều năm', 'hạt của thông nằm lộ trên lá noãn, chưa có quả bao bọc', 'lá thông có hình kim nên nước khó đọng lại ở trên lá', 'thông chỉ sống được ở vùng núi cao và khí hậu mát mẻ'), ans: 'B', why: 'Tên gọi "Hạt trần" xuất phát từ chính đặc điểm hạt nằm lộ ra trên lá noãn, không có quả bao bọc. Cái mà nhiều người quen gọi là "quả thông" thực ra là nón, không phải quả thật. Bẫy ở phương án C: hình dạng lá chỉ là đặc điểm thích nghi, không dùng để phân nhóm.' },
    { sec: 'Đa dạng thực vật', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Nhóm thực vật nào đa dạng và phong phú nhất hiện nay?', opts: o4('nhóm Rêu', 'nhóm Dương xỉ', 'nhóm Hạt kín', 'nhóm Hạt trần'), ans: 'C', why: 'Hạt kín là nhóm tiến hóa nhất và đa dạng nhất, chiếm phần lớn số loài thực vật trên Trái Đất.' },
    { sec: 'Cây dương xỉ', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Lá non của cây dương xỉ có đặc điểm nào dễ nhận ra?', opts: o4('có màu đỏ tươi và rất dày', 'mọc thành từng đôi đối nhau', 'có hình kim nhỏ như lá thông', 'cuộn tròn lại ở phần đầu lá'), ans: 'D', why: 'Lá non dương xỉ cuộn tròn ở đầu như đầu cần câu, sau đó mới duỗi dần ra. Đây là dấu hiệu nhận biết dương xỉ ngoài thiên nhiên.' },
    { sec: 'Vai trò của thực vật', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Trên một quả đồi trọc, người ta trồng rừng để chống xói mòn đất. Tác dụng chính của rừng ở đây là:', opts: o4('làm cho đất trên đồi nóng lên nhanh hơn', 'tán lá cản mưa, rễ cây giữ chặt đất lại', 'giúp nước mưa chảy nhanh xuống chân đồi', 'làm giảm lượng nước ngầm chứa trong đất'), ans: 'B', why: 'Tán lá làm giảm lực của hạt mưa rơi xuống mặt đất, còn hệ rễ chằng chịt giữ các hạt đất lại, nhờ đó hạn chế xói mòn và sạt lở.' },
    { sec: 'Vai trò của thực vật', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Vì sao nói thực vật có vai trò điều hòa khí hậu?', opts: o4('vì cây thoát hơi nước, che bóng mát và nhả khí oxygen', 'vì cây hút hết toàn bộ hơi nước có ở trong không khí', 'vì cây làm cho gió thổi mạnh hơn ở khắp mọi nơi', 'vì cây giữ lại toàn bộ nhiệt của Mặt Trời chiếu xuống'), ans: 'A', why: 'Cây thoát hơi nước làm tăng độ ẩm, tán lá che bớt nắng làm giảm nhiệt độ, đồng thời cây nhả khí oxygen và giữ lại bụi. Nhờ ba tác động cộng lại mà nơi nhiều cây xanh luôn mát và trong lành hơn. Bẫy ở phương án B: cây thải hơi nước ra không khí chứ không hút hơi nước vào.' },
    { sec: 'Cơ quan sinh sản', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Cơ quan sinh sản của cây Hạt kín là:', opts: o4('rễ và thân cây', 'lá và cành cây', 'hoa, quả và hạt', 'túi chứa bào tử'), ans: 'C', why: 'Ở cây Hạt kín, hoa là cơ quan sinh sản, sau đó tạo thành quả chứa hạt. Rễ, thân, lá là cơ quan sinh dưỡng.' },
    { sec: 'Nhận biết Hạt kín', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Nhóm cây nào sau đây đều thuộc nhóm Hạt kín?', opts: o4('cây thông, rêu, dương xỉ', 'cây thông, vạn tuế, bưởi', 'rêu, dương xỉ, cây lúa', 'cây lúa, bưởi, hoa hồng'), ans: 'D', why: 'Lúa, bưởi và hoa hồng đều có hoa, quả, hạt nằm trong quả nên thuộc Hạt kín. Thông và vạn tuế là Hạt trần; rêu và dương xỉ sinh sản bằng bào tử.' },
    { sec: 'Nhận dạng nhóm cây', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Một cây có mạch dẫn, sinh sản bằng bào tử, lá non cuộn tròn ở đầu. Cây đó thuộc nhóm:', opts: o4('nhóm Rêu', 'nhóm Dương xỉ', 'nhóm Hạt trần', 'nhóm Hạt kín'), ans: 'B', why: 'Phải nối ba dữ kiện: "có mạch dẫn" ⇒ loại Rêu; "sinh sản bằng bào tử" ⇒ loại Hạt trần và Hạt kín vì hai nhóm này sinh sản bằng hạt; "lá non cuộn tròn" khẳng định đúng đặc điểm của dương xỉ. Bẫy ở phương án A: nhiều bạn thấy chữ "bào tử" là chọn ngay Rêu mà quên dữ kiện mạch dẫn.' },
    { sec: 'Mạch dẫn', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Mạch dẫn trong thân cây có chức năng:', opts: o4('giữ cho thân cây luôn đứng thẳng', 'tạo ra chất hữu cơ để nuôi cây', 'vận chuyển nước và các chất trong cây', 'bảo vệ cây khỏi các loài sâu bệnh hại'), ans: 'C', why: 'Mạch dẫn vận chuyển nước, muối khoáng từ rễ lên lá và chất hữu cơ từ lá đi nuôi các bộ phận khác của cây.' },
    { sec: 'So sánh rêu – dương xỉ', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Cây rêu khác cây dương xỉ ở điểm nào?', opts: o4('rêu chưa có mạch dẫn, dương xỉ đã có mạch dẫn', 'rêu sinh sản bằng hạt, dương xỉ sinh sản bằng bào tử', 'rêu sống ở nơi khô hạn, dương xỉ sống ở dưới nước', 'rêu có hoa và quả, còn dương xỉ thì chưa có hoa'), ans: 'A', why: 'Cả hai đều sinh sản bằng bào tử và đều không có hoa, quả. Khác biệt cơ bản là dương xỉ đã có mạch dẫn và rễ thật nên cao lớn hơn rêu nhiều.' },
    { sec: 'Thích nghi của rêu', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Vì sao ở những vùng đất trống, rêu thường xuất hiện sớm hơn các loài cây khác?', opts: o4('vì rêu có bộ rễ rất khỏe nên bám chặt được vào đá cứng', 'vì rêu cần rất nhiều chất dinh dưỡng mới sống sót được', 'vì rêu có thân gỗ to nên chịu được gió mạnh ở vùng trống', 'vì rêu nhỏ, cần ít chất dinh dưỡng, sống được nơi đất nghèo'), ans: 'D', why: 'Rêu có cơ thể nhỏ, nhu cầu dinh dưỡng thấp nên sống được ở nơi đất nghèo, thậm chí trên mặt đá ẩm. Khi rêu chết đi, xác rêu phân hủy làm đất giàu chất hữu cơ hơn, tạo điều kiện cho cây khác mọc sau. Bẫy ở phương án A: rêu chỉ có rễ giả, không hề có rễ khỏe.' },
    { sec: 'Bảo vệ rừng', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Nếu chặt phá rừng đầu nguồn thì hậu quả trực tiếp là:', opts: o4('lượng nước ngầm trong lòng đất tăng lên rất nhanh', 'đất bị xói mòn, lũ quét và sạt lở xảy ra nhiều hơn', 'không khí trong vùng trở nên trong lành và mát hơn', 'các loài động vật rừng sẽ sinh sản nhanh hơn trước'), ans: 'B', why: 'Mất rừng đầu nguồn thì không còn tán lá cản mưa và rễ giữ đất, nước mưa chảy tràn rất nhanh xuống hạ lưu kéo theo đất đá, gây xói mòn, lũ quét và sạt lở. Bẫy ở phương án A: mất rừng làm nước không kịp thấm xuống đất nên nước ngầm giảm chứ không tăng.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'Nhà bạn Mai trồng rau trong thùng xốp trên sân thượng. Mùa hè nắng gắt, rau bị héo vào buổi trưa. Cách xử lí hợp lí nhất là:', opts: o4('tưới thật nhiều nước vào đúng lúc trời nắng gắt', 'nhổ bỏ toàn bộ rau rồi gieo lại vào mùa mưa tới', 'che lưới bớt nắng, tưới nước vào sáng sớm và chiều mát', 'phủ kín thùng xốp bằng tấm nylon dày cho đỡ nắng'), ans: 'C', why: 'Rau héo vì mất nước qua lá nhanh hơn lượng rễ hút vào. Che bớt nắng làm giảm thoát hơi nước, tưới lúc sáng sớm và chiều mát giúp nước ngấm sâu, ít bay hơi. Tưới giữa trưa nắng gắt dễ làm cây sốc nhiệt, còn phủ kín nylon thì cây thiếu ánh sáng và bí hơi.' },
    { sec: 'Vai trò của thực vật', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Vai trò nào sau đây KHÔNG phải của thực vật?', opts: o4('phân hủy xác sinh vật thành chất khoáng', 'cung cấp lương thực, thực phẩm cho người', 'cung cấp gỗ, dược liệu và nguyên liệu', 'làm nơi ở và nguồn thức ăn cho động vật'), ans: 'A', why: 'Phân hủy xác sinh vật là vai trò của vi khuẩn và nấm. Thực vật tạo ra chất hữu cơ chứ không phân hủy chúng.' },
    { sec: 'Nhận biết Hạt trần', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'Cây nào sau đây thuộc nhóm Hạt trần?', opts: o4('cây ngô', 'cây thông', 'cây rêu', 'cây ổi'), ans: 'B', why: 'Thông là cây Hạt trần điển hình: có mạch dẫn, sinh sản bằng hạt nhưng chưa có hoa và quả. Ngô và ổi là Hạt kín.' },
    { sec: 'Nhận dạng nhóm cây', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Trong vườn, em thấy một cây có quả, bổ quả ra thấy hạt nằm bên trong. Có thể khẳng định chắc chắn cây đó:', opts: o4('thuộc nhóm Hạt trần vì có hạt ở bên trong', 'thuộc nhóm Dương xỉ vì có túi chứa bào tử', 'thuộc nhóm Rêu vì cây mọc ở nơi ẩm ướt', 'thuộc nhóm Hạt kín vì hạt được quả bao bọc'), ans: 'D', why: 'Đặc điểm "hạt nằm trong quả" là dấu hiệu riêng của nhóm Hạt kín. Bẫy ở phương án A: Hạt trần cũng có hạt nhưng hạt nằm lộ trên lá noãn, không có quả thật bao bọc — vì vậy có quả là đủ để loại Hạt trần.' },
    { sec: 'Chống xói mòn', lvl: 'TH', name: 'Câu 22', pts: 1, text: 'Thực vật giúp giữ đất, chống xói mòn chủ yếu nhờ:', opts: o4('hệ rễ giữ đất và tán lá cản bớt nước mưa', 'thân cây to và cứng chắn được dòng nước lũ', 'hoa và quả rụng xuống che phủ kín mặt đất', 'hạt nảy mầm làm cho đất trở nên tơi xốp hơn'), ans: 'A', why: 'Rễ đan chằng chịt giữ các hạt đất, tán lá làm yếu lực của hạt mưa. Đó là hai tác dụng chính giúp chống xói mòn.' },
    { sec: 'Nơi sống của rêu', lvl: 'NB', name: 'Câu 23', pts: 1, text: 'Cây rêu thường mọc ở đâu?', opts: o4('trên cát khô giữa sa mạc', 'giữa mặt hồ nước rất sâu', 'chân tường, bờ đá ẩm ướt', 'trên mặt kim loại khô ráo'), ans: 'C', why: 'Rêu mọc thành đám ở nơi ẩm và ít nắng như chân tường, bờ đá, gốc cây trong vườn.' },
    { sec: 'Thích nghi của Hạt kín', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Vì sao cây Hạt kín thích nghi được với nhiều môi trường sống hơn cây Rêu?', opts: o4('vì cây Hạt kín luôn có kích thước lớn hơn cây rêu rất nhiều', 'vì cây Hạt kín có rễ thật, mạch dẫn và hạt được quả bảo vệ', 'vì cây Hạt kín sinh sản bằng bào tử nên phát tán đi được rất xa', 'vì cây Hạt kín không cần đến nước để sống và phát triển'), ans: 'B', why: 'Rễ thật hút được nước ở sâu, mạch dẫn đưa nước lên cao nên cây không phụ thuộc vào độ ẩm bề mặt; hạt nằm trong quả được bảo vệ và dự trữ chất dinh dưỡng nên nảy mầm được ở nhiều nơi. Bẫy ở phương án C: Hạt kín sinh sản bằng hạt chứ không bằng bào tử.' },
    { sec: 'Cơ quan sinh dưỡng', lvl: 'TH', name: 'Câu 25', pts: 1, text: 'Bộ phận nào của cây làm nhiệm vụ hút nước và muối khoáng?', opts: o4('lá của cây', 'hoa của cây', 'thân của cây', 'rễ của cây'), ans: 'D', why: 'Rễ hút nước và muối khoáng hòa tan từ đất, rồi mạch dẫn trong thân đưa lên các bộ phận phía trên.' },
    { sec: 'Vai trò của thực vật', lvl: 'NB', name: 'Câu 26', pts: 1, text: 'Thực vật cung cấp khí nào cho hoạt động hô hấp của người và động vật?', opts: o4('khí nitrogen', 'khí carbon dioxide', 'khí oxygen', 'hơi nước'), ans: 'C', why: 'Cây xanh nhả ra khí oxygen — loại khí mà người và động vật cần để hô hấp.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 27', pts: 1, text: 'Người ta thường trồng cây xanh dọc hai bên đường phố. Lợi ích rõ nhất của việc này là:', opts: o4('che bóng mát, giảm bụi, làm không khí trong lành hơn', 'làm cho mặt đường nhanh nóng lên vào buổi trưa hè', 'làm cho các phương tiện giao thông chạy nhanh hơn', 'làm tăng lượng khí carbon dioxide ở khu vực đường phố'), ans: 'A', why: 'Hàng cây tạo bóng mát làm giảm nhiệt độ mặt đường, lá cây giữ bụi và cây nhả khí oxygen nên không khí trong lành hơn.' },
    { sec: 'Sắp xếp nhóm thực vật', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Ba mẫu cây thu được: mẫu 1 không có mạch dẫn; mẫu 2 có mạch dẫn và sinh sản bằng bào tử; mẫu 3 có hoa và quả. Thứ tự từ đơn giản đến phức tạp là:', opts: o4('mẫu 2 → mẫu 1 → mẫu 3', 'mẫu 1 → mẫu 2 → mẫu 3', 'mẫu 3 → mẫu 2 → mẫu 1', 'mẫu 1 → mẫu 3 → mẫu 2'), ans: 'B', why: 'Mẫu 1 chưa có mạch dẫn nên đơn giản nhất (nhóm Rêu). Mẫu 2 đã có mạch dẫn nhưng vẫn sinh sản bằng bào tử (nhóm Dương xỉ). Mẫu 3 có hoa và quả nên phức tạp nhất (nhóm Hạt kín). Bẫy ở phương án C: đây chính là thứ tự ngược lại, từ phức tạp về đơn giản.' },
    { sec: 'Nhận biết cây có hoa', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Cây nào sau đây KHÔNG có hoa?', opts: o4('cây cam', 'cây lúa', 'cây bưởi', 'cây dương xỉ'), ans: 'D', why: 'Dương xỉ sinh sản bằng bào tử nên không có hoa. Cam, lúa, bưởi đều là cây Hạt kín nên đều có hoa, dù hoa lúa nhỏ và khó thấy.' },
    { sec: 'Cấu tạo cây Hạt kín', lvl: 'NB', name: 'Câu 30', pts: 1, text: 'Ở cây Hạt kín, bộ phận nào chứa hạt?', opts: o4('quả', 'lá', 'rễ', 'thân'), ans: 'A', why: 'Sau khi hoa tàn, bầu nhụy phát triển thành quả và hạt nằm bên trong quả — đó là đặc điểm đặc trưng của Hạt kín.' },
  ],
},

/* ═══════════ ĐỀ 15 — ĐỘNG VẬT KHÔNG XƯƠNG SỐNG ═══════════ */
{
  id: 10665, title: 'Đề 15 · Động vật không xương sống', time: 60,
  questions: [
    { sec: 'Đặc điểm chung', lvl: 'NC', name: 'Câu 1', pts: 1, text: 'Vì sao động vật không xương sống rất đa dạng nhưng cơ thể thường có kích thước nhỏ?', opts: o4('vì chúng chỉ sống được ở dưới nước nên không thể lớn lên', 'vì tất cả chúng đều sống kí sinh trong cơ thể của loài khác', 'vì không có bộ xương trong nên cơ thể khó nâng đỡ khi quá lớn', 'vì chúng sinh sản rất nhanh nên không kịp lớn về kích thước'), ans: 'C', why: 'Bộ xương trong là khung nâng đỡ cho cơ thể lớn. Thiếu khung này, cơ thể càng to càng khó giữ hình dạng và khó di chuyển, nên động vật không xương sống thường nhỏ. Bẫy ở phương án A: rất nhiều loài như châu chấu, nhện, ốc sên sống hoàn toàn trên cạn.' },
    { sec: 'Khái niệm', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Động vật không xương sống là những động vật:', opts: o4('không có bất kì bộ phận nâng đỡ nào', 'không có xương sống ở dọc lưng', 'không có hệ tiêu hóa trong cơ thể', 'không di chuyển được trong đời sống'), ans: 'B', why: 'Dấu hiệu duy nhất để phân biệt là không có xương sống chạy dọc lưng. Nhiều loài vẫn có bộ phận nâng đỡ, ví dụ vỏ đá vôi của ốc hay bộ xương ngoài của tôm.' },
    { sec: 'Ngành Chân khớp', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Nhóm nào sau đây gồm toàn động vật thuộc ngành Chân khớp?', opts: o4('trai sông, ốc sên, con mực', 'giun đất, con đỉa, sán lá gan', 'thủy tức, con sứa, san hô', 'tôm sông, nhện nhà, châu chấu'), ans: 'D', why: 'Tôm, nhện và châu chấu đều có bộ xương ngoài bằng chitin và chân phân đốt nên thuộc ngành Chân khớp. Các nhóm còn lại lần lượt là Thân mềm, Giun và Ruột khoang.' },
    { sec: 'Ngành Ruột khoang', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Thủy tức, sứa, san hô thuộc ngành nào?', opts: o4('Ruột khoang', 'Thân mềm', 'Chân khớp', 'Giun đốt'), ans: 'A', why: 'Đây là các đại diện của ngành Ruột khoang: cơ thể đối xứng tỏa tròn, có tua miệng để bắt mồi.' },
    { sec: 'Ngành Chân khớp', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Vì sao tôm và cua phải lột xác nhiều lần trong quá trình lớn lên?', opts: o4('vì lớp vỏ ngoài của chúng bị bẩn nên phải thay bằng lớp vỏ mới', 'vì lột xác giúp chúng thay đổi màu sắc để lẩn trốn được kẻ thù', 'vì lớp vỏ cứng bên ngoài không lớn lên cùng với cơ thể', 'vì lột xác giúp chúng bơi nhanh hơn khi gặp nguy hiểm'), ans: 'C', why: 'Bộ xương ngoài bằng chitin cứng và không giãn ra được. Cơ thể bên trong lớn dần nên đến lúc chật, con vật phải lột bỏ lớp vỏ cũ, lớn nhanh lúc vỏ mới còn mềm rồi mới cứng lại. Bẫy ở phương án A: lột xác là để lớn lên, không liên quan đến vỏ bẩn hay sạch.' },
    { sec: 'Ngành Chân khớp', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Đặc điểm chung của ngành Chân khớp là:', opts: o4('cơ thể mềm, không phân đốt, có vỏ đá vôi', 'cơ thể dẹp, sống kí sinh trong ruột vật chủ', 'cơ thể hình trụ, có nhiều tua miệng bắt mồi', 'có bộ xương ngoài bằng chitin, chân phân đốt'), ans: 'D', why: 'Tên "Chân khớp" bắt nguồn từ việc chân gồm nhiều đốt khớp với nhau; ngoài ra cơ thể còn được bọc bởi bộ xương ngoài bằng chitin.' },
    { sec: 'Giun kí sinh', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Giun đũa kí sinh ở bộ phận nào của người?', opts: o4('trong lá gan', 'trong ruột non', 'trong tim', 'trong phổi'), ans: 'B', why: 'Giun đũa sống trong ruột non và lấy chất dinh dưỡng của người, làm người bệnh gầy yếu, đau bụng.' },
    { sec: 'Phòng bệnh giun sán', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Để phòng bệnh giun sán, biện pháp nào sau đây quan trọng nhất?', opts: o4('ăn chín uống sôi, rửa tay sạch và tẩy giun định kì', 'chỉ ăn các loại rau sống đã ngâm nước muối loãng', 'uống thật nhiều nước lọc mỗi ngày để rửa sạch ruột', 'ăn nhiều thức ăn có vị cay để làm cho giun sán chết'), ans: 'A', why: 'Trứng giun sán vào cơ thể qua đường ăn uống, nên phải chặn ngay con đường đó bằng ăn chín uống sôi và rửa tay, kết hợp tẩy giun định kì để diệt giun đã có. Bẫy ở phương án B: ngâm nước muối loãng không diệt được trứng giun, chỉ rửa trôi bớt đất cát.' },
    { sec: 'Ngành Thân mềm', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Động vật nào sau đây thuộc ngành Thân mềm?', opts: o4('con giun đất', 'con châu chấu', 'con thủy tức', 'con ốc sên'), ans: 'D', why: 'Ốc sên có cơ thể mềm, không phân đốt và có vỏ đá vôi nên thuộc ngành Thân mềm.' },
    { sec: 'Vai trò giun đất', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Giun đất có lợi cho nhà nông vì:', opts: o4('giun đất ăn hết sâu bọ có hại cho cây trồng', 'giun đất hút nước từ đất rồi tưới cho cây', 'giun đất làm đất tơi xốp, thoáng khí và màu mỡ', 'giun đất tạo ra chất diệt cỏ dại quanh gốc cây'), ans: 'C', why: 'Giun đất đào hang làm đất tơi xốp và thoáng khí, phân giun lại giàu chất dinh dưỡng nên đất màu mỡ hơn, rễ cây phát triển tốt.' },
    { sec: 'Ngành Giun dẹp', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Sán lá gan thuộc ngành nào?', opts: o4('Giun tròn', 'Giun dẹp', 'Giun đốt', 'Thân mềm'), ans: 'B', why: 'Sán lá gan có cơ thể dẹp theo chiều lưng bụng, sống kí sinh nên thuộc ngành Giun dẹp.' },
    { sec: 'Ngành Ruột khoang', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Vì sao san hô được xếp vào giới Động vật dù nhìn giống một cành cây bằng đá?', opts: o4('vì san hô có tua miệng bắt mồi và không tự tạo chất hữu cơ', 'vì san hô có bộ xương đá vôi rất cứng nên chịu được sóng biển', 'vì san hô sống bám cố định thành tập đoàn ở dưới đáy biển', 'vì san hô có màu sắc sặc sỡ giống với nhiều loài cá biển'), ans: 'A', why: 'Tiêu chí để xếp vào giới Động vật là dị dưỡng (không tự tạo được chất hữu cơ) và có khả năng bắt mồi. San hô dùng tua miệng bắt các sinh vật nhỏ trong nước nên là động vật, dù sống cố định. Bẫy ở phương án C: sống bám cố định thường bị hiểu nhầm là đặc điểm của thực vật.' },
    { sec: 'Ngành Chân khớp', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Động vật nào sau đây KHÔNG thuộc ngành Chân khớp?', opts: o4('con nhện', 'con tôm', 'con ong', 'con mực'), ans: 'D', why: 'Mực thuộc ngành Thân mềm: cơ thể mềm, không phân đốt, chân biến thành các tua. Nhện, tôm, ong đều là Chân khớp.' },
    { sec: 'Ngành Thân mềm', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Cơ thể động vật ngành Thân mềm có đặc điểm:', opts: o4('phân đốt rõ ràng, có bộ xương ngoài cứng', 'mềm, không phân đốt, thường có vỏ đá vôi', 'dẹp theo chiều lưng bụng, sống kí sinh', 'hình trụ tròn, có nhiều tua ở quanh miệng'), ans: 'B', why: 'Thân mềm có cơ thể mềm, không phân đốt, đa số có vỏ đá vôi bảo vệ như trai, ốc; riêng mực thì vỏ tiêu giảm nằm trong cơ thể.' },
    { sec: 'Vận dụng thực tế', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Vì sao ruộng lúa bị phun quá nhiều thuốc trừ sâu lại dễ mất mùa hơn về lâu dài?', opts: o4('vì thuốc trừ sâu làm cho hạt lúa nảy mầm ngay ở trên bông', 'vì thuốc trừ sâu làm cho đất ruộng trở nên tơi xốp quá mức', 'vì thuốc diệt cả thiên địch nên sâu hại bùng phát mạnh hơn', 'vì thuốc trừ sâu làm nước trong ruộng bay hơi nhanh hơn'), ans: 'C', why: 'Trên ruộng có nhiều loài ăn sâu hại như nhện, bọ rùa, ong kí sinh. Thuốc trừ sâu diệt cả sâu hại lẫn những loài này, mà thiên địch thường hồi phục chậm hơn sâu hại, nên các lứa sau sâu bùng phát mạnh và ruộng mất mùa. Bẫy ở phương án B: thuốc trừ sâu không làm đất tơi xốp, và đất tơi xốp cũng không gây mất mùa.' },
    { sec: 'Nhận dạng ngành', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Một động vật có cơ thể phân đốt, sống trong đất ẩm, không có chân, di chuyển bằng cách co duỗi cơ thể. Động vật đó thuộc ngành:', opts: o4('Giun đốt', 'Giun tròn', 'Thân mềm', 'Chân khớp'), ans: 'A', why: 'Cần nối các dữ kiện: "cơ thể phân đốt" loại ngay Thân mềm và Giun tròn (giun tròn có cơ thể hình trụ, không phân đốt); "không có chân" loại Chân khớp. Còn lại là ngành Giun đốt, đúng với đặc điểm của giun đất.' },
    { sec: 'Tác hại của động vật', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Muỗi, ruồi, gián là những động vật có hại vì chúng:', opts: o4('ăn hết lá của các loại cây trồng trong vườn', 'phá hoại đồ gỗ và tường nhà của con người', 'hút hết nước trong thức ăn làm thức ăn bị khô', 'truyền mầm bệnh và làm bẩn thức ăn của người'), ans: 'D', why: 'Muỗi truyền bệnh sốt rét và sốt xuất huyết; ruồi, gián bò trên rác rồi bò lên thức ăn làm lây mầm bệnh đường tiêu hóa.' },
    { sec: 'Đa dạng Chân khớp', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Ngành động vật không xương sống nào có số lượng loài lớn nhất?', opts: o4('ngành Thân mềm', 'ngành Chân khớp', 'ngành Ruột khoang', 'ngành Giun đốt'), ans: 'B', why: 'Chân khớp là ngành đa dạng nhất trong giới Động vật, riêng côn trùng đã chiếm phần lớn số loài động vật đã biết.' },
    { sec: 'Phòng bệnh', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'Để diệt bọ gậy (lăng quăng), phòng bệnh sốt xuất huyết, việc nên làm là:', opts: o4('đậy kín lu nước, thả cá và dọn vật chứa nước đọng', 'đổ thêm thật nhiều nước sạch vào các lu chứa nước', 'để các chậu cây cảnh có nước đọng ở quanh nhà', 'phun nước thơm quanh nhà cho muỗi bay đi nơi khác'), ans: 'A', why: 'Muỗi đẻ trứng ở nước đọng, trứng nở thành bọ gậy. Đậy kín lu, thả cá ăn bọ gậy và dọn hết vật chứa nước đọng là cách cắt vòng đời của muỗi ngay từ gốc.' },
    { sec: 'Ngành Ruột khoang', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Thủy tức bắt mồi bằng bộ phận nào?', opts: o4('bằng đôi càng khỏe', 'bằng chiếc vỏ đá vôi', 'bằng các tua miệng', 'bằng đôi cánh mỏng'), ans: 'C', why: 'Thủy tức dùng các tua miệng có tế bào gai để làm tê liệt con mồi rồi đưa vào miệng.' },
    { sec: 'Phòng bệnh giun sán', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Ở nhiều vùng nông thôn, trẻ em hay bị nhiễm giun. Nguyên nhân chủ yếu là:', opts: o4('do trẻ em uống quá nhiều nước lã đã được đun sôi kĩ', 'do ăn uống chưa hợp vệ sinh, trứng giun theo thức ăn vào ruột', 'do trẻ em chơi đùa ngoài nắng nên cơ thể bị mất nước nhiều', 'do trẻ em ăn quá nhiều chất đạm nên giun sinh sôi ở trong ruột'), ans: 'B', why: 'Trứng giun có trong đất, nước bẩn, rau sống rửa chưa kĩ. Trẻ hay chơi đất, mút tay, ăn quà vặt không rửa tay nên trứng giun dễ theo thức ăn vào ruột và nở thành giun. Bẫy ở phương án D: giun lấy chất dinh dưỡng của vật chủ chứ không "sinh sôi" nhờ chất đạm trong khẩu phần.' },
    { sec: 'Ngành Thân mềm', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Trai sông di chuyển được nhờ bộ phận nào?', opts: o4('nhờ đôi tua dài', 'nhờ nhiều chân đốt', 'nhờ các vây nhỏ', 'nhờ chân hình lưỡi rìu'), ans: 'D', why: 'Trai có chân hình lưỡi rìu thò ra khỏi vỏ, cắm xuống bùn rồi kéo cơ thể tiến lên rất chậm.' },
    { sec: 'Ngành Ruột khoang', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Nhóm nào sau đây đều là động vật thuộc ngành Ruột khoang?', opts: o4('con sứa, hải quỳ, san hô', 'con ốc, con trai, con mực', 'con tôm, con cua, con nhện', 'giun đất, con đỉa, sán lá'), ans: 'A', why: 'Sứa, hải quỳ và san hô đều có cơ thể đối xứng tỏa tròn và có tua miệng, thuộc ngành Ruột khoang.' },
    { sec: 'Vai trò của động vật', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Một bạn nói: "Mọi động vật không xương sống đều có hại cho con người." Nhận định này SAI vì:', opts: o4('vì mọi loài không xương sống đều chỉ sống ở dưới đáy biển sâu', 'vì các loài không xương sống đều không tiếp xúc với con người', 'vì nhiều loài có lợi: ong thụ phấn, giun làm tơi đất, tôm làm thức ăn', 'vì các loài không xương sống đều có kích thước quá nhỏ để gây hại'), ans: 'C', why: 'Chỉ một số loài gây hại như muỗi, ruồi, sâu hại, giun sán kí sinh. Rất nhiều loài có lợi: ong giúp hoa thụ phấn, giun đất làm tơi xốp đất, tôm cua là nguồn thực phẩm. Bẫy ở phương án D: nhỏ không có nghĩa là vô hại — muỗi rất nhỏ nhưng truyền nhiều bệnh nguy hiểm.' },
    { sec: 'Côn trùng', lvl: 'NB', name: 'Câu 25', pts: 1, text: 'Châu chấu có mấy đôi chân?', opts: o4('hai đôi chân', 'ba đôi chân', 'bốn đôi chân', 'năm đôi chân'), ans: 'B', why: 'Châu chấu là côn trùng nên có ba đôi chân, trong đó đôi chân sau rất khỏe để nhảy.' },
    { sec: 'Phân biệt nhện – côn trùng', lvl: 'TH', name: 'Câu 26', pts: 1, text: 'Đặc điểm nào giúp phân biệt nhện với côn trùng?', opts: o4('nhện có cánh còn côn trùng thì không có cánh', 'nhện có râu dài còn côn trùng thì không có râu', 'nhện sống trên cạn còn côn trùng sống dưới nước', 'nhện có bốn đôi chân, côn trùng có ba đôi chân'), ans: 'D', why: 'Nhện có bốn đôi chân và không có cánh, không có râu; còn côn trùng có ba đôi chân, thường có cánh và có râu.' },
    { sec: 'Vai trò của ong', lvl: 'VD', name: 'Câu 27', pts: 1, text: 'Ong mật có lợi cho vườn cây ăn quả chủ yếu vì ong:', opts: o4('ăn hết các loại sâu bọ phá hại lá cây trong vườn', 'làm cho đất ở quanh gốc cây trở nên tơi xốp hơn', 'giúp hoa thụ phấn nên cây đậu được nhiều quả hơn', 'hút bớt nước thừa ở trong thân cây vào mùa mưa'), ans: 'C', why: 'Khi ong bay từ hoa này sang hoa khác lấy mật, phấn hoa dính vào mình ong được mang theo, nhờ đó hoa được thụ phấn và cây đậu quả nhiều hơn.' },
    { sec: 'Nhận dạng ngành', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Bạn An quan sát một con vật: cơ thể chia ba phần, có ba đôi chân, hai đôi cánh và một đôi râu. Con vật đó là:', opts: o4('một loài côn trùng thuộc ngành Chân khớp', 'một loài thân mềm thuộc ngành Thân mềm', 'một loài giun thuộc ngành Giun đốt', 'một loài ruột khoang sống ở dưới nước'), ans: 'A', why: 'Ba đôi chân, cơ thể chia ba phần (đầu, ngực, bụng), có râu và cánh là bộ đặc điểm riêng của côn trùng — lớp lớn nhất trong ngành Chân khớp. Bẫy ở phương án B: thân mềm không có chân phân đốt và không có cánh.' },
    { sec: 'Ngành Giun tròn', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Động vật nào sau đây thuộc ngành Giun tròn?', opts: o4('giun đất', 'giun kim', 'sán lá gan', 'con đỉa'), ans: 'B', why: 'Giun kim có cơ thể hình trụ, không phân đốt nên thuộc ngành Giun tròn. Giun đất và đỉa thuộc Giun đốt, sán lá gan thuộc Giun dẹp.' },
    { sec: 'An toàn thực phẩm', lvl: 'TH', name: 'Câu 30', pts: 1, text: 'Vì sao không nên ăn gỏi cá sống và tiết canh?', opts: o4('vì các món đó có vị tanh, khó ăn với nhiều người', 'vì các món đó chứa quá nhiều muối khoáng cho cơ thể', 'vì các món đó làm cho cơ thể bị thiếu chất đường bột', 'vì có thể chứa trứng và ấu trùng giun sán gây bệnh'), ans: 'D', why: 'Thức ăn sống chưa qua nấu chín có thể mang trứng hoặc ấu trùng giun sán; vào cơ thể chúng phát triển thành giun sán kí sinh gây bệnh.' },
  ],
},

/* ═══════════ ĐỀ 16 — ĐỘNG VẬT CÓ XƯƠNG SỐNG ═══════════ */
{
  id: 10666, title: 'Đề 16 · Động vật có xương sống', time: 60,
  questions: [
    { sec: 'Các lớp động vật', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Động vật có xương sống gồm các lớp nào?', opts: o4('Cá, Lưỡng cư, Bò sát, Chân khớp, Thú', 'Cá, Lưỡng cư, Bò sát, Chim, Thú', 'Cá, Thân mềm, Bò sát, Chim, Thú', 'Giun đốt, Cá, Lưỡng cư, Chim, Thú'), ans: 'B', why: 'Động vật có xương sống gồm năm lớp: Cá, Lưỡng cư, Bò sát, Chim và Thú. Chân khớp, Thân mềm, Giun đốt đều là động vật không xương sống.' },
    { sec: 'Lớp Lưỡng cư', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Vì sao ếch đồng phải sống ở nơi ẩm ướt, gần bờ nước?', opts: o4('vì ếch chỉ ăn được các loài động vật sống ở dưới nước', 'vì ếch có mang nên bắt buộc phải thở ở trong nước', 'vì ếch có lớp vảy sừng cần được làm ướt thường xuyên', 'vì da ếch trần, luôn ẩm và tham gia vào việc trao đổi khí'), ans: 'D', why: 'Ngoài phổi, ếch còn trao đổi khí qua da; da phải luôn ẩm thì khí mới thấm qua được. Nếu da khô, ếch sẽ ngạt. Bẫy ở phương án B: ếch trưởng thành thở bằng phổi và da, chỉ giai đoạn nòng nọc mới thở bằng mang.' },
    { sec: 'Lớp Chim', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Đặc điểm nào sau đây có ở lớp Chim?', opts: o4('da trần và luôn ẩm ướt', 'da khô, phủ vảy sừng', 'có lông vũ và mỏ sừng', 'có lông mao và đẻ con'), ans: 'C', why: 'Chim có lông vũ bao phủ cơ thể và mỏ sừng không răng. Da trần ẩm là của lưỡng cư, vảy sừng là của bò sát, lông mao và đẻ con là của thú.' },
    { sec: 'Lớp Cá', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Cá hô hấp bằng bộ phận nào?', opts: o4('bằng mang', 'bằng phổi', 'bằng da', 'bằng vây'), ans: 'A', why: 'Cá lấy khí oxygen hòa tan trong nước nhờ mang. Vây chỉ dùng để di chuyển và giữ thăng bằng.' },
    { sec: 'Lớp Thú', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Vì sao thú mỏ vịt đẻ trứng nhưng vẫn được xếp vào lớp Thú?', opts: o4('vì thú mỏ vịt có mỏ dẹt giống với mỏ của loài vịt nhà', 'vì thú mỏ vịt có lông mao và nuôi con bằng sữa mẹ', 'vì thú mỏ vịt bơi rất giỏi và sống ở gần các bờ sông', 'vì thú mỏ vịt có kích thước cơ thể lớn hơn loài chim'), ans: 'B', why: 'Dấu hiệu quyết định của lớp Thú là có lông mao và nuôi con bằng sữa, chứ không phải đẻ con. Thú mỏ vịt đẻ trứng nhưng vẫn có đủ hai dấu hiệu trên nên thuộc lớp Thú. Bẫy ở phương án A: hình dạng cái mỏ chỉ là vẻ ngoài, không dùng để phân lớp.' },
    { sec: 'Lớp Chim', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Đặc điểm nào giúp chim thích nghi với đời sống bay lượn?', opts: o4('da khô có phủ vảy sừng và có chiếc đuôi rất dài', 'chi trước biến thành vây bơi, thân dẹp sang hai bên', 'thân hình thoi, chi trước biến thành cánh, lông vũ nhẹ', 'cơ thể có lông mao rất dày và có bốn chân khỏe'), ans: 'C', why: 'Ba đặc điểm cùng phối hợp: thân hình thoi giảm sức cản không khí, chi trước biến thành cánh tạo lực nâng, lông vũ nhẹ và xốp làm cơ thể nhẹ đi. Bẫy ở phương án D: lông mao và bốn chân khỏe là đặc điểm của thú chạy trên cạn.' },
    { sec: 'Lớp Lưỡng cư', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'Động vật nào sau đây thuộc lớp Lưỡng cư?', opts: o4('cá chép', 'thằn lằn', 'chim sẻ', 'ếch đồng'), ans: 'D', why: 'Ếch đồng có da trần luôn ẩm, sống vừa ở nước vừa ở cạn nên thuộc lớp Lưỡng cư. Thằn lằn là bò sát.' },
    { sec: 'Lớp Thú', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Lớp Thú có đặc điểm đặc trưng nào?', opts: o4('có lông mao, đẻ con và nuôi con bằng sữa', 'có lông vũ, đẻ trứng có vỏ đá vôi cứng', 'có da khô phủ vảy sừng, đẻ trứng vỏ dai', 'có da trần ẩm ướt, đẻ trứng ở trong nước'), ans: 'A', why: 'Lông mao và tuyến sữa nuôi con là hai đặc điểm riêng của lớp Thú, không lớp nào khác có.' },
    { sec: 'Vai trò động vật', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Người nông dân thường bảo vệ rắn và chim cú mèo ở đồng ruộng vì chúng:', opts: o4('giúp làm cho đất ruộng trở nên tơi xốp hơn', 'giúp cây lúa thụ phấn nên cho nhiều hạt hơn', 'ăn chuột, giúp hạn chế chuột phá hoại mùa màng', 'ăn hết cỏ dại mọc xen lẫn giữa các gốc lúa'), ans: 'C', why: 'Rắn và cú mèo là thiên địch của chuột. Giữ được chúng thì số lượng chuột giảm, lúa ít bị cắn phá nên nông dân đỡ phải dùng thuốc diệt chuột.' },
    { sec: 'So sánh bò sát – lưỡng cư', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Bò sát khác lưỡng cư ở đặc điểm nào?', opts: o4('bò sát sống được ở dưới nước, lưỡng cư thì không', 'bò sát có da khô phủ vảy sừng, lưỡng cư có da trần', 'bò sát đẻ con, còn lưỡng cư đẻ trứng ở dưới nước', 'bò sát có lông mao, còn lưỡng cư có lông vũ mềm'), ans: 'B', why: 'Da khô phủ vảy sừng giúp bò sát chống mất nước nên sống được ở nơi khô hạn, còn lưỡng cư có da trần luôn ẩm nên phải ở gần nước. Phần lớn bò sát cũng đẻ trứng chứ không đẻ con.' },
    { sec: 'Vòng đời của ếch', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Vì sao nòng nọc sống được dưới nước còn ếch trưởng thành sống được trên cạn?', opts: o4('vì nòng nọc thở bằng mang, ếch trưởng thành thở bằng phổi và da', 'vì nòng nọc có bốn chân khỏe, ếch trưởng thành lại không có chân', 'vì nòng nọc có vảy sừng, còn ếch trưởng thành thì có lông mao', 'vì nòng nọc ăn thịt động vật, còn ếch trưởng thành chỉ ăn thực vật'), ans: 'A', why: 'Nòng nọc có mang và đuôi bơi nên chỉ sống được trong nước. Khi biến đổi thành ếch, mang tiêu biến, phổi hình thành, chi phát triển nên ếch lên cạn được nhưng vẫn phải ở nơi ẩm vì còn thở qua da. Bẫy ở phương án B: chính nòng nọc mới là giai đoạn chưa có chân.' },
    { sec: 'Lớp Bò sát', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Động vật nào sau đây thuộc lớp Bò sát?', opts: o4('cá voi xanh', 'chim bồ câu', 'con ếch cây', 'rắn hổ mang'), ans: 'D', why: 'Rắn hổ mang có da khô phủ vảy sừng, đẻ trứng vỏ dai nên thuộc lớp Bò sát. Cá voi là thú, ếch cây là lưỡng cư.' },
    { sec: 'Lớp Thú', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Cá voi được xếp vào lớp Thú vì:', opts: o4('cá voi sống hoàn toàn ở trong môi trường nước', 'cá voi có vây bơi và có thân hình rất thon dài', 'cá voi thở bằng phổi và nuôi con bằng sữa mẹ', 'cá voi có kích thước cơ thể lớn hơn mọi loài cá'), ans: 'C', why: 'Dù sống dưới nước và có tên gọi là "cá", cá voi vẫn thở bằng phổi, đẻ con và nuôi con bằng sữa nên thuộc lớp Thú. Môi trường sống và hình dáng không quyết định việc phân lớp.' },
    { sec: 'Nhận dạng lớp', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Một động vật có da khô phủ vảy sừng, đẻ trứng có vỏ dai và thở bằng phổi. Động vật đó thuộc lớp:', opts: o4('lớp Cá', 'lớp Bò sát', 'lớp Chim', 'lớp Lưỡng cư'), ans: 'B', why: 'Ba dữ kiện phải khớp cùng lúc: "da khô phủ vảy sừng" loại Cá và Lưỡng cư; "trứng vỏ dai" loại Chim vì trứng chim có vỏ đá vôi cứng. Kết quả chỉ còn lớp Bò sát.' },
    { sec: 'Lớp Chim', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Trứng của chim có đặc điểm:', opts: o4('có vỏ đá vôi cứng bao bọc bên ngoài', 'có lớp màng mỏng trong suốt bao quanh', 'được đẻ thành từng đám ở dưới nước', 'có vỏ dai và thường được vùi trong cát'), ans: 'A', why: 'Trứng chim có vỏ đá vôi cứng bảo vệ phôi. Trứng bò sát có vỏ dai, còn trứng ếch chỉ có lớp màng và được đẻ thành đám trong nước.' },
    { sec: 'Nhận dạng nhóm', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Nhóm nào sau đây đều là động vật có xương sống?', opts: o4('con tôm, con cua, cá chép, con ếch', 'con mực, ốc sên, con rắn, chim sẻ', 'giun đất, cá rô, con thằn lằn', 'cá chép, con ếch, con rắn, con mèo'), ans: 'D', why: 'Cá chép (Cá), ếch (Lưỡng cư), rắn (Bò sát), mèo (Thú) đều có xương sống. Các nhóm còn lại đều lẫn động vật không xương sống như tôm, cua, mực, ốc sên, giun đất.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 17', pts: 1, text: 'Muốn nuôi cá cảnh trong bể được khỏe mạnh, việc cần làm là:', opts: o4('đậy kín nắp bể và không thay nước trong nhiều tháng', 'đổ thật nhiều thức ăn để cá ăn dần trong suốt cả tuần', 'thay nước định kì và sục khí để cung cấp oxygen', 'đặt bể ở nơi nắng gắt cả ngày cho nước luôn được ấm'), ans: 'C', why: 'Cá lấy oxygen hòa tan trong nước nhờ mang, nên nước phải sạch và đủ oxygen. Thức ăn thừa phân hủy làm bẩn nước và tiêu tốn oxygen, còn nắng gắt cả ngày làm nước nóng lên, cá dễ chết.' },
    { sec: 'Bảo vệ động vật', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'Vì sao số lượng của nhiều loài động vật hoang dã đang giảm mạnh?', opts: o4('do bị săn bắt quá mức và môi trường sống bị thu hẹp', 'do các loài đó tự nhiên mất đi khả năng sinh sản', 'do khí hậu Trái Đất ngày càng trở nên mát mẻ hơn', 'do rừng tự nhiên ngày càng được mở rộng thêm ra'), ans: 'A', why: 'Hai nguyên nhân chính cùng tác động: con người săn bắt để lấy thịt, da, sừng và phá rừng, lấp đầm lầy khiến nơi sống của chúng bị thu hẹp. Bẫy ở phương án D: rừng đang bị thu hẹp chứ không mở rộng, đó mới là nguyên nhân gây suy giảm.' },
    { sec: 'Lớp Cá', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Động vật nào sau đây thuộc lớp Cá?', opts: o4('cá voi', 'cá chép', 'cá sấu', 'cá heo'), ans: 'B', why: 'Chỉ cá chép mới thở bằng mang nên thuộc lớp Cá. Cá voi và cá heo là thú, cá sấu là bò sát — cả ba đều thở bằng phổi dù trong tên gọi có chữ "cá".' },
    { sec: 'Lớp Cá', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Đặc điểm nào KHÔNG phải của lớp Cá?', opts: o4('di chuyển ở trong nước nhờ các vây', 'hô hấp bằng mang khi sống dưới nước', 'thân phủ vảy và có chất nhờn trơn', 'đẻ con và nuôi con bằng sữa mẹ'), ans: 'D', why: 'Đẻ con và nuôi con bằng sữa là đặc điểm của lớp Thú. Cá đẻ trứng và thụ tinh ngoài trong nước.' },
    { sec: 'Chăn nuôi', lvl: 'NC', name: 'Câu 21', pts: 1, text: 'Vì sao khi nuôi gà, người ta cần giữ chuồng khô ráo và ấm về mùa đông?', opts: o4('vì gà con chịu lạnh kém, chuồng ẩm lạnh dễ làm gà mắc bệnh', 'vì chuồng ấm sẽ giúp cho gà thay toàn bộ lông vũ nhanh hơn', 'vì chuồng khô ráo làm cho trứng gà có vỏ dai và bền hơn', 'vì chuồng ấm làm cho gà không cần ăn thức ăn hằng ngày'), ans: 'A', why: 'Gà con chưa đủ lông nên khả năng giữ ấm kém; chuồng ẩm và lạnh vừa làm gà mất nhiệt vừa tạo điều kiện cho vi khuẩn, nấm mốc phát triển nên gà dễ mắc bệnh và chết. Bẫy ở phương án C: vỏ trứng gà là vỏ đá vôi cứng, không phải vỏ dai như trứng bò sát.' },
    { sec: 'Lớp Lưỡng cư', lvl: 'NB', name: 'Câu 22', pts: 1, text: 'Lưỡng cư có đặc điểm nào sau đây?', opts: o4('sống hoàn toàn ở trên cạn suốt đời', 'thân phủ vảy sừng khô, đẻ trứng cạn', 'vừa sống ở nước vừa sống ở trên cạn', 'thân phủ lông vũ, chi trước là cánh'), ans: 'C', why: 'Chữ "lưỡng cư" nghĩa là sống được ở cả hai môi trường: giai đoạn nòng nọc ở nước, giai đoạn trưởng thành lên cạn nhưng vẫn cần nơi ẩm.' },
    { sec: 'Vai trò động vật', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Vai trò nào sau đây là của động vật có xương sống đối với con người?', opts: o4('phân hủy xác sinh vật thành chất khoáng', 'cung cấp thực phẩm, sức kéo và dược liệu', 'giúp hoa của cây trồng được thụ phấn', 'tạo ra khí oxygen cho bầu khí quyển'), ans: 'B', why: 'Trâu bò cho sức kéo, gia súc gia cầm và cá cho thực phẩm, nhiều loài còn cho dược liệu. Phân hủy xác là việc của vi khuẩn và nấm, thụ phấn chủ yếu do côn trùng.' },
    { sec: 'Khóa lưỡng phân', lvl: 'NC', name: 'Câu 24', pts: 1, text: 'Trong một khóa lưỡng phân về động vật có xương sống, đặc điểm "nuôi con bằng sữa mẹ" được dùng để tách riêng:', opts: o4('lớp Chim ra khỏi các lớp còn lại', 'lớp Cá ra khỏi các lớp còn lại', 'lớp Bò sát ra khỏi các lớp còn lại', 'lớp Thú ra khỏi các lớp còn lại'), ans: 'D', why: 'Trong năm lớp động vật có xương sống, chỉ lớp Thú có tuyến sữa nuôi con. Vì vậy cặp đặc điểm "nuôi con bằng sữa / không nuôi con bằng sữa" tách ngay lớp Thú ra khỏi bốn lớp kia. Bẫy ở phương án A: chim mớm mồi cho con chứ không tiết sữa.' },
    { sec: 'Bảo vệ đa dạng sinh học', lvl: 'VD', name: 'Câu 25', pts: 1, text: 'Để góp phần bảo vệ đa dạng sinh học ở địa phương, học sinh nên làm việc nào sau đây?', opts: o4('bắt chim non về nuôi làm cảnh ở trong lồng', 'đốt rơm rạ và cỏ khô ở ven rừng cho sạch', 'không săn bắt và tuyên truyền bảo vệ động vật hoang dã', 'thả các loài vật nuôi lạ vào trong rừng tự nhiên'), ans: 'C', why: 'Không săn bắt và vận động mọi người cùng bảo vệ là việc học sinh làm được ngay. Bắt chim non, đốt ven rừng hay thả loài lạ vào rừng đều gây hại cho hệ sinh thái.' },
    { sec: 'Lớp Thú', lvl: 'NB', name: 'Câu 26', pts: 1, text: 'Động vật nào sau đây đẻ con và nuôi con bằng sữa?', opts: o4('con mèo nhà', 'con cá chép', 'con rắn nước', 'con chim sẻ'), ans: 'A', why: 'Mèo thuộc lớp Thú nên đẻ con và nuôi con bằng sữa. Cá chép, rắn nước và chim sẻ đều đẻ trứng.' },
    { sec: 'Lớp Bò sát', lvl: 'TH', name: 'Câu 27', pts: 1, text: 'Vì sao cá sấu là bò sát chứ không phải lưỡng cư?', opts: o4('vì cá sấu có thể bơi rất nhanh ở trong nước', 'vì cá sấu có da khô phủ vảy sừng, đẻ trứng trên cạn', 'vì cá sấu có kích thước cơ thể rất lớn và nặng', 'vì cá sấu ăn thịt các loài động vật khác trong đầm'), ans: 'B', why: 'Cá sấu tuy sống nhiều ở nước nhưng có da khô phủ vảy sừng và đẻ trứng vỏ dai trên cạn — đó là đặc điểm của bò sát. Lưỡng cư thì da trần ẩm và đẻ trứng trong nước.' },
    { sec: 'Phân tích khóa lưỡng phân', lvl: 'NC', name: 'Câu 28', pts: 1, text: 'Cho ba con vật: cá chép, ếch đồng, chim bồ câu. Nếu chia theo cặp đặc điểm "hô hấp bằng mang / không hô hấp bằng mang" thì:', opts: o4('cả ba con vật đều thuộc nhóm hô hấp bằng mang', 'ếch đồng và chim bồ câu thuộc nhóm hô hấp bằng mang', 'chỉ có chim bồ câu thuộc nhóm hô hấp bằng mang', 'chỉ có cá chép thuộc nhóm hô hấp bằng mang'), ans: 'D', why: 'Cá chép hô hấp bằng mang suốt đời. Ếch đồng trưởng thành thở bằng phổi và da (chỉ giai đoạn nòng nọc mới có mang), chim bồ câu thở bằng phổi. Bẫy ở phương án B: nhiều bạn thấy ếch sống được dưới nước liền cho rằng ếch trưởng thành vẫn thở bằng mang.' },
    { sec: 'Lớp Chim', lvl: 'NB', name: 'Câu 29', pts: 1, text: 'Chim di chuyển chủ yếu bằng cách:', opts: o4('bay nhờ đôi cánh', 'bơi nhờ đôi vây', 'bò nhờ bốn chân', 'trườn nhờ thân dài'), ans: 'A', why: 'Phần lớn các loài chim bay nhờ đôi cánh do chi trước biến đổi thành; một số ít như đà điểu, chim cánh cụt thì chạy hoặc bơi.' },
    { sec: 'Đặc điểm chung', lvl: 'TH', name: 'Câu 30', pts: 1, text: 'Đặc điểm chung của động vật có xương sống là:', opts: o4('cơ thể luôn được phủ một lớp lông mao dày', 'cơ thể có vỏ cứng bằng chitin bao bọc ở ngoài', 'cơ thể có bộ xương trong, có xương sống ở lưng', 'cơ thể mềm, không phân đốt, sống ở dưới nước'), ans: 'C', why: 'Dấu hiệu chung của cả năm lớp là có bộ xương trong, trong đó cột sống chạy dọc lưng làm trụ nâng đỡ cơ thể. Lông mao chỉ có ở thú, còn vỏ chitin là của chân khớp.' },
  ],
},

];

